window.JPG=window.JPG||{};JPG.N5=[{"id":"g5_011","t":"AはBが～","ko":"A는 B가 ~하다","cat":"조사","conn":[{"w":"명사 + 신체·부분","f":"ぞう + は + 鼻 + が + 長い"},{"w":"명사 + 성질","f":"この店 + は + ケーキ + が + おいしい"},{"w":"사람 + 好き/上手 등","f":"わたし + は + 音楽 + が + 好きです"}],"rule":["이야기의 주제 A에 は를 붙인다.","A의 부분·특징 B(또는 好き·上手 등의 대상)에 が를 붙인다.","마지막에 B를 설명하는 형용사·술어를 놓는다.","뜻의 구조는 'A에 대해 말하면 → B가 ~하다'이다(ぞうは鼻が長い = ぞうの鼻が長い를 주제화한 것)."],"why":"は는 문장 전체의 주제를, が는 술어의 주어를 나타낸다. 'ぞうの鼻が長い'에서 'ぞうの'를 주제로 꺼내 は를 붙인 것으로 설명된다.","nu":"회화·문장 모두 쓰는 기본 구조. 한국어 '코끼리는 코가 길다'와 구조가 같아 이해하기 쉽지만, B 자리에 は를 쓰면(鼻は) 다른 부분과 대비하는 뜻이 된다. 好き·嫌い·上手·下手·わかる 등의 대상도 を가 아니라 が로 나타낸다.","cmp":[{"g":"AのBが～","d":"뜻은 비슷하나 A를 주제로 내세우지 않고 한 덩어리로 말한다."}],"ex":[{"jp":"ぞうは鼻[はな]が長[なが]いです。","ko":"코끼리는 코가 길어요."},{"jp":"姉[あね]は髪[かみ]がとても長[なが]いです。","ko":"언니는 머리가 아주 길어요."},{"jp":"わたしは日本[にほん]の料理[りょうり]が好[す]きです。","ko":"저는 일본 요리를 좋아해요."}],"dr":[{"t":"make","q":"うさぎ / 耳 / 長い → AはBが～","a":"うさぎは耳が長い","hint":"주제 A + は, 부분 B + が, 형용사."},{"t":"make","q":"この町 / 公園 / きれいです → AはBが～","a":"この町は公園がきれいです","hint":"주제에 は, 특징에 が."},{"t":"fill","q":"兄[あに]は歌[うた]（　）上手[じょうず]です。","a":"が","opts":["が","を","より","へ"]}],"src":["https://konomu.github.io/wa-ga-other"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_022","t":"名詞か名詞か～","ko":"~이나 ~(이나), ~든 ~든 (둘 중 하나)","cat":"조사","conn":[{"w":"명사","f":"コーヒー + か + 紅茶 + か"},{"w":"명사(뒤 か 생략)","f":"電車 + か + バス + で"},{"w":"동사 보통형","f":"行く + か + 行かない + か"}],"rule":["선택지가 되는 첫 번째 명사 뒤에 か를 붙인다(コーヒーか).","두 번째 명사를 놓고 그 뒤에도 か를 붙일 수 있다(コーヒーか紅茶か).","두 번째 か는 생략할 수 있고, 그 경우 뒤에 오는 조사를 그대로 붙인다(コーヒーか紅茶を飲みます).","활용 변화는 없다. 'Aか Bか、どちら…'처럼 고르게 하는 문장에 자주 쓴다."],"why":"か는 원래 의문을 나타내는 조사로, 여러 개를 늘어놓을 때는 '그 가운데 하나'를 고르는 뜻이 된다.","nu":"회화·문장 모두 쓴다. と(A와 B 둘 다)와 달리 か는 '둘 중 하나'만 해당한다. 두 번째 か를 넣으면 선택지를 하나하나 따져 보는 느낌이 강해진다(赤か青か、迷っています). 한국어 '~이나'는 '정도'의 뜻(커피나 마실까)도 있지만 그 뜻은 でも를 쓴다.","cmp":[{"g":"AとB","d":"A와 B 둘 다 해당. AかB는 둘 중 하나."},{"g":"AやB","d":"예를 들어 몇 개를 늘어놓음(그 밖에도 있음). か는 고르기."}],"ex":[{"jp":"コーヒーか紅茶[こうちゃ]か、どちらがいいですか。","ko":"커피랑 홍차 중 어느 쪽이 좋으세요?"},{"jp":"土曜日[どようび]か日曜日[にちようび]に会[あ]いましょう。","ko":"토요일이나 일요일에 만나요."},{"jp":"パーティーに行[い]くか行[い]かないか、まだ決[き]めていません。","ko":"파티에 갈지 안 갈지 아직 정하지 않았어요."}],"dr":[{"t":"make","q":"コーヒー / 紅茶 → ～か～か、どちらがいいですか","a":"コーヒーか紅茶か、どちらがいいですか","hint":"각 명사 뒤에 か를 붙인다."},{"t":"make","q":"電車 / バス / 行きます → ～か～で行きます","a":"電車かバスで行きます","hint":"첫 명사 뒤에 か, 두 번째 か는 생략하고 수단의 で."},{"t":"fill","q":"ペン（　）鉛筆[えんぴつ]で書[か]いてください。","a":"か","opts":["か","を","へ","に"]}],"src":["https://aiueo.cc/pages_v2/en/grammar/web/22.php"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_025","t":"NからNまで","ko":"~부터 ~까지, ~에서 ~까지","cat":"조사","conn":[{"w":"명사(시간)","f":"9時 + から + 5時 + まで"},{"w":"명사(장소)","f":"東京 + から + 大阪 + まで"},{"w":"명사(범위·순서)","f":"5ページ + から + 10ページ + まで"},{"w":"단독 사용","f":"10時 + からです / 3時 + までです"}],"rule":["출발점(시간·장소·범위의 시작)이 되는 명사1 뒤에 조사 から를 붙인다.","도착점(끝)이 되는 명사2 뒤에 조사 まで를 붙인다.","그 뒤에 동사(働きます, 行きます 등)나 です를 이어 쓴다. 명사의 형태는 바뀌지 않는다.","から와 まで는 각각 따로 쓸 수도 있다(10時からです)."],"why":"から는 기점(시작점), まで는 종점(끝점)을 나타내는 조사로, 둘을 짝지어 쓰면 시작부터 끝까지의 범위가 된다.","nu":"회화·문장 모두 쓰는 기본 표현. 시간과 장소 둘 다 같은 형태로 쓴다. 한국어는 시간엔 '부터', 장소엔 '에서'로 나누지만 일본어는 둘 다 から. 'まで(까지 계속)'와 'までに(그때까지 마감)'를 혼동하기 쉬우니 주의.","cmp":[{"g":"～までに","d":"まで는 그 시점까지 동작·상태가 계속됨, までに는 그 시점 전에 한 번 끝내야 하는 기한."}],"ex":[{"jp":"毎日[まいにち]、9時[くじ]から5時[ごじ]まで働[はたら]きます。","ko":"매일 9시부터 5시까지 일합니다."},{"jp":"家[いえ]から駅[えき]まで歩[ある]いて10分[じっぷん]です。","ko":"집에서 역까지 걸어서 10분입니다."},{"jp":"月曜日[げつようび]から金曜日[きんようび]まで学校[がっこう]があります。","ko":"월요일부터 금요일까지 학교가 있어요."}],"dr":[{"t":"make","q":"東京 / 大阪 / 行きます → ～から～まで","a":"東京から大阪まで行きます","hint":"출발점 명사 + から, 도착점 명사 + まで, 그다음 동사."},{"t":"make","q":"1時 / 3時 / 休みです → ～から～まで","a":"1時から3時まで休みです","hint":"시작 시각 + から, 끝 시각 + まで, 마지막에 です."},{"t":"fill","q":"銀行[ぎんこう]は9時[くじ]から3時[さんじ]（　）です。","a":"まで","opts":["まで","から","までに","より"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_3.pdf"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_030","t":"Nで","ko":"~에서 (장소), ~로 (수단·도구)","cat":"조사","conn":[{"w":"명사(동작 장소)","f":"図書館 + で + 勉強する"},{"w":"명사(교통수단)","f":"バス + で + 行く"},{"w":"명사(도구)","f":"鉛筆 + で + 書く"},{"w":"명사(언어)","f":"日本語 + で + 話す"}],"rule":["동작이 일어나는 장소 명사 뒤에 で를 붙인다(図書館で勉強する).","수단·도구·언어를 나타내는 명사 뒤에도 같은 で를 붙인다(バスで行く).","명사·で 모두 형태가 바뀌지 않고, 뒤에 동작 동사를 잇는다."],"why":"で는 그 동작을 하는 데 필요한 것, 곧 동작의 장소나 사용하는 수단을 나타내는 조사다.","nu":"회화·문장 모두 쓰는 기본 조사. 한국어 '~에서'와 '~(으)로' 두 가지에 대응한다. 존재(いる・ある・住む)의 장소에는 で가 아니라 に를 쓴다(東京に住む / 東京で働く). 목적지에도 で가 아니라 に・へ를 쓴다.","cmp":[{"g":"～に","d":"に는 존재 장소·목적지(東京に住む, 駅に行く), で는 동작이 일어나는 장소(東京で勉強する)."}],"ex":[{"jp":"図書館[としょかん]で勉強[べんきょう]します。","ko":"도서관에서 공부해요."},{"jp":"バスで学校[がっこう]に行[い]きます。","ko":"버스로 학교에 가요."},{"jp":"鉛筆[えんぴつ]で名前[なまえ]を書[か]いてください。","ko":"연필로 이름을 써 주세요."}],"dr":[{"t":"make","q":"公園 / 遊びます → ～で","a":"公園で遊びます","hint":"동작 장소 명사 뒤에 で."},{"t":"make","q":"電車 / 来ました → ～で","a":"電車で来ました","hint":"교통수단 명사 뒤에 で."},{"t":"fill","q":"友達[ともだち]はレストラン（　）働[はたら]いています。","a":"で","opts":["で","に","を","へ"]}],"src":["https://bunpro.jp/grammar_points/で"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_031","t":"Nと","ko":"~와/과 (나열), ~와 함께","cat":"조사","conn":[{"w":"명사 + 명사(나열)","f":"リンゴ + と + バナナ"},{"w":"사람 명사(함께)","f":"友達 + と + 行く"},{"w":"사람 명사(+一緒に)","f":"母 + と + 一緒に + 旅行する"},{"w":"상호 동작 동사","f":"先生 + と + 話す / 友達 + と + 会う"}],"rule":["명사1 뒤에 と를 붙이고 명사2를 이어 '명사1과 명사2'로 나열한다(リンゴとバナナ).","함께 하는 사람 명사 뒤에 と를 붙이고 동사를 이으면 '~와 같이 ~하다'가 된다(友達と行く).","명사·と 모두 형태가 바뀌지 않는다. '함께'를 강조할 때는 と 뒤에 一緒に를 넣는다."],"why":"と는 두 명사를 대등하게 묶는 조사로, 사람에 붙으면 그 사람이 동작에 함께 참여함을 나타낸다.","nu":"회화·문장 모두 쓰는 기본 조사. 나열의 と는 말한 것이 전부임을 나타내므로, 일부만 예로 들 때는 や를 쓴다. と는 명사끼리만 잇고, 문장(동사·형용사)을 '~고'로 이을 때는 쓰지 않는다(て형 사용). 마지막 명사 뒤에는 보통 と를 붙이지 않는다.","cmp":[{"g":"～や","d":"や는 여럿 중 몇 개만 예로 드는 나열, と는 빠짐없이 전부를 드는 나열."},{"g":"～に(相手)","d":"友達と話す는 서로 주고받는 대화, 友達に話す는 한쪽이 상대에게 일방적으로 말함."}],"ex":[{"jp":"リンゴとバナナを買[か]いました。","ko":"사과와 바나나를 샀어요."},{"jp":"日曜日[にちようび]に友達[ともだち]と映画[えいが]を見[み]ます。","ko":"일요일에 친구와 영화를 봐요."},{"jp":"父[ちち]と一緒[いっしょ]に旅行[りょこう]しました。","ko":"아버지와 함께 여행했어요."}],"dr":[{"t":"make","q":"パン / 牛乳 / を買いました → ～と～","a":"パンと牛乳を買いました","hint":"명사1 + と + 명사2, 그다음 を와 동사."},{"t":"make","q":"妹 / 公園に行きます → ～と (함께)","a":"妹と公園に行きます","hint":"함께 하는 사람 명사 뒤에 と."},{"t":"fill","q":"昨日[きのう]、駅[えき]で先生[せんせい]（　）会[あ]いました。","a":"と","opts":["と","を","で","から"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A8-with"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_032","t":"Nに","ko":"~에 (시각·도착점), ~에게 (상대)","cat":"조사","conn":[{"w":"시각·날짜·요일","f":"6時 + に + 起きる / 日曜日 + に"},{"w":"장소(도착점)","f":"日本 + に + 行く"},{"w":"사람(상대)","f":"友達 + に + あげる"},{"w":"장소(존재)","f":"部屋 + に + いる / 東京 + に + 住む"}],"rule":["동작이 일어나는 구체적 시각·날짜 명사 뒤에 に를 붙인다(6時に起きる).","이동의 도착점이 되는 장소 명사 뒤에 に를 붙인다(日本に行く).","주거나 말하는 상대(사람) 명사 뒤에 に를 붙인다(友達にあげる).","今日・明日・昨日・今・毎日처럼 기준에 따라 정해지는 시간 말에는 に를 붙이지 않는다."],"why":"に는 동작이 가 닿는 끝점(도착점·상대·시점)을 나타내는 조사다.","nu":"회화·문장 모두 쓰는 기본 조사. 한국어 '~에'와 '~에게' 둘 다에 대응한다. '明日に行きます'처럼 상대적 시간 말에 に를 붙이는 실수가 많다. 동작이 일어나는 장소에는 に가 아니라 で를 쓴다(図書館で勉強する). 도착점의 に는 へ로 바꿔도 된다.","cmp":[{"g":"～で","d":"で는 동작이 일어나는 장소, に는 존재 장소·도착점."},{"g":"～へ","d":"へ는 이동의 방향, に는 도착점. 行く・来る・帰る에는 둘 다 쓸 수 있다."}],"ex":[{"jp":"毎朝[まいあさ]6時[ろくじ]に起[お]きます。","ko":"매일 아침 6시에 일어나요."},{"jp":"来年[らいねん]、日本[にほん]に行[い]きます。","ko":"내년에 일본에 가요."},{"jp":"彼女[かのじょ]に花[はな]をあげました。","ko":"여자친구에게 꽃을 줬어요."}],"dr":[{"t":"make","q":"7時 / 寝ます → ～に","a":"7時に寝ます","hint":"구체적 시각 뒤에 に."},{"t":"make","q":"先生 / 手紙を書きます → ～に (상대)","a":"先生に手紙を書きます","hint":"상대가 되는 사람 뒤에 に."},{"t":"fill","q":"毎年[まいとし]、夏休[なつやす]みに京都[きょうと]（　）行[い]きます。","a":"に","opts":["に","で","を","と"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei01_4.pdf"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_033","t":"Nに帰ります","ko":"~에 돌아갑니다/돌아옵니다, ~(집)에 갑니다","cat":"조사","conn":[{"w":"장소 명사","f":"家 + に + 帰ります"},{"w":"자기 나라·고향","f":"国 + に + 帰ります"},{"w":"へ로 대체","f":"うち + へ + 帰ります"},{"w":"과거·부정","f":"家に + 帰りました / 帰りません"}],"rule":["돌아갈 장소 명사 뒤에 도착점의 に를 붙인다(家に).","帰る는 る로 끝나지만 1그룹(5단) 동사다. 어미 る를 い단 り로 바꾼다(帰る → 帰り).","り 뒤에 ます를 붙여 帰ります가 된다."],"why":"帰る는 자기 집이나 원래 있던 곳으로 돌아간다는 뜻의 동사이고, に는 그 도착점을 나타낸다.","nu":"회화·문장 모두 쓰는 기본 표현. 帰る는 1그룹이라 '帰ます'가 아니라 帰ります가 맞다(한국인이 자주 틀리는 부분). 자기 집·나라·고향처럼 '원래 있던 곳'에만 쓰고, 처음 가는 곳에는 行く를 쓴다. 한국어 '집에 가다'는 일본어로 家に帰る가 자연스럽다.","cmp":[{"g":"～に行きます","d":"行く는 원래 장소가 아닌 곳으로 감. 帰る는 자기 집·고향 등 본래 자리로 돌아감."}],"ex":[{"jp":"6時[ろくじ]に家[いえ]に帰[かえ]ります。","ko":"6시에 집에 가요."},{"jp":"夏休[なつやす]みに国[くに]へ帰[かえ]りました。","ko":"여름 방학에 고국으로 돌아갔어요."},{"jp":"今日[きょう]は早[はや]くうちに帰[かえ]りたいです。","ko":"오늘은 일찍 집에 가고 싶어요."}],"dr":[{"t":"make","q":"家 / 帰る → ～に帰ります","a":"家に帰ります","hint":"장소 + に, 帰る의 る를 り로 바꾸고 ます."},{"t":"make","q":"国 / 帰る(과거 정중형) → ～に帰りました","a":"国に帰りました","hint":"帰り + ました."},{"t":"fill","q":"授業[じゅぎょう]が終[お]わったら、まっすぐうち（　）帰[かえ]ります。","a":"に","opts":["に","を","で","が"]}],"src":["https://www.weblio.jp/content/帰る","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei02_5.pdf"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_034","t":"Nにします","ko":"~로 하겠습니다 (선택·결정)","cat":"조사","conn":[{"w":"명사(음식·물건)","f":"すし + に + します"},{"w":"명사(장소·날짜)","f":"このレストラン + に + します / 日曜日 + に + します"},{"w":"의문사","f":"何 + に + しますか"},{"w":"보통형","f":"コーヒー + に + する"}],"rule":["고른 것을 나타내는 명사 뒤에 조사 に를 붙인다(すしに).","する는 3그룹 불규칙 동사로, ます를 붙일 때 する가 し로 바뀐다(する → し).","し 뒤에 ます를 붙여 します가 된다(すしにします)."],"why":"する(하다)에 결과를 나타내는 に가 붙어 '~로 하다', 곧 여럿 중에서 그것으로 정한다는 뜻이 된다. 말하는 사람이 스스로 결과를 정한다는 점이 특징이다.","nu":"회화에서 자주 쓰는 표현. 주문·쇼핑처럼 여러 선택지 중에서 그 자리에서 정할 때 많이 쓴다(何にしますか / コーヒーにします). 동사를 고를 때는 명사가 아니라 '동사 사전형 + ことにする'를 쓴다.","cmp":[{"g":"～になります","d":"にする는 내가 골라 정하는 것, になる는 저절로 그렇게 바뀌거나 정해지는 것."}],"ex":[{"jp":"昼[ひる]ご飯[はん]はすしにします。","ko":"점심은 초밥으로 할게요."},{"jp":"飲[の]み物[もの]は何[なに]にしますか。","ko":"음료는 뭘로 하시겠어요?"},{"jp":"この赤[あか]いかばんにします。","ko":"이 빨간 가방으로 할게요."}],"dr":[{"t":"make","q":"紅茶 / する → ～にします","a":"紅茶にします","hint":"명사 + に, する는 し로 바꾸고 ます."},{"t":"make","q":"何 / する → ～にしますか","a":"何にしますか","hint":"의문사 何 + に + します + か."},{"t":"fill","q":"A「ケーキはどれにしますか。」B「このチョコレートのケーキ（　）します。」","a":"に","opts":["に","を","で","が"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%99%E3%82%8B"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_035","t":"Nになります","ko":"~이/가 됩니다 (변화)","cat":"조사","conn":[{"w":"명사","f":"医者 + に + なります"},{"w":"な형용사(어간)","f":"きれい + に + なります"},{"w":"い형용사(い→く)","f":"寒い → 寒く + なります"},{"w":"いい(예외)","f":"いい → よく + なります"}],"rule":["변화의 결과가 되는 명사 뒤에 に를 붙인다(医者に). な형용사는 어간에 바로 に를 붙인다(きれいに).","い형용사는 に를 쓰지 않고 끝의 い를 く로 바꾼다(寒い → 寒く). いい는 よく가 된다.","なる는 1그룹 동사다. 어미 る를 い단 り로 바꾼다(なる → なり).","り 뒤에 ます를 붙여 なります가 된다(医者になります)."],"why":"なる는 '되다'라는 뜻의 동사이고, に는 변화의 결과(도착점)를 나타낸다.","nu":"회화·문장 모두 쓰는 기본 표현. 한국어 '의사가 되다'에 끌려 '医者がなる'라고 하기 쉬운데, 결과에는 が가 아니라 に를 쓴다. 저절로 바뀌는 변화를 나타내며, 누군가 의도해서 바꿀 때는 にする・くする를 쓴다. 시간·나이가 되는 것에도 쓴다(20歳になります).","cmp":[{"g":"～にします","d":"になる는 저절로 그렇게 바뀜, にする는 사람이 골라서·의도해서 그렇게 함."}],"ex":[{"jp":"兄[あに]は来年[らいねん]、医者[いしゃ]になります。","ko":"형은 내년에 의사가 돼요."},{"jp":"部屋[へや]がきれいになりました。","ko":"방이 깨끗해졌어요."},{"jp":"もうすぐ暗[くら]くなります。","ko":"이제 곧 어두워져요."}],"dr":[{"t":"make","q":"先生 / なる → ～になります","a":"先生になります","hint":"명사 + に, なる의 る를 り로 바꾸고 ます."},{"t":"make","q":"暑い / なる → (い형용사) なります","a":"暑くなります","hint":"い형용사는 い를 く로 바꾸고 なります (に 없음)."},{"t":"fill","q":"妹[いもうと]は4月[しがつ]から大学生[だいがくせい]（　）なります。","a":"に","opts":["に","が","を","で"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%AA%E3%82%8B-%E3%81%8F%E3%81%AA%E3%82%8B"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_036","t":"Nに来ます","ko":"~에 옵니다","cat":"조사","conn":[{"w":"장소 명사","f":"うち + に + 来ます"},{"w":"へ로 대체","f":"学校 + へ + 来ます"},{"w":"과거·부정","f":"日本に + 来ました / 来ません"},{"w":"목적(동사 ます형 어간)","f":"遊び + に + 来ます"}],"rule":["오는 도착점 장소 명사 뒤에 に를 붙인다(うちに).","来る(くる)는 3그룹 불규칙 동사로, ます를 붙일 때 읽기가 く에서 き로 바뀌고 る는 떨어진다(来る(くる) → 来(き)).","来(き) 뒤에 ます를 붙여 来ます(きます)가 된다. 한자는 그대로이고 읽기만 바뀐다."],"why":"来る는 말하는 사람이 있는 쪽으로 이동해 온다는 동사이고, に는 그 도착점을 나타낸다.","nu":"회화·문장 모두 쓰는 기본 표현. 来る는 불규칙이라 '来ります'가 아니라 来ます(きます)가 맞고, 부정은 来ません(きません), 과거는 来ました(きました)다. 말하는 사람 쪽으로 오는 이동에만 쓰며, 말하는 사람이 다른 곳으로 가는 것은 行く다. 도착점의 に는 へ로 바꿔도 된다.","cmp":[{"g":"～に行きます","d":"行く는 지금 있는 곳에서 멀어지는 이동, 来る는 말하는 사람 쪽으로 다가오는 이동."}],"ex":[{"jp":"明日[あした]、友達[ともだち]がうちに来[き]ます。","ko":"내일 친구가 우리 집에 와요."},{"jp":"先生[せんせい]は8時[はちじ]に学校[がっこう]へ来[き]ました。","ko":"선생님은 8시에 학교에 오셨어요."},{"jp":"去年[きょねん]、日本[にほん]に来[き]ました。","ko":"작년에 일본에 왔어요."}],"dr":[{"t":"make","q":"学校 / 来る → ～に来ます","a":"学校に来ます","hint":"장소 + に, 来る(くる)는 来(き) + ます."},{"t":"make","q":"日本 / 来る(과거 정중형) → ～に来ました","a":"日本に来ました","hint":"来る → 来(き) + ました."},{"t":"fill","q":"今晩[こんばん]、兄[あに]が私[わたし]の部屋[へや]（　）来[き]ます。","a":"に","opts":["に","を","で","と"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei02_5.pdf"],"vf":1,"u":1,"g":1,"gp":"gg_N5_00"},{"id":"g5_037","t":"～に行きます","ko":"~에 갑니다","cat":"조사","conn":[{"w":"명사(장소)","f":"学校 + に + 行きます"},{"w":"명사(장소·사람 집)","f":"友だちの家 + に + 行きます"},{"w":"의문사","f":"どこ + に + 行きますか"},{"w":"다른 이동 동사","f":"日本 + に + 来ます / 家 + に + 帰ります"}],"rule":["가는 곳(장소 명사)에 조사 に를 붙인다.","그 뒤에 이동 동사 行きます(가다)를 놓는다. 来ます(오다)·帰ります(돌아가다)도 같은 틀이다.","명사와 동사 모두 활용 변화는 없고, 어순은 '장소 + に + 行きます'다.","に 자리에 へ를 써도 되며, 이때 へ는 '에'로 읽는다."],"why":"に는 이동이 끝나는 도착점(귀착점)을 나타내는 조사이고, へ는 향하는 방향을 나타낸다. 그래서 둘 다 행선지를 나타낼 수 있지만 に는 '도착하는 곳', へ는 '그쪽으로'라는 느낌이 있다.","nu":"회화·문장 모두 쓰는 기본 표현. に는 말과 글 모두 흔하고 へ는 조금 더 딱딱하거나 글에서 자주 보인다. 한국어 '학교에서 가요'처럼 で를 쓰면 틀린다(学校で行きます는 X). 또 '학교를 가요'에 끌려 を를 쓰지 않도록 주의(学校を行きます는 X).","cmp":[{"g":"～へ行きます","d":"へ는 방향을 강조한다. 행선지라는 뜻은 거의 같아 바꿔 쓸 수 있는 경우가 많다."},{"g":"명사(행동)に行きます","d":"買い物に行きます처럼 に 앞에 장소가 아니라 행동 명사가 오면 '~하러 가다'라는 목적을 나타낸다."}],"ex":[{"jp":"毎朝[まいあさ]、八時[はちじ]に学校[がっこう]に行[い]きます。","ko":"매일 아침 8시에 학교에 가요."},{"jp":"明日[あした]、友[とも]だちの家[いえ]に行[い]きます。","ko":"내일 친구 집에 가요."},{"jp":"夏休[なつやす]みにどこに行[い]きますか。","ko":"여름 방학에 어디에 가요?"}],"dr":[{"t":"make","q":"スーパー / 行きます → ～に行きます","a":"スーパーに行きます","hint":"장소 명사 뒤에 に, 그다음 行きます."},{"t":"make","q":"図書館 / 行きました (과거) → ～に行きました","a":"図書館に行きました","hint":"과거는 行きます를 行きました로만 바꾼다. に는 그대로."},{"t":"fill","q":"日曜日[にちようび]にデパート（　）行[い]きます。","a":"に","opts":["に","を","で","が"]}],"src":["https://oercollective.caul.edu.au/japanese/?p=3095","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei05_7.pdf"],"vf":1,"u":2,"g":1,"gp":"gg_N5_00"},{"id":"g5_039","t":"～の前に","ko":"~의 앞에","cat":"조사","conn":[{"w":"명사(장소·건물)","f":"駅 + の + 前に"},{"w":"명사(사람)","f":"私 + の + 前に"},{"w":"의문사","f":"どこ + の + 前に"}],"rule":["기준이 되는 장소·사물·사람 명사에 조사 の를 붙인다.","그 뒤에 前(まえ, 앞)과 조사 に를 붙여 '~의 앞에'를 만든다.","뒤에는 あります·います(있다)나 止めます·立ちます처럼 그 자리에 놓이는 동사가 온다.","활용 변화는 없다."],"why":"前는 '앞'이라는 위치 명사이고, に는 무엇이 있거나 놓이는 장소를 나타낸다. 명사끼리 이어지므로 사이에 の가 들어간다.","nu":"기본 표현. 그 자리에서 '동작'을 할 때는 に가 아니라 で를 써서 駅の前で待ちます(역 앞에서 기다려요)라고 한다. 같은 형태 '~の前に'가 시간 명사와 쓰이면 '~ 전에'라는 뜻도 되므로 앞 명사가 장소인지 행사인지 보고 구별한다.","cmp":[{"g":"～の前で","d":"で는 동작이 일어나는 장소. 前に는 존재·도착 위치(ある, いる, 止める), 前で는 행동(待つ, 写真を撮る)."},{"g":"～の前に (시간)","d":"食事の前に처럼 행사·활동 명사와 쓰이면 '~ 전에'. 반대는 ～のあとで."}],"ex":[{"jp":"駅[えき]の前[まえ]にコンビニがあります。","ko":"역 앞에 편의점이 있어요."},{"jp":"家[いえ]の前[まえ]に車[くるま]を止[と]めてください。","ko":"집 앞에 차를 세워 주세요."},{"jp":"私[わたし]の前[まえ]に背[せ]の高[たか]い人[ひと]がいます。","ko":"제 앞에 키 큰 사람이 있어요."}],"dr":[{"t":"make","q":"銀行 / 自転車があります → ～の前に～","a":"銀行の前に自転車があります","hint":"장소 + の + 前に, 그다음 있는 것 + があります."},{"t":"make","q":"学校 → ～の前に","a":"学校の前に","hint":"명사 뒤에 の, 그다음 前に."},{"t":"fill","q":"郵便局[ゆうびんきょく]の前[まえ]（　）ポストがあります。","a":"に","opts":["に","を","から","より"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/前に-まえに-mae-ni-meaning","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_4.pdf"],"vf":1,"u":2,"g":1,"gp":"gg_N5_00"},{"id":"g5_040","t":"～は～","ko":"~은/는 (주제)","cat":"조사","conn":[{"w":"명사","f":"私 + は + 学生です"},{"w":"지시어","f":"これ / この本 + は + 面白いです"},{"w":"시간 명사","f":"今 + は + 忙しいです"},{"w":"다른 조사 뒤","f":"日本に + は / 学校で + は"}],"rule":["문장의 주제(무엇에 대해 말하는지)가 되는 명사에 조사 は를 붙인다.","は는 글자는 は로 쓰지만 소리는 '와(わ)'로 읽는다.","그 뒤에 주제에 대한 설명(명사+です, 형용사, 동사)을 쓴다.","활용 변화는 없고, 주어가 곧 주제일 때는 が 자리를 は가 대신한다."],"why":"조사 は는 옛 표기 습관이 남아 は로 쓰고 わ로 읽는다. こんにちは·こんばんは의 は도 원래 같은 조사다.","nu":"가장 기본적인 조사. 한국어 '은/는'과 비슷하지만, 의문사(だれ, 何)가 주어일 때는 は를 쓸 수 없고 が를 쓴다(だれは는 X, だれが来ましたか). 대비('~는 ~지만')의 뜻으로도 쓰인다. 발음을 '하'로 읽는 실수가 많다.","cmp":[{"g":"～が","d":"が는 새 정보나 '바로 그것'을 고를 때. は는 이미 아는 화제를 꺼낼 때."}],"ex":[{"jp":"私[わたし]は韓国人[かんこくじん]です。","ko":"저는 한국인이에요."},{"jp":"この本[ほん]はとても面白[おもしろ]いです。","ko":"이 책은 아주 재미있어요."},{"jp":"今日[きょう]は雨[あめ]が降[ふ]っています。","ko":"오늘은 비가 오고 있어요."}],"dr":[{"t":"make","q":"私 / 学生です → ～は～","a":"私は学生です","hint":"주제 명사 뒤에 は(와로 읽음), 그다음 설명."},{"t":"make","q":"このかばん / 高いです → ～は～","a":"このかばんは高いです","hint":"주제(このかばん) + は + 형용사."},{"t":"fill","q":"田中[たなか]さん（　）先生[せんせい]です。","a":"は","opts":["は","を","へ","で"]}],"src":["https://guidetojapanese.org/learn/complete/topic_particles","https://en.wikibooks.org/wiki/Japanese/Grammar/Basic_Particles"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_041","t":"～も","ko":"~도","cat":"조사","conn":[{"w":"명사(は·が 자리)","f":"彼 + も + 学生です"},{"w":"명사(を 자리)","f":"コーヒー + も + 飲みます"},{"w":"다른 조사 뒤","f":"日本に + も / 公園で + も"},{"w":"AもBも","f":"東京 + も + 大阪 + も"}],"rule":["'~도 마찬가지'인 명사에 조사 も를 붙인다.","は·が·を 자리에서는 그 조사를 빼고 も로 바꾼다(私は -> 私も, 本を -> 本も).","に·で·へ 같은 다른 조사 뒤에는 빼지 않고 뒤에 붙인다(にも, でも).","두 개 이상을 'AもBも'로 나열하면 'A도 B도'가 된다."],"why":"も는 앞에 나온 것과 같은 부류임을 나타내는 조사로, は처럼 주제 역할을 하면서 '~도'의 뜻을 더한다. 그래서 は·が·を와 겹쳐 쓰지 않고 그 자리를 대신한다.","nu":"기본 조사. 私もは, 本をも처럼 は·を와 겹쳐 쓰는 것은 틀린다. 의문사 + も + 부정형은 '아무(것)도 ~않다'가 된다(だれもいません, 何も食べません).","cmp":[{"g":"～は","d":"は는 주제를 꺼낼 뿐이고, も는 '앞의 것과 같다'는 뜻을 더한다."}],"ex":[{"jp":"私[わたし]も日本語[にほんご]を勉強[べんきょう]しています。","ko":"저도 일본어를 공부하고 있어요."},{"jp":"パンも卵[たまご]も食[た]べました。","ko":"빵도 달걀도 먹었어요."},{"jp":"日曜日[にちようび]にも学校[がっこう]に行[い]きます。","ko":"일요일에도 학교에 가요."}],"dr":[{"t":"make","q":"私は学生です。(彼도) → 彼～学生です","a":"彼も学生です","hint":"は를 빼고 그 자리에 も."},{"t":"make","q":"コーヒーを飲みます。(紅茶도) → 紅茶～飲みます","a":"紅茶も飲みます","hint":"を를 빼고 も로 바꾼다."},{"t":"fill","q":"兄[あに]は医者[いしゃ]です。父[ちち]（　）医者[いしゃ]です。","a":"も","opts":["も","を","に","や"]}],"src":["https://en.wikibooks.org/wiki/Japanese/Grammar/Basic_Particles","https://guidetojapanese.org/learn/complete/topic_particles"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_042","t":"～や～など","ko":"~(이)랑 ~ 등","cat":"조사","conn":[{"w":"명사 + 명사","f":"りんご + や + みかん + など"},{"w":"명사 셋 이상","f":"パン + や + 卵 + や + 牛乳 + など"},{"w":"など 생략","f":"本 + や + 雑誌 (+ を読みます)"}],"rule":["예로 드는 첫 명사 뒤에 조사 や를 붙이고 다음 명사를 잇는다.","마지막 명사 뒤에 など를 붙여 '~ 등(그 밖에도 있음)'을 나타낸다.","など는 생략할 수 있고, 뒤에 を·が·に 같은 조사가 이어진다(～などを).","명사는 활용 변화가 없다."],"why":"や는 여럿 중 몇 가지만 예로 드는 나열 조사이고, など는 '그 밖의 것들'을 덧붙여 말하는 말이다. 그래서 둘을 함께 쓰면 '예를 들면 A랑 B 등'이 된다.","nu":"회화·문장 모두 쓴다. 전부를 빠짐없이 말할 때는 や가 아니라 と를 쓴다. 명사끼리만 이을 수 있고, 동사나 형용사를 나열할 때는 쓰지 않는다(그때는 ～たり～たり 등).","cmp":[{"g":"AとB","d":"と는 말한 것이 전부. や는 다른 것도 더 있다는 느낌."}],"ex":[{"jp":"かばんの中[なか]に本[ほん]やノートなどがあります。","ko":"가방 안에 책이랑 공책 등이 있어요."},{"jp":"朝[あさ]はパンや卵[たまご]を食[た]べます。","ko":"아침에는 빵이랑 달걀 같은 걸 먹어요."},{"jp":"デパートやスーパーなどで買[か]い物[もの]をします。","ko":"백화점이나 슈퍼 등에서 장을 봐요."}],"dr":[{"t":"make","q":"りんご / バナナ → ～や～など","a":"りんごやバナナなど","hint":"첫 명사 + や + 둘째 명사 + など."},{"t":"make","q":"机 / いす / あります → ～や～などがあります","a":"机やいすなどがあります","hint":"나열 뒤 など에 조사 が를 붙이고 あります."},{"t":"fill","q":"部屋[へや]にテレビ（　）ベッドなどがあります。","a":"や","opts":["や","を","で","へ"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_4.pdf"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_043","t":"～を～","ko":"~을/를 (동작의 대상)","cat":"조사","conn":[{"w":"명사 + 타동사","f":"本 + を + 読みます"},{"w":"명사 + する 동사","f":"日本語 + を + 勉強します"},{"w":"지시어·의문사","f":"これ / 何 + を + 食べますか"},{"w":"지나가는 장소 + 이동 동사","f":"公園 + を + 散歩します"}],"rule":["동작을 받는 대상(목적어) 명사에 조사 を를 붙인다.","を는 글자는 を로 쓰지만 소리는 '오(お)'와 같이 읽는다.","그 뒤에 食べます·読みます 같은 타동사를 놓는다.","활용 변화는 없고 어순은 '대상 + を + 동사'다. 散歩する·歩く처럼 이동 동사와 쓰면 지나가는 장소를 나타낸다."],"why":"を는 동작이 직접 미치는 대상을 표시하는 조사다. 걷거나 달릴 때는 그 길을 동작이 거쳐 가는 대상으로 보기 때문에 장소에도 を를 쓴다.","nu":"가장 기본적인 조사. 한국어로 '~을/를'이어도 일본어에서는 に나 が를 쓰는 동사가 있다: 友だちに会います(친구를 만나요), バスに乗ります(버스를 타요), 日本語が分かります·すしが好きです. 이런 동사에 を를 쓰는 실수가 많다.","cmp":[{"g":"～が","d":"が는 주어(동작하는 쪽)나 好き·分かる의 대상. を는 동작을 받는 쪽."}],"ex":[{"jp":"毎晩[まいばん]、本[ほん]を読[よ]みます。","ko":"매일 밤 책을 읽어요."},{"jp":"何[なに]を飲[の]みますか。","ko":"뭘 마실래요?"},{"jp":"朝[あさ]、公園[こうえん]を散歩[さんぽ]しました。","ko":"아침에 공원을 산책했어요."}],"dr":[{"t":"make","q":"テレビ / 見ます → ～を～","a":"テレビを見ます","hint":"대상 명사 뒤에 を, 그다음 동사."},{"t":"make","q":"手紙 / 書きました → ～を～","a":"手紙を書きました","hint":"무엇을(手紙) + を + 동사 과거형."},{"t":"fill","q":"毎朝[まいあさ]コーヒー（　）飲[の]みます。","a":"を","opts":["を","に","へ","で"]}],"src":["https://bunpro.jp/grammar_points/21","https://en.wikibooks.org/wiki/Japanese/Grammar/Basic_Particles"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_051","t":"Nに戻ります","ko":"~(원래 곳·상태)로 돌아갑니다","cat":"조사","conn":[{"w":"명사(장소)","f":"席 + に + 戻ります"},{"w":"명사(활동·소속)","f":"仕事 + に + 戻ります"},{"w":"명사(상태)","f":"元 + に + 戻ります"}],"rule":["돌아가는 곳(원래 있던 장소나 상태)을 나타내는 명사 뒤에 조사 に를 붙인다.","그 뒤에 동사 戻る의 정중형 戻ります를 쓴다. 명사의 형태는 바뀌지 않는다.","과거는 戻りました, 반말은 戻る / 戻った로 동사만 활용한다."],"why":"戻る는 '원래 있던 곳이나 원래 상태로 돌아가다'라는 뜻의 동사이고, に는 이동·변화의 도착점을 나타내는 조사다. 그래서 '어디로 되돌아가는지'를 に로 표시한다.","nu":"회화·문장 모두 쓰는 기본 표현. 도착점은 へ로 말할 수도 있다(席へ戻る). 집으로 귀가할 때는 보통 帰る를 쓰고, 戻る는 잠깐 떠났던 출발점(자리, 회사, 방 등)이나 이전 상태로 돌아올 때 잘 맞는다. 한국어 '~로'에 끌려 で나 を를 쓰지 않도록 주의.","cmp":[{"g":"Nに帰ります","d":"帰る는 자기 집·고향 같은 본래 거처로 돌아가는 것, 戻る는 직전에 있던 장소나 원래 상태로 되돌아가는 것."}],"ex":[{"jp":"会議[かいぎ]が終[お]わったら、席[せき]に戻[もど]ります。","ko":"회의가 끝나면 자리로 돌아갑니다."},{"jp":"昼休[ひるやす]みのあと、仕事[しごと]に戻[もど]りました。","ko":"점심시간 후에 일로 돌아왔습니다."},{"jp":"忘[わす]れ物[もの]をしたので、部屋[へや]に戻[もど]ります。","ko":"물건을 두고 와서 방으로 돌아갑니다."}],"dr":[{"t":"make","q":"教室 / 戻ります → Nに戻ります","a":"教室に戻ります","hint":"돌아가는 곳 명사 + に + 戻ります."},{"t":"make","q":"会社 / 戻る(과거 정중형) → Nに戻ります","a":"会社に戻りました","hint":"명사 + に 뒤에 戻ります의 과거 戻りました."},{"t":"fill","q":"トイレのあと、すぐ席[せき]（　）戻[もど]りました。","a":"に","opts":["に","を","で","から"]}],"src":["https://kotobank.jp/word/%E6%88%BB%E3%82%8B-645015"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_071","t":"～が（격조사）","ko":"~이/가 (주어 표시)","cat":"조사","conn":[{"w":"명사","f":"私 + が"},{"w":"의문사","f":"だれ + が、何 + が"},{"w":"좋아함·능력의 대상","f":"紅茶 + が + 好きです / 日本語 + が + できます"},{"w":"존재문","f":"机 + が + あります"}],"rule":["명사 바로 뒤에 が를 붙여 동작·존재·상태의 주어를 나타낸다(私が作りました).","의문사가 주어일 때는 は가 아니라 が를 쓴다(だれが作りましたか).","대답에서도 질문의 의문사 자리에 들어간 말에 が를 붙인다(だれが → 私が).","好き·嫌い·上手·わかる·できる·ほしい 등의 대상도 が로 나타낸다."],"why":"","nu":"は는 이미 아는 화제(~은/는), が는 새로운 정보나 '바로 그것'을 지정할 때 쓴다. 한국어 '이/가'와 비슷하지만 好きです·わかります처럼 한국어로 '을/를'이 되는 대상에도 が를 쓰는 점이 틀리기 쉽다(×紅茶を好きです보다 紅茶が好きです가 기본). 명사를 꾸미는 절 안의 주어도 が로 쓴다(私が作ったケーキ).","cmp":[{"g":"～は","d":"は는 화제 제시(대비), が는 주어 지정·새 정보. 의문사 주어(だれが)와 그 대답에는 が."},{"g":"～を","d":"を는 동작의 목적어. 好き·わかる·できる 등은 목적어처럼 보여도 が를 쓴다."}],"ex":[{"jp":"だれがこのケーキを作[つく]りましたか。","ko":"누가 이 케이크를 만들었어요?"},{"jp":"私[わたし]が作[つく]りました。","ko":"제가 만들었어요."},{"jp":"私[わたし]は紅茶[こうちゃ]が好[す]きです。","ko":"저는 홍차를 좋아해요."}],"dr":[{"t":"make","q":"だれ / 来ましたか → 조사 넣기","a":"だれが来ましたか","hint":"의문사 주어에는 が."},{"t":"make","q":"田中さん / 来ました (だれが来ましたか의 대답)","a":"田中さんが来ました","hint":"대답의 주어에도 が."},{"t":"fill","q":"私[わたし]は日本語[にほんご]（　）少[すこ]しわかります。","a":"が","opts":["が","に","へ","で"]}],"src":["https://kotobank.jp/word/が"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_125","t":"～の","ko":"~의, ~의 것","cat":"조사","conn":[{"w":"명사 + の + 명사 (소유)","f":"私のかばん"},{"w":"명사 + の + 명사 (성질·소속)","f":"日本語の本 / 会社の人"},{"w":"명사 + の (뒤 명사 생략)","f":"これは私のです"},{"w":"명사 + の + 사람 이름 (동격)","f":"友達の田中さん"}],"rule":["앞 명사(주인·성질) 뒤에 の를 붙이고 뒤 명사를 이어 쓴다(私 + の + かばん).","뒤 명사가 이미 나왔거나 분명하면 빼고 の로 끝낸다(私のです = 제 것입니다).","の는 명사 뒤에 붙는다. い형용사(赤いかばん)와 な형용사(きれいなかばん)는 の 없이 명사를 꾸민다."],"why":"","nu":"가장 기본적인 조사로 회화·문장 모두 쓴다. 한국어는 '내 가방', '일본어 책'처럼 '의'를 빼지만 일본어는 명사끼리 이을 때 の를 빼지 않는다(私かばん ×). 반대로 형용사 뒤에 の를 넣는 실수(赤いのかばん ×, きれいのかばん ×)도 많다. '나의 것'은 私ののです가 아니라 私のです.","cmp":[{"g":"な (な형용사 + 명사)","d":"好きな本처럼 な형용사는 な로 명사를 꾸미고, 명사는 の로 명사를 꾸민다."}],"ex":[{"jp":"これは私[わたし]のかばんです。","ko":"이것은 제 가방입니다."},{"jp":"日本語[にほんご]の先生[せんせい]はやさしいです。","ko":"일본어 선생님은 친절합니다."},{"jp":"そのかさは兄[あに]のです。","ko":"그 우산은 형 것입니다."}],"dr":[{"t":"make","q":"先生 + かさ → '선생님의 우산'","a":"先生のかさ","hint":"명사와 명사 사이에 の."},{"t":"make","q":"これは私のかばんです → かばん을 빼고","a":"これは私のです","hint":"뒤 명사를 빼고 の로 끝낸다."},{"t":"fill","q":"これは日本[にほん]（　）車[くるま]です。","a":"の","opts":["の","な","に","を"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AE","https://bunpro.jp/ja/grammar_points/%E3%81%AE-noun-ommission"],"vf":1,"u":2,"g":1,"gp":"gg_N5_01"},{"id":"g5_136","t":"（場所）に～があります","ko":"(장소)에 ~이/가 있습니다","cat":"조사","conn":[{"w":"장소 명사 + に + 사물 + が + あります","f":"公園に池があります"},{"w":"위치 표현(명사の前/上…) + に","f":"駅の前にコンビニがあります"},{"w":"부정","f":"部屋にテレビはありません"},{"w":"의문","f":"かばんに何がありますか"}],"rule":["장소 명사 뒤에 조사 に를 붙여 '어디에'를 나타낸다.","있는 물건 뒤에 조사 が를 붙이고, 마지막에 あります를 둔다.","부정은 あります를 ありません으로 바꾸고, 보통 が를 は로 바꾼다(テレビはありません).","사람·동물처럼 스스로 움직이는 것은 あります 대신 います를 쓴다."],"why":"に는 존재하는 장소를 가리키는 조사이고, ある는 생명이 없는 사물의 존재를 나타내는 동사라서 '장소에 물건이 있다'가 된다.","nu":"기본 존재문으로 회화·문장 모두 쓴다. 처음 알려 주는 정보(무엇이 있는지)는 が로 표시한다. 이미 화제인 물건의 위치를 말할 때는 '물건は 장소に あります'(本は机の上にあります)로 어순과 조사가 바뀐다. 한국어 '있다'는 사람·물건 모두에 쓰지만 일본어는 사물=ある, 사람·동물=いる로 나뉘어 '猫があります'처럼 틀리기 쉽다. 장소 조사를 で로 쓰는 실수(公園で池があります)도 많다.","cmp":[{"g":"（場所）に～がいます","d":"사람·동물 등 살아 움직이는 것의 존재. あります는 사물·식물."},{"g":"～は（場所）にあります","d":"이미 알고 있는 물건이 '어디에' 있는지를 말하는 문형. 초점이 장소."}],"ex":[{"jp":"公園[こうえん]に池[いけ]があります。","ko":"공원에 연못이 있어요."},{"jp":"駅[えき]の前[まえ]にコンビニがあります。","ko":"역 앞에 편의점이 있어요."},{"jp":"わたしの部屋[へや]にテレビはありません。","ko":"제 방에는 텔레비전이 없어요."}],"dr":[{"t":"make","q":"机の上 / 本 → '책상 위에 책이 있어요'","a":"机の上に本があります","hint":"장소 + に, 물건 + が, 끝에 あります."},{"t":"make","q":"部屋にテレビがあります → 부정","a":"部屋にテレビはありません","hint":"あります → ありません, が는 は로."},{"t":"fill","q":"教室[きょうしつ]に時計[とけい]が（　）。","a":"あります","opts":["あります","います","です","します"]}],"src":["https://a1.marugotoweb.jp/en/note_4_7_1.php"],"vf":1,"u":3,"g":1,"gp":"gg_N5_01"},{"id":"g5_014","t":"い形容詞く＋動詞","ko":"~하게 (동사를 꾸밈)","cat":"활용","conn":[{"w":"い형용사","f":"速い → 速く + 走る"},{"w":"い형용사","f":"早い → 早く + 起きる"},{"w":"불규칙 いい","f":"いい → よく + 寝る"}],"rule":["い형용사 끝의 い를 떼어 낸다(速い → 速).","그 자리에 く를 붙여 연용형을 만든다(速 → 速く).","く형 뒤에 동사를 놓으면 '~하게 ~하다'라는 부사 역할을 한다(速く走る).","いい는 예외로 よい에서 와서 よく가 된다(いく는 틀림)."],"why":"く형은 い형용사의 연용형(뒤의 용언에 이어지는 꼴)이라서 동사를 꾸미는 부사처럼 쓰인다. いい의 く형이 よく인 것은 いい가 원래 よい에서 온 말이기 때문이다.","nu":"회화·문장 모두 쓰는 기본 활용. な형용사에는 く를 붙이지 않고 に를 쓴다(きれいに書く). 부사 뒤에 です를 붙이지 않는다. 한국어 '-게'와 거의 대응하지만 '맛있게 먹었다'처럼 결과·감상을 말할 때는 おいしく食べた보다 おいしかった가 자연스러운 경우가 많다.","cmp":[{"g":"な형용사に＋동사","d":"な형용사는 に로 부사가 된다(静かに話す). い형용사는 く."}],"ex":[{"jp":"毎朝[まいあさ]早[はや]く起[お]きます。","ko":"매일 아침 일찍 일어나요."},{"jp":"字[じ]を大[おお]きく書[か]いてください。","ko":"글씨를 크게 써 주세요."},{"jp":"昨日[きのう]はよく寝[ね]ました。","ko":"어제는 푹(잘) 잤어요."}],"dr":[{"t":"make","q":"速い + 走る → ～く＋동사","a":"速く走る","hint":"끝의 い를 く로 바꾸고 동사를 잇는다."},{"t":"make","q":"いい + 寝る → ～く＋동사","a":"よく寝る","hint":"いい는 예외로 よく가 된다."},{"t":"fill","q":"字[じ]を大[おお]き（　）書[か]いてください。","a":"く","opts":["く","に","な","で"]}],"src":["https://sublearn.com/learn/ja/grammar/ja-adjective-adverbial-form","https://www.tofugu.com/japanese-grammar/i-adjective-negative-form-kunai/"],"vf":1,"u":3,"g":1,"gp":"gg_N5_01"},{"id":"g5_015","t":"い形容詞くします","ko":"~게 하다 (상태를 바꾸다)","cat":"활용","conn":[{"w":"い형용사","f":"明るい → 明るく + します"},{"w":"い형용사","f":"短い → 短く + します"},{"w":"불규칙 いい","f":"いい → よく + します"}],"rule":["い형용사 끝의 い를 떼어 낸다(明るい → 明る).","그 자리에 く를 붙인다(明るく).","く형 뒤에 します(する)를 붙여 '누군가가 무엇을 ~하게 만든다'를 나타낸다(明るくします).","대상은 を로 나타낸다(部屋を明るくします). いい는 よくします."],"why":"く형(연용형) + する 구조로, する의 동작주가 의도적으로 대상의 상태를 바꾼다는 뜻이 된다.","nu":"사람이 일부러 바꿀 때 쓴다. 저절로 바뀌는 변화는 くなる(明るくなる)를 쓴다. 부탁할 때는 くしてください(音を小さくしてください)가 자주 쓰인다. な형용사는 にする(きれいにする).","cmp":[{"g":"～くなる","d":"상태가 자연히 바뀜(部屋が明るくなる). くする는 사람이 바꿈(部屋を明るくする)."},{"g":"な형용사にします","d":"な형용사는 く 대신 に를 써서 にします."}],"ex":[{"jp":"電気[でんき]をつけて、部屋[へや]を明[あか]るくします。","ko":"불을 켜서 방을 밝게 합니다."},{"jp":"すみません、音[おと]を小[ちい]さくしてください。","ko":"죄송한데 소리를 작게 해 주세요."},{"jp":"髪[かみ]を短[みじか]くしました。","ko":"머리를 짧게 했어요."}],"dr":[{"t":"make","q":"部屋 / 明るい → ～を～くします","a":"部屋を明るくします","hint":"い를 く로 바꾸고 します를 붙인다."},{"t":"make","q":"音 / 小さい → ～くしてください","a":"音を小さくしてください","hint":"小さい → 小さく, します의 て형 して + ください."},{"t":"fill","q":"暑[あつ]いですね。エアコンで部屋[へや]を涼[すず]し（　）します。","a":"く","opts":["く","に","な","で"]}],"src":["https://nihongokyoshi-net.com/2020/01/23/jlptn4-grammar-adjective-suru/","https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%AA%E3%82%8B-%E3%81%8F%E3%81%AA%E3%82%8B"],"vf":1,"u":3,"g":1,"gp":"gg_N5_01"},{"id":"g5_016","t":"い形容詞くないです","ko":"~지 않습니다 (い형용사 정중 부정)","cat":"활용","conn":[{"w":"い형용사","f":"寒い → 寒く + ないです"},{"w":"い형용사","f":"高い → 高く + ありません"},{"w":"불규칙 いい","f":"いい → よく + ないです"}],"rule":["い형용사 끝의 い를 떼어 낸다(寒い → 寒).","く를 붙인다(寒く).","부정 ない를 붙인 뒤 정중하게 です를 붙인다(寒くないです).","ないです 대신 ありません을 써도 된다(寒くありません). いい는 よくないです."],"why":"く형(연용형)에 부정의 ない가 붙은 꼴이고, ない 자체가 い형용사처럼 활용하므로 정중형은 です를 덧붙여 만든다.","nu":"くないです는 일상 정중체, くありません은 조금 더 딱딱하고 글에서 자주 보인다. 과거는 くなかったです / くありませんでした. な형용사·명사처럼 じゃないです를 붙여 '寒いじゃないです'라고 하는 것은 틀린다. いくないです도 틀리고 よくないです가 맞다.","cmp":[{"g":"な형용사じゃないです","d":"な형용사·명사의 부정(静かじゃないです). い형용사는 く+ないです."}],"ex":[{"jp":"今日[きょう]はあまり寒[さむ]くないです。","ko":"오늘은 별로 춥지 않아요."},{"jp":"この本[ほん]は高[たか]くありません。","ko":"이 책은 비싸지 않습니다."},{"jp":"天気[てんき]はよくないです。","ko":"날씨가 좋지 않아요."}],"dr":[{"t":"make","q":"寒い → ～くないです","a":"寒くないです","hint":"い를 떼고 く + ない + です."},{"t":"make","q":"いい → ～くないです","a":"よくないです","hint":"いい는 よ를 어간으로 써서 よく + ないです."},{"t":"fill","q":"この料理[りょうり]は辛[から]（　）です。","a":"くない","opts":["くない","じゃない","ではない","にない"]}],"src":["https://www.tofugu.com/japanese-grammar/i-adjective-negative-form-kunai/"],"vf":1,"u":3,"g":1,"gp":"gg_N5_01"},{"id":"g5_017","t":"い形容詞くて","ko":"~고, ~해서 (い형용사 연결)","cat":"활용","conn":[{"w":"い형용사","f":"安い → 安くて + おいしい"},{"w":"い형용사","f":"広い → 広くて + 明るい"},{"w":"불규칙 いい","f":"いい → よくて"}],"rule":["い형용사 끝의 い를 떼어 낸다(安い → 安).","く를 붙이고 이어서 て를 붙인다(安くて).","くて 뒤에 다른 형용사나 문장을 이어 '~하고 ~하다'를 나타낸다(安くておいしい).","いい는 예외로 よくて가 된다."],"why":"く형(연용형)에 접속의 て가 붙은 꼴로, 동사 て형처럼 뒤 내용을 잇는다.","nu":"성질을 나열할 때 쓰고, 문맥에 따라 이유(~해서)도 된다(暑くて眠れない). 나열할 때는 좋은 평가끼리, 나쁜 평가끼리 묶는 것이 자연스럽고 좋은 점과 나쁜 점을 함께 말할 때는 けど・が를 쓴다(安いけど、まずい). な형용사·명사는 で를 쓴다.","cmp":[{"g":"な형용사で","d":"な형용사·명사의 연결은 で(静かで、きれい). い형용사는 くて."}],"ex":[{"jp":"この店[みせ]のラーメンは安[やす]くておいしいです。","ko":"이 가게 라면은 싸고 맛있어요."},{"jp":"私[わたし]の部屋[へや]は広[ひろ]くて明[あか]るいです。","ko":"제 방은 넓고 밝아요."},{"jp":"今日[きょう]は暑[あつ]くて、何[なに]もしたくないです。","ko":"오늘은 더워서 아무것도 하기 싫어요."}],"dr":[{"t":"make","q":"安い + おいしい → ～くて～","a":"安くておいしい","hint":"앞 형용사의 い를 く로 바꾸고 て를 붙인다."},{"t":"make","q":"頭がいい + やさしい → ～くて～","a":"頭がよくてやさしい","hint":"いい는 よくて."},{"t":"fill","q":"この部屋[へや]は広[ひろ]（　）、きれいです。","a":"くて","opts":["くて","で","に","な"]}],"src":["https://bunpro.jp/grammar_points/adjective-%E3%81%A6-noun-%E3%81%A7","https://langoal.com/jlpt/explain-grammar-adj-and-adj.html"],"vf":1,"u":3,"g":1,"gp":"gg_N5_01"},{"id":"g5_018","t":"な形容詞に＋動詞","ko":"~하게, ~히 (동사를 꾸밈)","cat":"활용","conn":[{"w":"な형용사","f":"静か(な) → 静かに + 歩く"},{"w":"な형용사","f":"きれい(な) → きれいに + 書く"},{"w":"な형용사","f":"上手(な) → 上手に + 話す"}],"rule":["명사를 꾸밀 때 붙는 な를 쓰지 않는다(静かな → 静か).","어간에 に를 붙인다(静かに).","に형 뒤에 동사를 놓아 '~하게 ~하다'를 나타낸다(静かに歩く)."],"why":"な형용사의 연용형이 に여서, に가 붙으면 동사를 꾸미는 부사처럼 쓰인다.","nu":"회화·문장 모두 쓴다. な형용사에 く를 붙이는 실수(きれいく)가 많다. きれい・きらい는 い로 끝나도 な형용사라서 きれいに가 맞다. 부탁할 때 '静かにしてください'처럼 する와 함께 자주 쓴다.","cmp":[{"g":"い형용사く＋동사","d":"い형용사는 い를 く로 바꾼다(速く走る). な형용사는 に."}],"ex":[{"jp":"赤[あか]ちゃんが寝[ね]ているので、静[しず]かに歩[ある]いてください。","ko":"아기가 자고 있으니 조용히 걸어 주세요."},{"jp":"名前[なまえ]をきれいに書[か]きました。","ko":"이름을 깔끔하게 썼어요."},{"jp":"マリアさんは日本語[にほんご]を上手[じょうず]に話[はな]します。","ko":"마리아 씨는 일본어를 잘 해요."}],"dr":[{"t":"make","q":"静かな + 歩く → ～に＋동사","a":"静かに歩く","hint":"な를 빼고 に를 붙인 뒤 동사."},{"t":"make","q":"きれいな + 書く → ～に＋동사","a":"きれいに書く","hint":"きれい는 な형용사라서 く가 아니라 に."},{"t":"fill","q":"図書館[としょかん]では静[しず]か（　）話[はな]してください。","a":"に","opts":["に","く","な","で"]}],"src":["https://sublearn.com/learn/ja/grammar/ja-adjective-adverbial-form"],"vf":1,"u":3,"g":1,"gp":"gg_N5_02"},{"id":"g5_019","t":"な形容詞で～","ko":"~하고, ~해서 (な형용사 연결)","cat":"활용","conn":[{"w":"な형용사","f":"きれい(だ) → きれいで + 静かです"},{"w":"な형용사","f":"便利(だ) → 便利で + 安い"},{"w":"명사(같은 꼴)","f":"学生(だ) → 学生で + 二十歳です"}],"rule":["な형용사 어간 뒤의 だ(또는 명사 수식의 な)를 쓰지 않는다(きれいだ → きれい).","어간에 で를 붙인다(きれいで). で는 だ의 て형이다.","で 뒤에 다른 형용사나 문장을 이어 '~하고 ~하다'를 나타낸다(きれいで静かです)."],"why":"で는 단정의 だ가 て형으로 바뀐 꼴이라서, い형용사의 くて나 동사의 て형처럼 앞뒤를 잇는다.","nu":"성질을 나열하거나 이유(~해서)를 말할 때 쓴다(大変で疲れました). 나열할 때는 좋은 평가끼리, 나쁜 평가끼리 묶는 것이 자연스럽고, 좋은 점과 나쁜 점은 けど・が로 잇는다. きれい・きらい는 い로 끝나도 な형용사라서 きれいくて가 아니라 きれいで가 맞다.","cmp":[{"g":"い형용사くて","d":"い형용사는 い를 く로 바꾸고 て(安くて). な형용사·명사는 で."}],"ex":[{"jp":"この公園[こうえん]はきれいで静[しず]かです。","ko":"이 공원은 깨끗하고 조용해요."},{"jp":"この町[まち]は便利[べんり]で、とても住[す]みやすいです。","ko":"이 동네는 편리해서 아주 살기 좋아요."},{"jp":"田中[たなか]さんは親切[しんせつ]で、おもしろい人[ひと]です。","ko":"다나카 씨는 친절하고 재미있는 사람이에요."}],"dr":[{"t":"make","q":"静かだ + きれいです → ～で～","a":"静かできれいです","hint":"だ를 で로 바꿔 뒤 문장과 잇는다."},{"t":"make","q":"元気だ + 明るい → ～で～","a":"元気で明るい","hint":"な형용사 어간 + で."},{"t":"fill","q":"この部屋[へや]はきれい（　）、広[ひろ]いです。","a":"で","opts":["で","くて","に","な"]}],"src":["https://bunpro.jp/grammar_points/adjective-%E3%81%A6-noun-%E3%81%A7","https://langoal.com/jlpt/explain-grammar-adj-and-adj.html"],"vf":1,"u":3,"g":1,"gp":"gg_N5_02"},{"id":"g5_020","t":"な形容詞にします","ko":"~하게 하다 (상태를 바꾸다)","cat":"활용","conn":[{"w":"な형용사","f":"きれい(な) → きれいに + します"},{"w":"な형용사","f":"静か(な) → 静かに + します"},{"w":"な형용사","f":"簡単(な) → 簡単に + します"}],"rule":["명사를 꾸밀 때 붙는 な를 쓰지 않는다(きれいな → きれい).","어간에 に를 붙인다(きれいに).","뒤에 します(する)를 붙여 '누군가가 무엇을 ~하게 만든다'를 나타낸다(きれいにします).","대상은 を로 나타낸다(部屋をきれいにします)."],"why":"に형(연용형) + する 구조로, する의 동작주가 의도적으로 대상의 상태를 바꾼다는 뜻이 된다.","nu":"사람이 일부러 바꿀 때 쓴다. 저절로 바뀌는 변화는 になる(きれいになる). '静かにしてください'(조용히 해 주세요)는 아주 자주 쓰는 부탁 표현이다. 명사 + にします는 '~로 하겠습니다(결정)'라는 별개 용법이라 헷갈리지 않도록 한다(コーヒーにします).","cmp":[{"g":"な형용사になります","d":"상태가 자연히 바뀜(部屋がきれいになる). にする는 사람이 바꿈(部屋をきれいにする)."},{"g":"い형용사くします","d":"い형용사는 い를 く로 바꿔 くします(明るくします)."}],"ex":[{"jp":"毎週[まいしゅう]日曜日[にちようび]に部屋[へや]をきれいにします。","ko":"매주 일요일에 방을 깨끗하게 해요."},{"jp":"図書館[としょかん]では静[しず]かにしてください。","ko":"도서관에서는 조용히 해 주세요."},{"jp":"来週[らいしゅう]のテストは簡単[かんたん]にします。","ko":"다음 주 시험은 쉽게 하겠습니다."}],"dr":[{"t":"make","q":"部屋 / きれいな → ～を～にします","a":"部屋をきれいにします","hint":"な를 빼고 に + します."},{"t":"make","q":"静かな → ～にしてください","a":"静かにしてください","hint":"静か + に, します의 て형 して + ください."},{"t":"fill","q":"もっと字[じ]をきれい（　）書[か]いてください。","a":"に","opts":["に","く","で","な"]}],"src":["https://nihongokyoshi-net.com/2020/01/23/jlptn4-grammar-adjective-suru/","https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%AA%E3%82%8B-%E3%81%8F%E3%81%AA%E3%82%8B"],"vf":1,"u":3,"g":1,"gp":"gg_N5_02"},{"id":"g5_021","t":"な形容詞になります","ko":"~해집니다, ~하게 됩니다","cat":"활용","conn":[{"w":"な형용사","f":"元気(な) → 元気に + なります"},{"w":"명사","f":"医者 → 医者に + なります"},{"w":"참고: い형용사","f":"寒い → 寒く + なります"}],"rule":["명사를 꾸밀 때 붙는 な를 쓰지 않는다(元気な → 元気).","어간에 に를 붙인다(元気に).","뒤에 なります(なる)를 붙여 '그 상태로 변한다'를 나타낸다(元気になります).","명사도 같은 방식으로 に + なります를 쓴다. い형용사는 い를 く로 바꿔 くなります."],"why":"なる는 '되다'라는 동사이고, に는 변화의 결과(도착점)를 나타내므로 'に + なる'가 '~한 상태가 되다'라는 뜻이 된다.","nu":"자연스러운 변화나 결과를 말한다. 누가 일부러 바꾼 것은 にする. 과거 なりました, 결과가 이어지는 상태는 なっています. 한국어 '건강해지다'에 끌려 元気くなる로 쓰지 않도록 주의(な형용사는 に). 앞으로의 변화를 말할 때 '~になりたい'(되고 싶다)도 자주 쓴다.","cmp":[{"g":"な형용사にします","d":"사람이 의도적으로 바꿈(部屋をきれいにします)."},{"g":"い형용사くなります","d":"い형용사의 변화형(暖かくなります)."}],"ex":[{"jp":"薬[くすり]を飲[の]んで、元気[げんき]になりました。","ko":"약을 먹고 건강해졌어요."},{"jp":"夜[よる]になると、この町[まち]は静[しず]かになります。","ko":"밤이 되면 이 동네는 조용해져요."},{"jp":"毎日[まいにち]練習[れんしゅう]して、日本語[にほんご]が上手[じょうず]になりました。","ko":"매일 연습해서 일본어를 잘하게 됐어요."}],"dr":[{"t":"make","q":"元気な → ～になりました","a":"元気になりました","hint":"な를 빼고 に + なりました."},{"t":"make","q":"日本語 / 上手な → ～が～になりました","a":"日本語が上手になりました","hint":"上手 + に + なりました."},{"t":"fill","q":"部屋[へや]を掃除[そうじ]して、きれい（　）なりました。","a":"に","opts":["に","く","で","を"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%AA%E3%82%8B-%E3%81%8F%E3%81%AA%E3%82%8B"],"vf":1,"u":3,"g":1,"gp":"gg_N5_02"},{"id":"g5_046","t":"～て（て形）","ko":"~하고, ~해서 (동작 잇기)","cat":"활용","conn":[{"w":"1그룹 う·つ·る","f":"買う → 買って / 待つ → 待って / 帰る → 帰って"},{"w":"1그룹 む·ぶ·ぬ","f":"飲む → 飲んで / 遊ぶ → 遊んで / 死ぬ → 死んで"},{"w":"1그룹 く·ぐ·す","f":"書く → 書いて / 泳ぐ → 泳いで / 話す → 話して (예외 行く → 行って)"},{"w":"2그룹","f":"食べる → 食べて / 起きる → 起きて"},{"w":"3그룹","f":"する → して / 来る(くる) → 来て(きて)"}],"rule":["2그룹 동사는 끝의 る를 빼고 て를 붙인다(食べる -> 食べて).","1그룹 동사는 끝 글자에 따라 바뀐다: う·つ·る -> って, む·ぶ·ぬ -> んで, く -> いて, ぐ -> いで, す -> して.","行く만 예외로 行いて가 아니라 行って가 된다.","する는 して, 来る는 来て(きて)가 된다. て형 뒤에 쉼표를 찍고 다음 동작을 이으면 '~하고 (나서)'가 된다."],"why":"1그룹의 って·んで·いて는 옛날 연용형(書き·飲み·買い)에 て가 붙을 때 발음이 편하게 바뀐 '음편'에서 나왔다. む·ぶ·ぬ는 ん 뒤에서 て가 탁음 で로 바뀐다.","nu":"동사 활용 중 가장 중요하고 실수가 잦은 형태. 동작을 일어난 순서대로 잇는다. 문장의 시제·정중함은 마지막 동사가 정하므로 て형 자체는 바뀌지 않는다(飲んで、出かけました). 2그룹처럼 보이는 1그룹 동사(帰る, 入る, 走る 등)를 帰て로 만드는 실수에 주의.","cmp":[{"g":"～てから","d":"てから는 'A를 끝낸 다음에 B'라는 순서를 더 강조한다. て는 단순히 이어서 말한다."}],"ex":[{"jp":"コーヒーを飲[の]んで、出[で]かけます。","ko":"커피를 마시고 나가요."},{"jp":"朝[あさ]六時[ろくじ]に起[お]きて、ジョギングをしました。","ko":"아침 6시에 일어나서 조깅을 했어요."},{"jp":"買[か]い物[もの]をして、家[いえ]に帰[かえ]りましょう。","ko":"장을 보고 집에 돌아갑시다."}],"dr":[{"t":"make","q":"書く → て형","a":"書いて","hint":"く는 いて로 바뀐다."},{"t":"make","q":"待つ → て형","a":"待って","hint":"う·つ·る는 って로 바뀐다."},{"t":"fill","q":"本[ほん]を（　）、寝[ね]ました。","a":"読んで","opts":["読んで","読みて","読って","読いて"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei06_5.pdf","https://laits.utexas.edu/japanese/joshu/conjugation/conref/cr_teform.php"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_047","t":"～ています","ko":"~하고 있습니다 / ~해 있습니다","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読んで + います"},{"w":"2그룹 동사","f":"食べる → 食べて + います"},{"w":"する","f":"する → して + います (勉強しています)"},{"w":"来る","f":"来る(くる) → 来て(きて) + います"}],"rule":["동사를 て형으로 바꾼다(2그룹은 る -> て, 1그룹은 음편: 読む -> 読んで, 書く -> 書いて).","て형 뒤에 います를 붙인다. 보통체는 ている.","동작 동사(食べる, 読む)에 붙으면 '지금 ~하고 있다'(진행)가 된다.","변화 동사(結婚する, 開く)에 붙으면 '~해 있다'(변화가 끝난 상태)가 된다."],"why":"て형에 있다(いる)를 붙인 형태로, 동작이나 그 결과가 '계속 있다'는 뜻에서 진행·결과 상태·습관 등을 나타낸다.","nu":"회화에서는 い가 빠진 てます(食べてます)도 흔하다. 結婚しています는 '결혼하는 중'이 아니라 '결혼한 상태(기혼)'이고, 知っています(알고 있다)의 부정은 知りません이다. 毎朝走っています처럼 습관도 나타낸다.","cmp":[{"g":"～てあります","d":"てあります는 누군가 일부러 해 둔 결과(窓が開けてあります). ています는 진행 또는 저절로 된 상태(窓が開いています)."}],"ex":[{"jp":"妹[いもうと]は今[いま]、ご飯[はん]を食[た]べています。","ko":"여동생은 지금 밥을 먹고 있어요."},{"jp":"私[わたし]は毎日[まいにち]日本語[にほんご]を勉強[べんきょう]しています。","ko":"저는 매일 일본어를 공부하고 있어요."},{"jp":"兄[あに]は結婚[けっこん]しています。","ko":"형은 결혼했어요(기혼이에요)."}],"dr":[{"t":"make","q":"見る → ～ています","a":"見ています","hint":"2그룹: る를 て로, 그다음 います."},{"t":"make","q":"待つ → ～ています","a":"待っています","hint":"つ는 って, 그다음 います."},{"t":"fill","q":"今[いま]、雨[あめ]が降[ふ]って（　）。","a":"います","opts":["います","あります","から","まえに"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201312.html","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei06_5.pdf"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_070","t":"～ています","ko":"~하고 있습니다 (진행·상태·습관)","cat":"활용","conn":[{"w":"1그룹 동사(む·ぶ·ぬ)","f":"読む → 読んで + います"},{"w":"1그룹 동사(う·つ·る)","f":"待つ → 待って + います"},{"w":"1그룹 동사(く)","f":"聞く → 聞いて + います (行く → 行って)"},{"w":"2그룹 동사","f":"食べる → 食べて + います"},{"w":"する / 来る","f":"勉強する → 勉強して、来る → 来(き)て + います"}],"rule":["동사를 て형으로 바꾼다. む·ぶ·ぬ로 끝나는 1그룹 동사는 어미를 ん으로 바꾸고 て를 で로 붙인다(読む → 読んで).","う·つ·る는 って, く는 いて, ぐ는 いで, す는 して가 되고 2그룹은 る를 떼고 て를 붙인다(食べて). 行く는 예외로 行って.","て형 뒤에 います를 붙인다(読んで + います). 보통체는 ている, 회화에서는 てる로 줄기도 한다."],"why":"동사 て형에 '있다'는 뜻의 いる가 붙은 형태로, 어떤 동작·변화가 일어난 뒤 그 상황이 지금까지 이어지고 있음을 나타낸다. 그래서 진행(읽고 있다)도, 결과 상태(결혼해 있다, 알고 있다)도 표현한다.","nu":"① 지금 진행 중인 동작(新聞を読んでいます). ② 순간 동사의 결과 상태(電気がついています, 疲れています). ③ 반복·습관(毎日走っています). 知る는 '알고 있다'를 知っています로 말하고, 부정은 知りません이 보통이다. 住む도 住んでいます. ある에는 ている를 붙이지 않는다. 한국어 '~고 있다'로만 생각하면 결과 상태 용법을 놓치기 쉽다.","cmp":[{"g":"～てあります","d":"てあります는 누군가 의도적으로 해 둔 결과(窓が開けてあります, 타동사), ています는 진행이나 자연스러운 상태(窓が開いています, 자동사)."}],"ex":[{"jp":"父[ちち]は新聞[しんぶん]を読[よ]んでいます。","ko":"아버지는 신문을 읽고 있습니다."},{"jp":"今[いま]、雨[あめ]が降[ふ]っています。","ko":"지금 비가 내리고 있어요."},{"jp":"姉[あね]は大阪[おおさか]に住[す]んでいます。","ko":"언니는 오사카에 살고 있어요."}],"dr":[{"t":"make","q":"飲む → ～ています","a":"飲んでいます","hint":"む를 ん으로, て를 で로 바꿔 んで + います."},{"t":"make","q":"書く → ～ています","a":"書いています","hint":"く를 いて로 바꾸고 います."},{"t":"fill","q":"今[いま]、弟[おとうと]は部屋[へや]でテレビを見[み]て（　）。","a":"います","opts":["います","あります","いきます","みます"]}],"src":["https://www.tofugu.com/japanese-grammar/verb-continuous-form-teiru/"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_089","t":"～たり、～たりします","ko":"~하기도 하고 ~하기도 합니다, ~거나 ~거나 합니다","cat":"활용","conn":[{"w":"동사","f":"見る → 見た + り → 見たり / 遊ぶ → 遊んだり"},{"w":"い형용사","f":"寒い → 寒かった + り → 寒かったり"},{"w":"な형용사","f":"静か → 静かだった + り → 静かだったり"},{"w":"명사","f":"雨 → 雨だった + り → 雨だったり"},{"w":"불규칙","f":"する → したり / 来る → 来たり"}],"rule":["동사를 과거(た)형으로 바꾼다(見る → 見た, 遊ぶ → 遊んだ).","た형 끝에 り를 붙인다(見たり, 遊んだり). た가 だ인 동사는 だり가 된다.","같은 방법으로 만든 두 번째 동작을 이어 쓴다(見たり遊んだり).","맨 끝에 する를 붙이고, 시제·정중함은 する에서 나타낸다(します / しました).","형용사·명사는 かったり / だったり로 만든다."],"why":"たり의 た는 과거형 끝의 た와 같은 것이다. 다만 이 문형에서는 과거의 뜻이 없고, 시제는 마지막 する가 정한다.","nu":"회화·문장 모두 쓴다. 여러 행동 중 몇 가지를 예로 드는 것이어서 '등등'의 느낌이 있다. 형용사·명사에 쓰면 '~하기도 하고 ~하기도 하다'처럼 상태가 번갈아 바뀌는 뜻이 된다. 한국인이 자주 하는 실수: 마지막 する를 빼먹거나(×見たり遊んだりです), 두 번째에만 り를 붙이는 것.","cmp":[{"g":"～て、～て","d":"て형 나열은 말한 행동을 실제 순서대로 모두 했다는 뜻. たり는 순서 없이 예를 몇 개 든다."},{"g":"～や～など","d":"や는 명사를 예로 들어 나열한다. たり는 동작·상태를 예로 든다."}],"ex":[{"jp":"休[やす]みの日[ひ]は、映画[えいが]を見[み]たり、友達[ともだち]と遊[あそ]んだりします。","ko":"쉬는 날에는 영화를 보기도 하고 친구와 놀기도 합니다."},{"jp":"昨日[きのう]は掃除[そうじ]をしたり、洗濯[せんたく]をしたりしました。","ko":"어제는 청소를 하기도 하고 빨래를 하기도 했습니다."},{"jp":"このごろは暑[あつ]かったり寒[さむ]かったりします。","ko":"요즘은 덥기도 하고 춥기도 합니다."}],"dr":[{"t":"make","q":"読む・書く → ～たり～たりします","a":"読んだり書いたりします","hint":"각각 た형(読んだ, 書いた)에 り를 붙이고 끝에 します."},{"t":"make","q":"歌う・踊る → ～たり～たりしました","a":"歌ったり踊ったりしました","hint":"う・る로 끝나는 1그룹은 った형, 과거 시제는 마지막 しました로."},{"t":"fill","q":"週末[しゅうまつ]は買[か]い物[もの]をし（　）、料理[りょうり]を作[つく]ったりします。","a":"たり","opts":["たり","ても","たら","ながら"]}],"src":["https://www.tofugu.com/japanese-grammar/tarisuru/","https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%8A-%E3%81%9F%E3%82%8A%E3%81%99%E3%82%8B"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_024","t":"名詞がほしいです","ko":"~을/를 갖고 싶어요, ~이/가 필요해요","cat":"문말표현","conn":[{"w":"명사","f":"車 + が + ほしいです"},{"w":"명사(부정)","f":"お金 + は + ほしくないです"},{"w":"의문사","f":"何 + が + ほしいですか"}],"rule":["갖고 싶은 물건(명사) 뒤에 조사 が를 붙인다(車が).","그 뒤에 ほしいです를 놓는다(車がほしいです).","ほしい는 い형용사처럼 활용한다: 부정 ほしくないです, 과거 ほしかったです."],"why":"ほしい(欲しい)는 '갖고 싶다'라는 뜻의 い형용사라서 원하는 대상을 が로 나타내고 い형용사처럼 활용한다.","nu":"말하는 사람 자신의 바람을 말한다. 제3자의 바람은 ほしがっています를 쓴다(弟は車をほしがっています). 상대에게 'ほしいですか'라고 물을 수는 있지만 윗사람에게는 실례가 된다. 행동을 하고 싶을 때는 ～たいです, 남이 해 주기를 바랄 때는 ～てほしい를 쓴다. 한국어 '~를 갖고 싶다'에 끌려 を를 쓰기 쉬운데 기본은 が.","cmp":[{"g":"동사ます형 + たいです","d":"행동을 하고 싶을 때(車を買いたいです). ほしい는 물건."}],"ex":[{"jp":"新[あたら]しいくつがほしいです。","ko":"새 신발을 갖고 싶어요."},{"jp":"誕生日[たんじょうび]に何[なに]がほしいですか。","ko":"생일에 뭐 갖고 싶어요?"},{"jp":"今[いま]は車[くるま]はほしくないです。","ko":"지금은 차는 갖고 싶지 않아요."}],"dr":[{"t":"make","q":"車 → ～がほしいです","a":"車がほしいです","hint":"명사 + が + ほしいです."},{"t":"make","q":"お金はほしいです → ～くないです","a":"お金はほしくないです","hint":"ほしい의 い를 く로 바꾸고 ないです."},{"t":"fill","q":"私[わたし]は新[あたら]しいパソコン（　）ほしいです。","a":"が","opts":["が","で","に","へ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%8C%E3%81%BB%E3%81%97%E3%81%84","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei03_4.pdf"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_045","t":"～たいです","ko":"~하고 싶습니다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"飲む → 飲み + たいです"},{"w":"2그룹 동사","f":"食べる → 食べ + たいです"},{"w":"する","f":"する → し + たいです (勉強したいです)"},{"w":"来る","f":"来る(くる) → 来(き) + たいです"}],"rule":["동사를 ます형(ます를 붙이는 형태)에서 ます를 뗀 모양으로 만든다.","1그룹 동사는 끝 글자를 う단에서 い단으로 바꾼다(飲む -> 飲み, 行く -> 行き).","2그룹 동사는 る를 뺀다(食べる -> 食べ). する는 し, 来る는 来(き).","그 뒤에 たい를 붙이고, 정중하게는 です를 더한다. たい는 い형용사처럼 たくない·たかった로 활용한다."],"why":"たい는 ます와 같은 자리(동사의 ます형 어간)에 붙는 희망의 조동사이며, 끝이 い로 끝나서 い형용사와 똑같이 활용한다.","nu":"말하는 사람 자신의 바람(의문문에서는 듣는 사람의 바람)에 쓴다. 제3자의 바람을 '彼は行きたいです'처럼 단정하면 부자연스럽고, 行きたがっています·行きたいと言っています를 쓴다. 상대에게 권유할 때는 たいですか보다 ～ませんか가 자연스럽다. 원하는 대상에는 を 대신 が도 쓸 수 있다(水が飲みたい).","cmp":[{"g":"～がほしいです","d":"ほしい는 '물건'을 갖고 싶을 때(명사 + がほしい). たい는 '동작'을 하고 싶을 때."}],"ex":[{"jp":"冷[つめ]たい水[みず]が飲[の]みたいです。","ko":"차가운 물을 마시고 싶어요."},{"jp":"夏休[なつやす]みに日本[にほん]へ行[い]きたいです。","ko":"여름 방학에 일본에 가고 싶어요."},{"jp":"今日[きょう]は何[なに]もしたくないです。","ko":"오늘은 아무것도 하고 싶지 않아요."}],"dr":[{"t":"make","q":"買う → ～たいです","a":"買いたいです","hint":"1그룹: う를 い로 바꾸고 たいです."},{"t":"make","q":"寝る → ～たいです","a":"寝たいです","hint":"2그룹: る를 빼고 たいです."},{"t":"fill","q":"週末[しゅうまつ]は映画[えいが]を見[み]（　）です。","a":"たい","opts":["たい","ます","て","たり"]}],"src":["https://bunpro.jp/ja/grammar_points/59"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_049","t":"～てください","ko":"~해 주세요, ~하세요","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"書く → 書いて + ください / 待つ → 待って + ください / 読む → 読んで + ください"},{"w":"1그룹 예외(行く)","f":"行く → 行って + ください"},{"w":"2그룹 동사","f":"開ける → 開けて + ください"},{"w":"する","f":"する → して + ください"},{"w":"来る","f":"来る → 来て + ください"}],"rule":["동사를 て형으로 바꾼다. 2그룹 동사는 끝의 る를 떼고 て를 붙인다(開ける → 開けて).","1그룹 동사는 어미에 따라 음편이 생긴다: う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで, す → して(行く만 예외로 行って).","する는 して, 来る는 来て로 바뀐다.","만든 て형 뒤에 ください를 그대로 붙인다(開けて + ください)."],"why":"ください는 '주다'의 존경어 くださる의 명령형이다. 그래서 '~해 주십시오'처럼 상대에게 행동을 요구하는 뜻이 되고, ください를 빼고 て형만 쓰면 반말 지시가 된다.","nu":"정중한 부탁·지시 표현이지만 실제로는 상대가 하도록 정해 주는 '지시'의 힘이 있어서, 윗사람에게 부탁할 때는 ～てくださいませんか / ～ていただけませんか가 더 공손하다. 안내문·선생님 지시·가게 직원 말투에 자주 나온다. 한국어 '~해 주세요'를 그대로 옮겨 윗사람에게 남발하지 않도록 주의.","cmp":[{"g":"～てくださいませんか","d":"てください는 지시에 가까운 부탁, てくださいませんか는 상대의 의향을 묻는 더 공손한 부탁."},{"g":"Nをください","d":"명사를 달라고 할 때는 명사 + をください, 행동을 해 달라고 할 때는 て형 + ください."}],"ex":[{"jp":"すみません、窓[まど]を開[あ]けてください。","ko":"죄송한데 창문을 열어 주세요."},{"jp":"もう少[すこ]しゆっくり話[はな]してください。","ko":"조금 더 천천히 말해 주세요."},{"jp":"明日[あした]は九時[くじ]に来[き]てください。","ko":"내일은 9시에 와 주세요."}],"dr":[{"t":"make","q":"待つ → ～てください","a":"待ってください","hint":"1그룹, 어미 つ는 って로 바뀐 뒤 ください를 붙인다."},{"t":"make","q":"見せる → ～てください","a":"見せてください","hint":"2그룹, る를 떼고 て + ください."},{"t":"fill","q":"ここに名前[なまえ]を書[か]いて（　）。","a":"ください","opts":["ください","います","しまいます","から"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201603.html","https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%84%E3%81%A7%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_050","t":"～ないでください","ko":"~하지 마세요, ~하지 말아 주세요","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"走る → 走らない + でください / 吸う → 吸わない + でください"},{"w":"2그룹 동사","f":"忘れる → 忘れない + でください"},{"w":"する","f":"する → しない + でください"},{"w":"来る","f":"来る → 来(こ)ない + でください"}],"rule":["동사를 ない형으로 바꾼다. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다(走る → 走らない). 어미가 う면 わ가 된다(吸う → 吸わない).","2그룹 동사는 る를 떼고 ない를 붙인다(忘れる → 忘れない).","する → しない, 来る → こない로 바뀐다.","ない 뒤에 で를 붙이고, 이어서 ください를 붙인다(走らない + で + ください)."],"why":"ないで는 부정 ない에 で가 붙은 형태로 '~하지 않고/않은 채로'라는 뜻이며, 여기에 くださる의 명령형 ください가 붙어 '~하지 않은 상태로 있어 주십시오', 즉 금지 부탁이 된다.","nu":"정중한 금지 표현이지만 말투만 공손할 뿐 단호하게 들리는 경우가 많다. 표지판·안내 방송·선생님 지시에 흔하다. なくてください처럼 잘못 만드는 실수가 많으니 반드시 ないで + ください로 쓴다.","cmp":[{"g":"～てはいけません","d":"ないでください는 상대에게 하지 말라고 부탁하는 말, てはいけません은 규칙상 금지되어 있다고 알리는 말."}],"ex":[{"jp":"ここでたばこを吸[す]わないでください。","ko":"여기서 담배를 피우지 마세요."},{"jp":"廊下[ろうか]を走[はし]らないでください。","ko":"복도에서 뛰지 마세요."},{"jp":"明日[あした]の約束[やくそく]を忘[わす]れないでください。","ko":"내일 약속을 잊지 마세요."}],"dr":[{"t":"make","q":"話す → ～ないでください","a":"話さないでください","hint":"1그룹, す를 さ로 바꾸고 ない + で + ください."},{"t":"make","q":"心配する → ～ないでください","a":"心配しないでください","hint":"する는 しない로 바뀐다."},{"t":"fill","q":"この部屋[へや]には入[はい]ら（　）ください。","a":"ないで","opts":["ないで","なくて","ないと","なければ"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201603.html","https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%84%E3%81%A7%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84"],"vf":1,"u":4,"g":1,"gp":"gg_N5_02"},{"id":"g5_054","t":"～ましょう","ko":"~합시다, ~하자(요)","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行き + ましょう"},{"w":"2그룹 동사","f":"食べる → 食べ + ましょう"},{"w":"する","f":"する → し + ましょう / 散歩する → 散歩し + ましょう"},{"w":"来る","f":"来る → 来(き) + ましょう"}],"rule":["동사를 ます형으로 바꾼다. 1그룹은 어미 う단을 い단으로(行く → 行き), 2그룹은 る를 뗀다(食べる → 食べ).","する는 し, 来る는 き가 된다.","ます 대신 ましょう를 붙인다(行きます → 行きましょう)."],"why":"ましょう는 정중의 조동사 ます의 의지·권유형이다. 그래서 정중하게 '같이 ~하자'라고 권하는 뜻이 된다.","nu":"정중한 권유. 함께 하자고 적극적으로 끌어당기는 말이라 이미 하기로 정한 일이나, 상대의 권유에 응할 때(ええ、行きましょう) 잘 쓴다. 상대의 의향을 먼저 물을 때는 ませんか가 더 부드럽다. 선생님이 '~합시다'처럼 부드러운 지시로 쓰기도 한다.","cmp":[{"g":"～ませんか","d":"ませんか는 상대의 의사를 묻는 권유, ましょう는 함께 하자고 단정적으로 이끄는 권유."},{"g":"～ましょうか","d":"か를 붙이면 상대의 동의를 구하는 제안이나 '제가 ~할까요?'라는 제의가 된다."}],"ex":[{"jp":"一緒[いっしょ]に昼[ひる]ご飯[はん]を食[た]べましょう。","ko":"같이 점심 먹읍시다."},{"jp":"ちょっと休[やす]みましょう。","ko":"잠깐 쉽시다."},{"jp":"「映画[えいが]を見[み]ませんか。」「いいですね。見[み]ましょう。」","ko":"\"영화 안 볼래요?\" \"좋네요. 봅시다.\""}],"dr":[{"t":"make","q":"帰る → ～ましょう","a":"帰りましょう","hint":"帰る는 1그룹(예외), る를 り로 바꿔 ましょう."},{"t":"make","q":"勉強する → ～ましょう","a":"勉強しましょう","hint":"する는 し로 바꾸고 ましょう."},{"t":"fill","q":"もう遅[おそ]いですね。そろそろ帰[かえ]り（　）。","a":"ましょう","opts":["ましょう","ました","ません","ませんでした"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%97%E3%82%87%E3%81%86%E3%81%8B","https://bunpro.jp/topics/shall-we"],"vf":1,"u":4,"g":1,"gp":"gg_N5_03"},{"id":"g5_055","t":"～ましょうか","ko":"(제가) ~할까요?, (같이) ~할까요?","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"持つ → 持ち + ましょうか"},{"w":"2그룹 동사","f":"開ける → 開け + ましょうか"},{"w":"する","f":"する → し + ましょうか / 手伝う → 手伝い + ましょうか"},{"w":"来る","f":"来る → 来(き) + ましょうか"}],"rule":["동사를 ます형으로 바꾼다. 1그룹은 어미 う단을 い단으로(持つ → 持ち), 2그룹은 る를 뗀다(開ける → 開け).","する는 し, 来る는 き가 된다.","ます를 ましょう로 바꾸고 끝에 의문의 か를 붙인다(持ちます → 持ちましょうか)."],"why":"ましょう는 정중의 조동사 ます의 의지·권유형이고, 여기에 질문의 조사 か가 붙어 '~하자'를 상대에게 묻는 형태가 된다. 그래서 '제가 ~할까요?'(제의) 또는 '같이 ~할까요?'(제안)로 상대의 동의를 구한다.","nu":"두 가지 쓰임이 있다. ① 말하는 사람이 상대를 위해 무언가를 해 주겠다고 제의(荷物を持ちましょうか). ② 함께 하자고 부드럽게 제안(少し休みましょうか). ましょう보다 상대의 의견을 묻는 느낌이라 부드럽다. 반말로는 의지형 + か(持とうか)가 된다. 제의에 대한 대답은 ええ、お願いします / いいえ、大丈夫です 등.","cmp":[{"g":"～ましょう","d":"ましょう는 '~합시다'라고 이끄는 말, ましょうか는 '~할까요?'라고 상대의 동의를 묻는 말."},{"g":"～ませんか","d":"ませんか는 상대에게 하겠느냐고 묻는 권유(상대 중심), ましょうか는 함께 하거나 내가 해 주겠다는 제안·제의."}],"ex":[{"jp":"重[おも]そうですね。荷物[にもつ]を持[も]ちましょうか。","ko":"무거워 보이네요. 짐을 들어 드릴까요?"},{"jp":"暑[あつ]いですね。窓[まど]を開[あ]けましょうか。","ko":"덥네요. 창문을 열까요?"},{"jp":"疲[つか]れましたね。少[すこ]し休[やす]みましょうか。","ko":"피곤하네요. 조금 쉴까요?"}],"dr":[{"t":"make","q":"手伝う → ～ましょうか","a":"手伝いましょうか","hint":"う를 い로 바꾼 ます형 + ましょうか."},{"t":"make","q":"コーヒーを入れる → ～ましょうか","a":"コーヒーを入れましょうか","hint":"2그룹, る를 떼고 ましょうか."},{"t":"fill","q":"A: 写真[しゃしん]を撮[と]り（　）。 B: ええ、お願[ねが]いします。","a":"ましょうか","opts":["ましょうか","ましたか","ていますか","たいですか"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%97%E3%82%87%E3%81%86%E3%81%8B","https://bunpro.jp/grammar_points/75"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_056","t":"～ませんか","ko":"~하지 않겠어요?, ~안 할래요?","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行き + ませんか"},{"w":"2그룹 동사","f":"見る → 見 + ませんか"},{"w":"する","f":"する → し + ませんか / 参加する → 参加し + ませんか"},{"w":"来る","f":"来る → 来(き) + ませんか"}],"rule":["동사를 ます형으로 바꾼다. 1그룹은 어미 う단을 い단으로(行く → 行き), 2그룹은 る를 뗀다(見る → 見).","ます를 부정형 ません으로 바꾼다(見ます → 見ません).","끝에 의문의 か를 붙인다(見ません → 見ませんか)."],"why":"정중 부정 ません에 질문 か가 붙어 '~하지 않겠습니까?'라고 상대의 의향을 묻는 형태가 되고, 이것이 권유로 쓰인다. 부정 질문이라 상대가 거절하기 쉬운 여지를 남겨 정중하게 들린다.","nu":"상대의 의사를 존중하며 초대·권유할 때 가장 기본적인 정중 표현. 승낙은 いいですね、行きましょう, 거절은 すみません、ちょっと… 처럼 말끝을 흐리는 경우가 많다. 반말은 行かない?(올림 억양). 상대가 이미 하기로 한 일에는 쓰지 않는다. 문맥에 따라 그냥 '안 ~합니까?'라는 부정 질문으로도 읽히므로 억양·상황으로 구별한다.","cmp":[{"g":"～ましょう","d":"ましょう는 같이 하자고 이끄는 말이라 상대가 거절하기 어렵고, ませんか는 먼저 상대의 의향을 묻는다."},{"g":"～ましょうか","d":"ましょうか는 함께 하자는 제안이나 '제가 할까요?'라는 제의, ませんか는 상대에게 권하는 초대."}],"ex":[{"jp":"週末[しゅうまつ]、一緒[いっしょ]に映画[えいが]を見[み]ませんか。","ko":"주말에 같이 영화 안 볼래요?"},{"jp":"明日[あした]のパーティーに来[き]ませんか。","ko":"내일 파티에 오지 않을래요?"},{"jp":"駅前[えきまえ]で一緒[いっしょ]に昼[ひる]ご飯[はん]を食[た]べませんか。","ko":"역 앞에서 같이 점심 먹지 않을래요?"}],"dr":[{"t":"make","q":"飲む → ～ませんか","a":"飲みませんか","hint":"む를 み로 바꾸고 ませんか."},{"t":"make","q":"散歩する → ～ませんか","a":"散歩しませんか","hint":"する는 し로 바꾸고 ませんか."},{"t":"fill","q":"A: 今度[こんど]、一緒[いっしょ]に海[うみ]へ行[い]き（　）。 B: いいですね。","a":"ませんか","opts":["ませんか","ましたか","ませんでした","ています"]}],"src":["https://bunpro.jp/grammar_points/75","https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%97%E3%82%87%E3%81%86%E3%81%8B","https://bunpro.jp/topics/shall-we"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_064","t":"～があります","ko":"~이 있습니다 (사물·식물·일)","cat":"문말표현","conn":[{"w":"장소 + に + 사물 + が","f":"教室に机があります"},{"w":"사람 + は/に + 사물 + が (소유)","f":"私は車があります"},{"w":"사건·예정","f":"明日テストがあります"},{"w":"부정(ある의 부정)","f":"ある → ない / あります → ありません"}],"rule":["'장소 + に + 물건 + が + あります' 틀에 단어를 넣는다(教室に机があります).","사람·동물처럼 스스로 움직이는 것은 あります가 아니라 います를 쓴다(猫がいます).","부정은 ありません, 보통체 부정은 あらない가 아니라 ない다."],"why":"あります는 존재 동사 ある의 ます형이다. 일본어는 존재를 말할 때 움직이는 생물(いる)과 움직이지 않는 것(ある)을 구별한다.","nu":"식물, 물건, 건물, 사건·행사·계획 등에 쓴다. 한국어 '있다' 하나로 둘 다 말하므로 사람·동물에 あります를 쓰는 실수(×犬があります)가 많다. 정지한 차량은 ある, 운전사가 탄 채 기다리는 버스 등은 いる로도 말한다. 장소를 주제로 할 때는 '机は教室にあります'(책상은 교실에 있습니다) 어순도 쓴다.","cmp":[{"g":"～がいます","d":"います는 사람·동물 등 스스로 움직이는 것, あります는 움직이지 않는 사물·식물·일."}],"ex":[{"jp":"教室[きょうしつ]に机[つくえ]があります。","ko":"교실에 책상이 있습니다."},{"jp":"駅[えき]の近[ちか]くにコンビニがあります。","ko":"역 근처에 편의점이 있습니다."},{"jp":"明日[あした]、日本語[にほんご]のテストがあります。","ko":"내일 일본어 시험이 있습니다."}],"dr":[{"t":"make","q":"部屋 / テレビ → ～に～があります","a":"部屋にテレビがあります","hint":"장소 + に + 물건 + が + あります."},{"t":"make","q":"お金があります → 부정","a":"お金がありません","hint":"あります를 ありません으로."},{"t":"fill","q":"公園[こうえん]に大[おお]きい木[き]が（　）。","a":"あります","opts":["あります","います","です","します"]}],"src":["https://www.tofugu.com/japanese-grammar/iru-aru/"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_095","t":"～どうしますか","ko":"~은 어떻게 하겠어요?, ~하면 어떻게 할 거예요?","cat":"문말표현","conn":[{"w":"명사 + は","f":"飲み物は + どうしますか"},{"w":"조건절(동사 たら형)","f":"雨が降ったら、どうしますか"},{"w":"반말","f":"どうする?"}],"rule":["물어볼 대상이나 상황을 먼저 말한다(飲み物は / 雨が降ったら).","그 뒤에 どう(어떻게) + します(하다)를 놓는다.","끝에 か를 붙여 질문으로 만든다(どうしますか).","반말은 どうする?, 과거로 이미 한 일을 물을 때는 どうしましたか가 된다."],"why":"부사 どう(어떻게: 방법·상태를 묻는 말)에 동사 する의 정중형 します와 질문의 か가 이어진 것이다.","nu":"상대가 앞으로 어떤 선택·행동을 할지 묻는다. 가게에서 손님에게는 더 공손한 どうなさいますか를 쓴다. どうですか(어때요?: 감상·제안)와 혼동하기 쉽다. どうしましたか는 '무슨 일이에요?(어디 아파요?)'라는 뜻으로도 쓰이므로 구별해 익힌다.","cmp":[{"g":"～どうですか","d":"どうですか는 상태·감상을 묻거나 제안한다(이건 어때요?). どうしますか는 상대의 행동·결정을 묻는다(어떻게 할래요?)."},{"g":"なにをしますか","d":"なにをしますか는 '무엇을 해요?'로 활동 내용을 묻는다. どうしますか는 방법·선택을 묻는다."}],"ex":[{"jp":"お飲[の]み物[もの]はどうしますか。","ko":"음료는 어떻게 하시겠어요?"},{"jp":"明日[あした]雨[あめ]が降[ふ]ったら、どうしますか。","ko":"내일 비가 오면 어떻게 할 거예요?"},{"jp":"週末[しゅうまつ]はどうする？","ko":"주말엔 어떻게 할 거야?"}],"dr":[{"t":"make","q":"昼ご飯 → ～どうしますか","a":"昼ご飯はどうしますか","hint":"명사 뒤에 は를 붙이고 どうしますか."},{"t":"make","q":"どうしますか → 반말","a":"どうする","hint":"します를 사전형 する로 바꾸고 か를 뺀다(억양을 올린다)."},{"t":"fill","q":"電車[でんしゃ]が止[と]まったら、（　）しますか。","a":"どう","opts":["どう","どれ","どこ","どの"]}],"src":["https://kotobank.jp/word/%E3%81%A9%E3%81%86","https://www.vnjpclub.com/en/n5-grammar/dou-shimasu-ka.html"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_096","t":"～どうですか","ko":"~은 어때요?, ~하는 건 어때요?","cat":"문말표현","conn":[{"w":"명사 + は","f":"この服は + どうですか"},{"w":"동사 사전형 + の + は","f":"行くのは + どうですか"},{"w":"권유(명사만)","f":"コーヒー、どうですか"},{"w":"정중한 말","f":"どうですか → いかがですか"}],"rule":["물어볼 대상인 명사를 말하고 は를 붙인다(この服は).","그 뒤에 どう(어떻게) + です + か를 붙인다(この服はどうですか).","동사를 대상으로 할 때는 사전형에 の를 붙여 명사처럼 만든다(行くのはどうですか).","더 공손하게는 どう를 いかが로 바꾼다(いかがですか)."],"why":"どう는 상태를 묻는 부사이고, 사전에 따르면 상대의 기분을 살피며 무언가를 권하는 용법도 있어 いかが와 같은 역할을 한다. 그래서 감상을 묻는 뜻과 '~은 어때요?'라는 권유 뜻을 함께 가진다.","nu":"회화에서 매우 자주 쓴다. 감상·상태를 물을 때(日本はどうですか)와 무언가를 권할 때(お茶はどうですか) 두 가지로 쓴다. 손윗사람·손님에게는 いかがですか가 더 공손하다. どうしますか(어떻게 할 거예요?)와 헷갈리지 않도록 주의.","cmp":[{"g":"～どうしますか","d":"どうしますか는 상대의 행동·선택을 묻는다. どうですか는 상태·감상을 묻거나 제안한다."},{"g":"いかがですか","d":"뜻은 같고 더 공손한 말. 가게·손님 응대에서 쓴다."}],"ex":[{"jp":"この服[ふく]はどうですか。","ko":"이 옷은 어때요?"},{"jp":"日本[にほん]の生活[せいかつ]はどうですか。","ko":"일본 생활은 어때요?"},{"jp":"明日[あした]、映画[えいが]を見[み]に行[い]くのはどうですか。","ko":"내일 영화 보러 가는 건 어때요?"}],"dr":[{"t":"make","q":"天気 → ～どうですか","a":"天気はどうですか","hint":"명사 뒤에 は, 그 다음 どうですか."},{"t":"make","q":"どうですか → 더 공손하게","a":"いかがですか","hint":"どう를 공손한 いかが로 바꾼다."},{"t":"fill","q":"A：日本[にほん]の食[た]べ物[もの]は（　）ですか。　B：とてもおいしいです。","a":"どう","opts":["どう","だれ","いつ","どこ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/%E3%81%AF%E3%81%A9%E3%81%86%E3%81%A7%E3%81%99%E3%81%8B-wa-dou-desu-ka-meaning","https://kotobank.jp/word/%E3%81%A9%E3%81%86"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_098","t":"～はどう言いますか","ko":"~는 어떻게 말합니까","cat":"문말표현","conn":[{"w":"명사(단어) + は + 언어 + で","f":"「猫[ねこ]」は英語[えいご]でどう言[い]いますか"},{"w":"명사 + を + 언어 + で","f":"この言葉[ことば]を日本語[にほんご]でどう言[い]いますか"},{"w":"회화체 (って + 보통형)","f":"これって英語[えいご]でどう言[い]う？"},{"w":"なん(何)と로 바꾸기","f":"「猫[ねこ]」は英語[えいご]で何[なん]と言[い]いますか"}],"rule":["알고 싶은 단어나 표현을 「 」로 묶고 주제 조사 は를 붙인다.","언어 이름 뒤에는 수단의 조사 で를 붙인다(英語で). に가 아니다.","마지막에 どう(어떻게) + 言います(말합니다) + か(질문)를 놓는다.","친구끼리는 は 대신 って, 言いますか 대신 言う？를 쓴다."],"why":"どう(어떻게) + 言う(말하다)의 ます형 + 질문의 か로 이루어진 그대로의 문장이다. で는 '~로(수단)'를 나타내므로 언어 이름에 붙는다.","nu":"수업·여행에서 쓰는 정중한 질문이다. 단어 하나의 이름을 물을 때는 何と言いますか도 자연스럽고, 문장이나 기분처럼 표현 방식을 물을 때는 どう言いますか가 더 잘 어울린다. 한국인은 '영어로'를 英語に로 잘못 쓰기 쉬우니 で를 쓴다. 한자 읽는 법을 물을 때는 どう読みますか를 쓴다.","cmp":[{"g":"～は何と言いますか","d":"何と는 단어(이름) 자체를 묻는 데 초점, どう는 말하는 방식·표현을 묻는 데 초점. 짧은 단어에는 둘 다 쓴다."},{"g":"～はどう読みますか","d":"글자(한자)를 어떻게 읽는지 물을 때. どう言いますか는 다른 말로 어떻게 표현하는지 묻는다."}],"ex":[{"jp":"「ありがとう」は韓国語[かんこくご]でどう言[い]いますか。","ko":"'아리가토'는 한국어로 어떻게 말합니까?"},{"jp":"この気持[きも]ちは日本語[にほんご]でどう言[い]いますか。","ko":"이 기분은 일본어로 어떻게 말해요?"},{"jp":"これって英語[えいご]でどう言[い]う？","ko":"이거 영어로 어떻게 말해?"}],"dr":[{"t":"make","q":"「いぬ」/ 英語 → 질문 문장으로","a":"「いぬ」は英語でどう言いますか","hint":"단어 + は, 언어 + で, 끝에 どう言いますか"},{"t":"make","q":"「さようなら」は英語でどう言いますか → 친구에게 (회화체)","a":"「さようなら」って英語でどう言う？","hint":"は → って, 言いますか → 言う？"},{"t":"fill","q":"「水[みず]」は英語[えいご]（　）どう言[い]いますか。","a":"で","opts":["で","に","を","が"]}],"src":["https://www.vnjpclub.com/en/n5-grammar/dou-iimasu-ka.html"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_122","t":"～はなんと言いますか","ko":"~은/는 뭐라고 합니까?","cat":"문말표현","conn":[{"w":"명사 + は","f":"これはなんと言いますか"},{"w":"명사 + は + 언어 + で","f":"これは日本語でなんと言いますか"},{"w":"인용구 「 」 + は","f":"「ありがとう」は韓国語でなんと言いますか"},{"w":"명사 + を (목적어로)","f":"これを日本語でなんと言いますか"}],"rule":["묻고 싶은 말(명사·인용구)에 は를 붙여 주제로 세운다.","어느 언어로 묻는지는 언어 이름 + で로 넣는다(日本語で). 상황이 분명하면 생략한다.","何를 なん으로 읽고 인용 조사 と를 붙여 なんと(뭐라고)를 만든다.","끝에 言います + か를 붙여 정중한 질문을 만든다. 대답은 「はな」と言います처럼 같은 틀에 단어를 넣는다."],"why":"なん(무엇) + と(인용 조사 '~라고') + 言う(말하다)가 그대로 이어져 '뭐라고 말합니까'가 된다. 何는 た행 소리 앞에서 なん으로 읽는다.","nu":"정중체 질문이라 수업이나 처음 만난 사람에게 쓰기 좋다. 친구 사이에는 なんて言う？처럼 말한다. と를 빠뜨려 なん言いますか라고 하거나 なにと로 읽는 실수에 주의.","cmp":[{"g":"～は～語でなんですか","d":"'~는 ~어로 뭐예요?'라는 더 간단한 질문. 뜻은 비슷하지만 단어를 어떻게 말하는지 물을 때는 なんと言いますか가 더 자연스럽다."}],"ex":[{"jp":"これは日本語[にほんご]でなんと言[い]いますか。","ko":"이것은 일본어로 뭐라고 합니까?"},{"jp":"「감사합니다」は日本語[にほんご]でなんと言[い]いますか。","ko":"'감사합니다'는 일본어로 뭐라고 해요?"},{"jp":"この料理[りょうり]を日本語[にほんご]でなんと言[い]いますか。","ko":"이 요리를 일본어로 뭐라고 해요?"}],"dr":[{"t":"make","q":"これは 日本語 → '이것은 일본어로 뭐라고 합니까?'","a":"これは日本語でなんと言いますか","hint":"언어 뒤에 で, 이어서 なん + と + 言いますか."},{"t":"make","q":"なん ＿ 言いますか (빠진 조사를 넣어 완성)","a":"なんと言いますか","hint":"'~라고'를 나타내는 인용 조사 と."},{"t":"fill","q":"「サンキュー」は日本語[にほんご]で（　）言[い]いますか。","a":"なんと","opts":["なんと","なにを","なんで","なにが"]}],"src":["https://www.japanesepod101.com/lesson/listen-learn-speak-audio-can-do-japanese-12-how-to-ask-for-a-word-in-language","https://bagustris.github.io/minna-no-nihongo/mnn_sho_1/minna_no_nihongo_sho_1_07.html","https://tofugu.com/japanese-grammar/question-words"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_126","t":"～はたいへんです","ko":"~은/는 힘듭니다","cat":"문말표현","conn":[{"w":"명사 + は","f":"この仕事はたいへんです"},{"w":"동사 사전형 + の + は","f":"漢字を覚えるのはたいへんです"},{"w":"과거","f":"昨日のテストはたいへんでした"},{"w":"명사 수식 (な형용사)","f":"たいへんな仕事"}],"rule":["힘든 대상(명사)에 は를 붙인다(仕事は).","동작이 힘들 때는 동사 사전형에 の를 붙여 명사처럼 만든 뒤 は를 붙인다(覚える + の + は).","たいへん은 な형용사라서 끝에 です를 붙이고, 과거는 たいへんでした, 명사를 꾸밀 때는 たいへんな가 된다."],"why":"동사에 の를 붙이면 동작이 명사처럼 되어 문장의 주제가 될 수 있다. 그 동작에 대한 말하는 사람의 느낌을 たいへん(힘들다, 손이 많이 간다)으로 평가하는 짜임이다.","nu":"회화에서 자주 쓴다. 남의 고생을 듣고 たいへんですね(힘드시겠네요)라고 공감할 때도 쓴다. たいへん에는 '큰일'(たいへんだ!)이나 '매우'(たいへんおいしい)라는 뜻도 있다. 동사 뒤에 の를 빠뜨려 覚えるはたいへんです라고 하는 실수가 많다.","cmp":[{"g":"～はむずかしいです","d":"むずかしい는 이해하거나 해내기 '어렵다'. たいへん은 시간·힘이 많이 들어 '고생스럽다'."}],"ex":[{"jp":"この仕事[しごと]はたいへんです。","ko":"이 일은 힘듭니다."},{"jp":"漢字[かんじ]を覚[おぼ]えるのはたいへんです。","ko":"한자를 외우는 것은 힘듭니다."},{"jp":"昨日[きのう]のテストはたいへんでした。","ko":"어제 시험은 힘들었습니다."}],"dr":[{"t":"make","q":"毎日料理をする → ～のはたいへんです","a":"毎日料理をするのはたいへんです","hint":"사전형 する 뒤에 の + は."},{"t":"make","q":"たいへんです → 과거","a":"たいへんでした","hint":"な형용사: です → でした."},{"t":"fill","q":"朝[あさ]早[はや]く起[お]きる（　）はたいへんです。","a":"の","opts":["の","な","を","に"]}],"src":["https://jplang.tufs.ac.jp/tw/bu/21/21-6.html"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_057","t":"Vること","ko":"~하는 것 (동사의 명사화)","cat":"명사화·수식","conn":[{"w":"동사 사전형","f":"泳ぐ + こと / 食べる + こと"},{"w":"する·来る","f":"する + こと / 来る + こと"},{"w":"목적어가 있는 동사구","f":"日本語を勉強する + こと"},{"w":"ない형(부정)","f":"忘れない + こと"}],"rule":["동사는 사전형(보통형) 그대로 둔다. 어미는 바뀌지 않는다(泳ぐ).","뒤에 형식명사 こと를 붙여 '~하는 것'이라는 명사 덩어리를 만든다(泳ぐ + こと).","만든 덩어리는 명사처럼 조사 が・は・を 등을 붙여 쓴다(泳ぐことが好きです).","です 앞에서는 こと만 쓴다(趣味は泳ぐことです)."],"why":"こと(事)는 '일, 것'을 뜻하는 형식명사로, 앞의 동사구를 받아 하나의 명사로 묶는다. 그래서 동사를 문장의 주어·목적어 자리에 넣을 수 있다.","nu":"회화·문장 모두 쓰지만 の보다 약간 딱딱하다. 대부분 の와 바꿔 쓸 수 있으나 です・だ 앞(趣味は～ことです)과 ことができる・ことにする 같은 고정 표현에서는 こと만, 見る・聞く 같은 지각 동사 앞에서는 の만 쓴다. 한국어 '것'에 끌려 동사 뒤에 명사처럼 바로 が를 붙이는 실수(泳ぐが好き)에 주의.","cmp":[{"g":"Vの","d":"の는 더 회화적이고 눈앞의 구체적 동작에 잘 맞으며, こと는 です 앞이나 고정 표현에 쓴다."}],"ex":[{"jp":"私[わたし]の趣味[しゅみ]は写真[しゃしん]を撮[と]ることです。","ko":"제 취미는 사진을 찍는 것입니다."},{"jp":"泳[およ]ぐことが大好[だいす]きです。","ko":"헤엄치는 것을 아주 좋아합니다."},{"jp":"毎日[まいにち]日本語[にほんご]を勉強[べんきょう]することは大切[たいせつ]です。","ko":"매일 일본어를 공부하는 것은 중요합니다."}],"dr":[{"t":"make","q":"趣味 / 本を読む → 趣味は～ことです","a":"趣味は本を読むことです","hint":"동사 사전형 + こと + です."},{"t":"make","q":"料理を作る / 好きです → ～ことが好きです","a":"料理を作ることが好きです","hint":"사전형 + こと 뒤에 が好きです."},{"t":"fill","q":"私[わたし]の夢[ゆめ]は先生[せんせい]になる（　）です。","a":"こと","opts":["こと","ので","けど","し"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201112.html"],"vf":1,"u":5,"g":1,"gp":"gg_N5_03"},{"id":"g5_060","t":"Vるの","ko":"~하는 것 (の를 이용한 명사화)","cat":"명사화·수식","conn":[{"w":"동사 사전형","f":"歌う + の / 食べる + の"},{"w":"する·来る","f":"する + の / 来る + の"},{"w":"동사구","f":"料理を作る + の"},{"w":"ない형·た형","f":"行かない + の / 見た + の"}],"rule":["동사를 사전형(보통형) 그대로 둔다(歌う).","뒤에 の를 붙여 '~하는 것'이라는 명사 덩어리를 만든다(歌う + の).","명사처럼 조사를 붙인다: のが好き・のが上手・のを忘れる・のは楽しい 등.","です・だ 바로 앞에는 の가 아니라 こと를 쓴다."],"why":"の는 앞의 동사구를 받아 명사처럼 만드는 조사(준체조사)로 쓰여, 동사를 好き・上手 같은 말의 대상이나 주어로 만들 수 있다.","nu":"こと보다 회화적이다. 見る・聞く・聞こえる 같은 지각 동사, 待つ・手伝う 등과 함께 쓸 때는 の만 자연스럽다(子どもが遊んでいるのを見ました). 반대로 です 앞이나 ことができる 같은 고정 표현에서는 の로 바꿀 수 없다. 문장 끝에 오는 の(行くの? / 行くの。)는 설명·질문을 나타내는 반말 종조사로, 명사화와는 다른 쓰임이다.","cmp":[{"g":"Vこと","d":"こと는 です 앞·고정 표현에 쓰고 조금 딱딱하며, の는 회화적이고 지각 동사와 함께 쓴다."},{"g":"문말의 の(설명·질문)","d":"문장 끝의 の는 사정을 설명하거나 묻는 반말 표현이고, 문장 안의 の는 동사를 명사로 만든다."}],"ex":[{"jp":"妹[いもうと]は歌[うた]うのが上手[じょうず]です。","ko":"여동생은 노래 부르는 것을 잘합니다."},{"jp":"朝[あさ]早[はや]く起[お]きるのは大変[たいへん]です。","ko":"아침 일찍 일어나는 것은 힘듭니다."},{"jp":"宿題[しゅくだい]を出[だ]すのを忘[わす]れました。","ko":"숙제를 내는 것을 잊었습니다."}],"dr":[{"t":"make","q":"絵をかく / 好きです → ～のが好きです","a":"絵をかくのが好きです","hint":"사전형 + の + が好きです."},{"t":"make","q":"電話する / 忘れました → ～のを忘れました","a":"電話するのを忘れました","hint":"사전형 + の + を忘れました."},{"t":"fill","q":"子[こ]どもたちが公園[こうえん]で遊[あそ]んでいる（　）を見[み]ました。","a":"の","opts":["の","こと","もの","ため"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201112.html"],"vf":1,"u":6,"g":1,"gp":"gg_N5_03"},{"id":"g5_112","t":"どの＋名詞","ko":"어느 ~ (여럿 중)","cat":"명사화·수식","conn":[{"w":"どの + 명사 + が","f":"どの本がいいですか"},{"w":"どの + 명사 + を","f":"どの服を買いますか"},{"w":"どの + 명사 + に","f":"どの電車に乗りますか"},{"w":"どの + 사람 (정중: 方)","f":"どの方が先生ですか"}],"rule":["단독으로 쓰는 どれ를 명사 앞에서는 どの로 바꾼다(どれが → どの本が).","どの 바로 뒤에는 반드시 명사가 온다(どの本, どの色).","조사는 명사 뒤에 붙인다(どの本が, どの服を).","보통 셋 이상 가운데 하나를 물을 때 쓴다."],"why":"この・その・あの・どの는 명사를 꾸미는 말(연체사) 묶음이고, これ・それ・あれ・どれ는 혼자 쓰는 대명사 묶음이다. 그래서 명사 앞에는 どの를 쓴다.","nu":"회화·문장 모두 쓴다. どの 뒤에 명사 없이 どのが라고 하거나, どれ本처럼 쓰는 실수가 많다. 두 가지 중 고를 때는 どちらの + 명사가 더 자연스럽다.","cmp":[{"g":"どれ","d":"どれ는 혼자 쓰는 대명사(どれがいいですか). どの는 명사 앞에만(どの本がいいですか)."},{"g":"どんな","d":"どんな는 '어떤 종류의'. どの는 눈앞의 여러 개 중 '어느 것'."}],"ex":[{"jp":"どの本[ほん]がおもしろいですか。","ko":"어느 책이 재미있어요?"},{"jp":"どの電車[でんしゃ]に乗[の]りますか。","ko":"어느 전철을 탑니까?"},{"jp":"どの人[ひと]が山田[やまだ]さんですか。","ko":"어느 사람이 야마다 씨입니까?"}],"dr":[{"t":"make","q":"どれ + 色 + が好きですか → 하나로","a":"どの色が好きですか","hint":"명사 앞에서는 どれ를 どの로."},{"t":"make","q":"どれ + かさ + ですか → 하나로","a":"どのかさですか","hint":"どの + 명사 + ですか."},{"t":"fill","q":"（　）かばんが田中[たなか]さんのですか。","a":"どの","opts":["どの","どれ","どこ","どう"]}],"src":["https://tofugu.com/japanese-grammar/kore-sore-are-dore","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei15_6.pdf"],"vf":1,"u":6,"g":1,"gp":"gg_N5_03"},{"id":"g5_114","t":"どんな＋名詞","ko":"어떤 ~ (종류·성질)","cat":"명사화·수식","conn":[{"w":"どんな + 명사 + が","f":"どんな音楽が好きですか"},{"w":"どんな + 명사 + を","f":"どんな本を読みますか"},{"w":"どんな + 명사 + ですか","f":"どんな人ですか"},{"w":"대답: 형용사 + 명사","f":"静かな音楽です / 優しい人です"}],"rule":["どんな는 명사 바로 앞에 붙여 '어떤 종류·성질인지'를 묻는다(どんな + 音楽).","조사는 명사 뒤에 붙인다(どんな音楽が).","대답할 때는 どんな 자리에 성질을 나타내는 말을 넣는다(どんな → 静かな).","な형용사는 な, い형용사는 い 그대로 명사 앞에 둔다(静かな音楽, 明るい音楽)."],"why":"사전에서 どんな는 'どのような'와 같은 뜻으로 종류·상태를 묻는 말로 풀이된다.","nu":"회화체에 가깝고, 정중한 문장이나 글에서는 どのような를 쓴다. 눈앞의 여러 개 중 하나를 고를 때는 どの를 쓴다. どんな 뒤에 명사 없이 どんなが라고 하지 않는다. どんな～でも는 '어떤 ~라도'라는 별도 용법이다.","cmp":[{"g":"どの","d":"どの는 정해진 여러 개 중 '어느 것'. どんな는 '어떤 종류·성질'."},{"g":"どのような","d":"뜻은 같고 더 정중·문어적."}],"ex":[{"jp":"どんな音楽[おんがく]が好[す]きですか。","ko":"어떤 음악을 좋아하세요?"},{"jp":"新[あたら]しい先生[せんせい]はどんな人[ひと]ですか。","ko":"새 선생님은 어떤 사람이에요?"},{"jp":"きのうはどんな映画[えいが]を見[み]ましたか。","ko":"어제는 어떤 영화를 봤어요?"}],"dr":[{"t":"make","q":"どんな音楽が好きですか → '조용한(静か) 음악을 좋아해요'로 대답","a":"静かな音楽が好きです","hint":"どんな 자리에 な형용사 + な."},{"t":"make","q":"どんな人ですか → '친절한(親切) 사람입니다'로 대답","a":"親切な人です","hint":"親切는 な형용사, 명사 앞에서 な."},{"t":"fill","q":"（　）料理[りょうり]が好[す]きですか。―からい料理[りょうり]が好[す]きです。","a":"どんな","opts":["どんな","どの","どれ","どう"]}],"src":["https://kotobank.jp/jeword/%E3%81%A9%E3%82%93%E3%81%AA","https://tofugu.com/japanese-grammar/kore-sore-are-dore"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_075","t":"～から もらいます","ko":"~에게서(~로부터) 받습니다","cat":"수수·사역·수동","conn":[{"w":"사람 명사","f":"友達 + から + もらう (友達に もらう도 가능)"},{"w":"단체·기관 명사","f":"学校 + から + もらう (に보다 から가 자연스러움)"},{"w":"동사 て형 + もらう","f":"先生に 教えてもらう (이때는 から를 쓰지 않고 に)"}],"rule":["받는 사람을 は/が로, 주는 쪽 명사 뒤에 から를 붙인다(友達から).","받은 물건에 を를 붙인다(手紙を).","もらう를 시제에 맞게 바꾼다(もらう → もらった / もらいました).","주는 쪽이 회사·학교 같은 단체면 に보다 から를 주로 쓰고, '~해 받다(て형+もらう)'에서는 から가 아니라 に를 쓴다."],"why":"から는 '출발점·출처'를 나타내는 조사라서, 물건이 어디에서 왔는지를 나타낼 때 もらう와 함께 쓸 수 있다. 사람에게서 받을 때는 に도 되지만, 단체처럼 사람이 아닌 출처일 때는 から가 더 자연스럽다.","nu":"받는 사람의 입장에서 말하는 표현이며, 주는 쪽이 '나'일 수는 없다(내가 줄 때는 あげる). 윗사람에게서 받을 때는 いただく를 쓰면 정중하다. 한국어 '~에게 받다'를 그대로 옮겨 に만 쓰는 것은 맞지만, 단체(会社, 学校)에는 から를 쓰는 습관을 들이자.","cmp":[{"g":"～に もらう","d":"사람에게서 받을 때는 に와 から 모두 가능. 단체에는 から, て형+もらう에는 に만 쓴다."},{"g":"～が 私に くれる","d":"같은 일을 주는 쪽을 주어로 말하면 くれる. もらう는 받는 쪽(나)이 주어."}],"ex":[{"jp":"友達[ともだち]から手紙[てがみ]をもらいました。","ko":"친구에게서 편지를 받았습니다."},{"jp":"兄[あに]は会社[かいしゃ]から賞[しょう]をもらいました。","ko":"형은 회사로부터 상을 받았습니다."},{"jp":"誕生日[たんじょうび]に母[はは]から時計[とけい]をもらった。","ko":"생일에 엄마에게서 시계를 받았다."}],"dr":[{"t":"make","q":"父／本／もらいました → から를 써서 한 문장","a":"父から本をもらいました","hint":"주는 쪽 + から, 물건 + を, もらいました."},{"t":"make","q":"学校／手紙／もらう(과거) → から를 써서 한 문장","a":"学校から手紙をもらった","hint":"단체는 から, もらう의 과거는 もらった."},{"t":"fill","q":"大学[だいがく]（　）奨学金[しょうがくきん]をもらいました。","a":"から","opts":["から","を","へ","と"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei13_7.pdf","https://web.mit.edu/21f.503/www/quiz-review/lesson17/grammar/17B","https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%82%89%E3%81%86"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_076","t":"～が 私に くれます","ko":"(남이) 나에게 줍니다","cat":"수수·사역·수동","conn":[{"w":"사람 명사(주는 쪽)","f":"友達 + が + 私に + 花を + くれる"},{"w":"받는 쪽(나·우리 쪽)","f":"妹に くれる (가족 등 내 쪽 사람)"},{"w":"과거·정중","f":"くれる → くれた / くれます / くれました"}],"rule":["주는 사람 뒤에 が(또는 は)를 붙인다(友達が).","받는 사람은 나(또는 내 쪽 사람)이며 뒤에 に를 붙인다(私に).","물건에 を를 붙이고 くれる로 맺는다. 과거는 る를 떼고 た를 붙인 くれた."],"why":"くれる는 다른 사람이 말하는 사람(또는 가족 등 말하는 사람 쪽)에게 물건을 주는 방향만 나타내는 동사다. 그래서 받는 쪽이 '나'라는 것이 동사 자체에 들어 있어 私に는 자주 생략된다.","nu":"내가 남에게 주거나 남이 남에게 줄 때는 あげる를 쓰고, くれる는 쓰지 않는다(×私が友達にくれる). 한국어는 '주다' 하나로 다 말하므로 이 방향 구분을 자주 틀린다. 私に는 문맥상 분명하면 빼는 것이 더 자연스럽다. 윗사람이 줄 때는 くださる.","cmp":[{"g":"～に あげる","d":"あげる는 내가 남에게, 또는 남이 남에게 줄 때. くれる는 남이 나(내 쪽)에게 줄 때."},{"g":"～に(から) もらう","d":"같은 일을 받는 쪽(나)을 주어로 말하면 もらう: 友達に花をもらった."}],"ex":[{"jp":"友達[ともだち]が私[わたし]に花[はな]をくれました。","ko":"친구가 나에게 꽃을 주었습니다."},{"jp":"先生[せんせい]が私[わたし]に辞書[じしょ]をくれた。","ko":"선생님이 나에게 사전을 주셨다."},{"jp":"祖母[そぼ]が妹[いもうと]にお菓子[かし]をくれました。","ko":"할머니가 여동생에게 과자를 주셨습니다."}],"dr":[{"t":"make","q":"田中さん／私／ペン／くれる(과거) → 한 문장","a":"田中さんが私にペンをくれた","hint":"주는 사람 が, 나 に, 물건 を, くれた."},{"t":"make","q":"兄が私に本をあげました → 올바른 동사로 고치기","a":"兄が私に本をくれました","hint":"남이 나에게 줄 때는 あげる가 아니라 くれる."},{"t":"fill","q":"姉[あね]が私[わたし]にケーキを（　）。","a":"くれました","opts":["くれました","あげました","もらいました","やりました"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201409.html","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei13_7.pdf"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_123","t":"～にあげます","ko":"~에게 줍니다","cat":"수수·사역·수동","conn":[{"w":"받는 사람 + に + 물건 + を","f":"友達に本をあげます"},{"w":"주는 사람 + は","f":"わたしは妹にケーキをあげました"},{"w":"제3자끼리","f":"田中さんは山田さんに花をあげました"},{"w":"권유 (ましょう)","f":"彼にプレゼントをあげましょう"}],"rule":["주는 사람을 は/が로, 받는 사람을 に로 표시한다.","주는 물건은 を로 표시한다(友達に本を).","동사 あげる의 る를 떼고 ます를 붙여 あげます로 끝낸다(과거 あげました).","받는 사람이 '나'나 우리 쪽 사람이면 あげます가 아니라 くれます를 쓴다."],"why":"","nu":"나 → 남, 남 → 남 방향에 쓴다. 남이 나에게 줄 때는 くれる(先生がわたしに本をくれました). 한국어 '주다' 하나로 생각해 わたしにあげます라고 하는 실수가 많다. 윗사람에게 직접 쓰면 생색내는 느낌이 날 수 있어 さしあげます를 쓴다.","cmp":[{"g":"～にくれます","d":"받는 쪽이 나 또는 우리 쪽일 때. あげます는 받는 쪽이 남일 때."},{"g":"～にもらいます","d":"같은 일을 받는 사람을 주어로 말한다. 이때 に는 주는 사람."}],"ex":[{"jp":"わたしは友達[ともだち]に本[ほん]をあげました。","ko":"저는 친구에게 책을 주었습니다."},{"jp":"母[はは]の日[ひ]に、母[はは]に花[はな]をあげます。","ko":"어머니날에 어머니께 꽃을 드립니다."},{"jp":"田中[たなか]さんは山田[やまだ]さんにチョコレートをあげました。","ko":"다나카 씨는 야마다 씨에게 초콜릿을 주었습니다."}],"dr":[{"t":"make","q":"わたし / 弟 / ケーキ / あげる → 과거 정중","a":"わたしは弟にケーキをあげました","hint":"받는 사람 弟에 に, 물건에 を, あげる → あげました."},{"t":"make","q":"あげる → '줍시다'","a":"あげましょう","hint":"る를 떼고 ましょう."},{"t":"fill","q":"わたしは友達[ともだち]に誕生日[たんじょうび]のプレゼントを（　）。","a":"あげました","opts":["あげました","くれました","ください","いきました"]}],"src":["https://bagustris.github.io/minna-no-nihongo/mnn_sho_1/minna_no_nihongo_sho_1_07.html","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201409.html"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_124","t":"～にもらいます","ko":"~에게서 받습니다","cat":"수수·사역·수동","conn":[{"w":"주는 사람 + に + 물건 + を","f":"友達に本をもらいます"},{"w":"주는 사람 + から","f":"先生から手紙をもらいました"},{"w":"과거","f":"父に時計をもらいました"},{"w":"동사 て형 + もらう","f":"友達に教えてもらいました"}],"rule":["받는 사람을 は/が로, 주는 사람을 に(또는 から)로 표시한다.","받는 물건은 を로 표시한다.","동사 もらう의 어미 う를 い로 바꾸고 ます를 붙여 もらいます로 끝낸다(과거 もらいました).","주는 쪽이 회사·학교 같은 단체이면 に보다 から를 쓴다."],"why":"","nu":"받는 사람의 입장에서 말한다. 주어 わたしは는 자주 생략된다(友達に本をもらいました). 같은 사건을 주는 쪽 입장으로 말하면 あげる/くれる가 된다. 한국어 '~에게서'에 끌려 で나 を를 쓰는 실수에 주의. 윗사람에게 받을 때는 いただきます가 더 공손하다.","cmp":[{"g":"～にくれます","d":"주는 사람이 주어: 友達がわたしに本をくれました. 뜻은 友達に本をもらいました와 같지만 시점이 다르다."},{"g":"～にあげます","d":"주는 사람이 주어이고 に는 받는 사람."}],"ex":[{"jp":"誕生日[たんじょうび]に父[ちち]に時計[とけい]をもらいました。","ko":"생일에 아버지에게서 시계를 받았습니다."},{"jp":"先生[せんせい]から手紙[てがみ]をもらいました。","ko":"선생님에게서 편지를 받았습니다."},{"jp":"友達[ともだち]に日本語[にほんご]を教[おし]えてもらいました。","ko":"친구에게 일본어를 배웠습니다(가르쳐 받았습니다)."}],"dr":[{"t":"make","q":"わたし / 姉 / かばん / もらう → 과거 정중","a":"わたしは姉にかばんをもらいました","hint":"주는 사람 姉에 に, 물건에 を, もらう → もらいました."},{"t":"make","q":"もらう → ます형","a":"もらいます","hint":"어미 う를 い로 바꾸고 ます."},{"t":"fill","q":"わたしは田中[たなか]さん（　）お土産[みやげ]をもらいました。","a":"に","opts":["に","を","で","へ"]}],"src":["https://bagustris.github.io/minna-no-nihongo/mnn_sho_1/minna_no_nihongo_sho_1_07.html","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201412.html"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_023","t":"名詞ができます","ko":"~을/를 할 수 있습니다, ~을 할 줄 압니다","cat":"가능·의무·허가","conn":[{"w":"동작 명사(する동사)","f":"テニス(をします) → テニス + が + できます"},{"w":"언어","f":"日本語 + が + できます"},{"w":"동작 명사","f":"運転 + が + できます"}],"rule":["'명사 + をします' 꼴의 동작을 바탕으로 한다(テニスをします).","목적어 조사 を를 が로 바꾼다(テニスが).","します를 가능형 できます로 바꾼다(テニスができます).","부정은 できません, 질문은 ～ができますか."],"why":"できる는 する의 가능을 나타내는 동사라서, '명사をする'가 '명사ができる'(그 일을 할 수 있다)로 바뀐다. 가능의 대상은 が로 나타낸다.","nu":"능력(할 줄 안다)과 가능(조건상 할 수 있다)을 모두 나타낸다. 한국어 '~를 할 수 있다'에 끌려 を를 쓰기 쉬운데 기본은 が. 의지로 할 수 없는 일(わかる, 降る 등)에는 쓰지 않는다. '友だちができます'(친구가 생기다), 'ビルができます'(건물이 생기다)는 '생기다, 완성되다'라는 다른 뜻이다.","cmp":[{"g":"동사 사전형 + ことができます","d":"명사가 아닌 동사로 능력을 말할 때 쓴다(泳ぐことができます)."}],"ex":[{"jp":"私[わたし]は日本語[にほんご]が少[すこ]しできます。","ko":"저는 일본어를 조금 할 줄 알아요."},{"jp":"兄[あに]は車[くるま]の運転[うんてん]ができます。","ko":"형은 차 운전을 할 줄 알아요."},{"jp":"今日[きょう]は雨[あめ]なので、テニスができません。","ko":"오늘은 비가 와서 테니스를 칠 수 없어요."}],"dr":[{"t":"make","q":"テニスをします → ～ができます","a":"テニスができます","hint":"を를 が로, します를 できます로 바꾼다."},{"t":"make","q":"料理をします → ～ができません","a":"料理ができません","hint":"を → が, します → できません(부정)."},{"t":"fill","q":"マリアさんはピアノ（　）できます。","a":"が","opts":["が","で","へ","と"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei09_1.pdf"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_058","t":"Vことができます","ko":"~할 수 있습니다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사(사전형)","f":"話す + ことができます / 乗る + ことができます"},{"w":"2그룹 동사(사전형)","f":"食べる + ことができます"},{"w":"する","f":"する + ことができます / 運転する + ことができます"},{"w":"来る","f":"来る + ことができます"},{"w":"명사(する동사 명사 등)","f":"運転 + ができます / 日本語 + ができます"}],"rule":["동사를 사전형 그대로 둔다(話す). 어미는 바뀌지 않는다.","뒤에 こと를 붙여 명사로 만든다(話す + こと).","조사 が와 できます를 붙인다(話すことができます).","부정은 できません, 과거는 できました로 できます 부분만 바꾼다."],"why":"できます는 します의 가능형이다. '~하는 것(こと)이 가능하다(できる)'라는 구조라서 능력이나 상황상 가능함을 나타낸다.","nu":"능력(英語を話すことができます)과 규칙·상황상의 가능(ここで写真を撮ることができます) 둘 다 쓴다. 가능형(話せます)보다 조금 딱딱하고 격식 있는 느낌. 의지로 하는 동작에만 쓰며 わかる・ある・降る처럼 의지와 무관한 동사에는 쓰지 않는다(わかることができます는 틀림). 조사는 が이고 を를 쓰지 않는다.","cmp":[{"g":"가능형(話せます)","d":"뜻은 거의 같지만 가능형이 더 짧고 회화적, ことができます는 더 격식 있고 설명적."},{"g":"Nができます","d":"する동사 명사나 언어·운동 이름은 동사 없이 명사 + ができます로 말할 수 있다(運転ができます)."}],"ex":[{"jp":"兄[あに]は英語[えいご]を話[はな]すことができます。","ko":"형은 영어를 말할 수 있습니다."},{"jp":"この図書館[としょかん]では本[ほん]を三冊[さんさつ]借[か]りることができます。","ko":"이 도서관에서는 책을 세 권 빌릴 수 있습니다."},{"jp":"ここで写真[しゃしん]を撮[と]ることはできません。","ko":"여기서는 사진을 찍을 수 없습니다."}],"dr":[{"t":"make","q":"ピアノを弾く → ～ことができます","a":"ピアノを弾くことができます","hint":"사전형 + こと + ができます."},{"t":"make","q":"漢字を書く → ～ことができません","a":"漢字を書くことができません","hint":"사전형 + こと + が + できません."},{"t":"fill","q":"ここでは誰[だれ]でも無料[むりょう]で休[やす]む（　）ができます。","a":"こと","opts":["こと","ため","よう","まま"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei09_1.pdf","https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%8C%E3%81%A7%E3%81%8D%E3%82%8B"],"vf":1,"u":6,"g":1,"gp":"gg_N5_04"},{"id":"g5_059","t":"Vことができる","ko":"~할 수 있다 (보통체)","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사(사전형)","f":"乗る + ことができる"},{"w":"2그룹 동사(사전형)","f":"起きる + ことができる"},{"w":"する","f":"する + ことができる / 予約する + ことができる"},{"w":"来る","f":"来る + ことができる"},{"w":"명사(する동사 명사 등)","f":"予約 + ができる"}],"rule":["동사를 사전형 그대로 둔다(乗る).","뒤에 こと를 붙여 명사로 만든다(乗る + こと).","조사 が와 보통형 できる를 붙인다(乗ることができる).","부정 できない, 과거 できた, 이어 말할 때 できて처럼 できる 부분만 활용한다."],"why":"できる는 する의 가능 동사다. '~하는 것(こと)이 가능하다(できる)'라는 구조로, 정중체 ことができます의 보통체 형태다.","nu":"친구 사이 반말, 일기·글(보통체 문장), 명사 수식(泳ぐことができる人) 등에 쓴다. 정중하게 말할 때는 ことができます. 의지로 하는 동작에만 쓰며 わかる・ある 같은 동사에는 쓰지 않는다. 반말 회화에서는 가능형(乗れる)이 더 자연스러울 때가 많다.","cmp":[{"g":"Vことができます","d":"뜻은 같고 정중체. ことができる는 보통체라 반말이나 글, 명사 수식에 쓴다."},{"g":"가능형(乗れる)","d":"회화에서는 가능형이 짧고 자연스럽고, ことができる는 조금 설명적·문어적이다."}],"ex":[{"jp":"弟[おとうと]はもう自転車[じてんしゃ]に乗[の]ることができる。","ko":"남동생은 벌써 자전거를 탈 수 있다."},{"jp":"今朝[けさ]は早[はや]く起[お]きることができなかった。","ko":"오늘 아침에는 일찍 일어날 수 없었다."},{"jp":"このアプリで店[みせ]を予約[よやく]することができる。","ko":"이 앱으로 가게를 예약할 수 있다."}],"dr":[{"t":"make","q":"一人で行く → ～ことができる","a":"一人で行くことができる","hint":"사전형 + こと + ができる."},{"t":"make","q":"昨日はよく寝る → ～ことができなかった","a":"昨日はよく寝ることができなかった","hint":"できる를 과거 부정 できなかった로."},{"t":"fill","q":"このカードがあれば、だれでも図書館[としょかん]を使[つか]う（　）ができる。","a":"こと","opts":["こと","ため","はず","つもり"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei09_1.pdf","https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%8C%E3%81%A7%E3%81%8D%E3%82%8B"],"vf":1,"u":7,"g":1,"gp":"gg_N5_04"},{"id":"g5_028","t":"Nごろ","ko":"~쯤, ~무렵 (시점)","cat":"시간·순서","conn":[{"w":"시각","f":"3時 + ごろ(に)"},{"w":"연·월·일","f":"3月 + ごろ / 1980年 + ごろ"},{"w":"의문사","f":"何時 + ごろ"},{"w":"명사 + の","f":"子どもの + ころ (단독일 때는 보통 ころ)"}],"rule":["시각·날짜 같은 '시점' 명사 뒤에 ごろ(頃)를 붙인다(3時ごろ).","시각 + ごろ 뒤의 に는 붙여도 되고 생략해도 된다(3時ごろに来る = 3時ごろ来る).","명사 형태는 바뀌지 않고, 뒤에 동사를 잇는다."],"why":"한자로 頃라고 쓰며, 본래 읽기는 ころ이고 명사 뒤에 붙을 때 ごろ로 발음된다.","nu":"회화·문장 모두 쓰는 기본 표현. 기간·양(3時間, 20分)에는 쓰지 않고 시점에만 쓴다. 앞의 수는 보통 딱 떨어지는 시각이다. 今日・今週・今年 같은 말에는 붙이지 않는다. 한국어 '3시간쯤'을 3時間ごろ로 잘못 말하기 쉬운데, 이때는 3時間ぐらい가 맞다.","cmp":[{"g":"～くらい／ぐらい","d":"くらい는 양·기간의 대략(3時間くらい), ごろ는 시점의 무렵(3時ごろ)."}],"ex":[{"jp":"3時[さんじ]ごろ友達[ともだち]が来[き]ます。","ko":"3시쯤 친구가 와요."},{"jp":"毎朝[まいあさ]、7時[しちじ]ごろに起[お]きます。","ko":"매일 아침 7시쯤 일어나요."},{"jp":"何時[なんじ]ごろ家[いえ]に帰[かえ]りますか。","ko":"몇 시쯤 집에 돌아가요?"}],"dr":[{"t":"make","q":"6時 / 帰ります → ～ごろ","a":"6時ごろ帰ります","hint":"시각 뒤에 ごろ를 붙인다(に는 생략 가능)."},{"t":"make","q":"何時 / 寝ますか → ～ごろ","a":"何時ごろ寝ますか","hint":"何時 + ごろ로 대략의 시각을 묻는다."},{"t":"fill","q":"昼[ひる]の12時[じゅうにじ]（　）にご飯[ごはん]を食[た]べます。","a":"ごろ","opts":["ごろ","しか","より","を"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_6.pdf","https://bunpro.jp/grammar_points/ごろ"],"vf":1,"u":7,"g":1,"gp":"gg_N5_04"},{"id":"g5_038","t":"～のあとで","ko":"~(이) 끝난 뒤에, ~ 후에","cat":"시간·순서","conn":[{"w":"명사(행사·활동)","f":"朝ご飯 + の + あとで"},{"w":"명사(행사·활동)","f":"授業 + の + あとで"},{"w":"참고: 동사","f":"食べた + あとで (동사는 た형에 바로 붙음)"}],"rule":["먼저 일어나는 일(명사)에 조사 の를 붙인다.","그 뒤에 あとで를 붙여 '그 일이 끝난 뒤에'를 만든다.","명사는 활용 변화가 없고, 뒷문장에 나중에 하는 일을 쓴다.","あと는 한자로 後라고도 쓴다(後で)."],"why":"あと(後)는 '뒤, 나중'이라는 명사이고, で가 붙어 그 시점을 나타낸다. 명사 두 개를 잇기 때문에 사이에 の가 들어간다.","nu":"회화·문장 모두 쓰는 기본 표현. 앞 명사는 パーティー·授業·食事처럼 시작과 끝이 있는 행사·활동 명사가 자연스럽다(예: 机のあとで는 X). 한국어 '밥 먹은 후에'처럼 の를 빼고 ご飯あとで라고 하기 쉬운데 の가 꼭 필요하다.","cmp":[{"g":"～の前に","d":"반대로 '그 일 전에'. 食事の前に手を洗います처럼 순서가 거꾸로다."},{"g":"～たあとで","d":"동사일 때 쓰는 형태. 명사에는 の, 동사에는 た형이 온다."}],"ex":[{"jp":"授業[じゅぎょう]のあとで、図書館[としょかん]に行[い]きます。","ko":"수업 후에 도서관에 가요."},{"jp":"晩[ばん]ご飯[はん]のあとで、テレビを見[み]ました。","ko":"저녁 식사 후에 TV를 봤어요."},{"jp":"テストのあとで、みんなで遊[あそ]びましょう。","ko":"시험 끝나고 다 같이 놀아요."}],"dr":[{"t":"make","q":"仕事 → ～のあとで","a":"仕事のあとで","hint":"명사 뒤에 の를 넣고 あとで."},{"t":"make","q":"パーティー / 部屋を片づけました → ～のあとで、～","a":"パーティーのあとで、部屋を片づけました","hint":"먼저 일어난 일 + のあとで, 그다음 나중 일."},{"t":"fill","q":"昼[ひる]ご飯[はん]の（　）、散歩[さんぽ]します。","a":"あとで","opts":["あとで","まえに","ながら","から"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei11_2.pdf","https://jlptsensei.com/learn-japanese-grammar/前に-まえに-mae-ni-meaning"],"vf":1,"u":7,"g":1,"gp":"gg_N5_04"},{"id":"g5_044","t":"～たあとで","ko":"~한 뒤에, ~하고 나서","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"書く → 書いた + あとで / 飲む → 飲んだ + あとで"},{"w":"2그룹 동사","f":"食べる → 食べた + あとで"},{"w":"する","f":"する → した + あとで (勉強した + あとで)"},{"w":"来る","f":"来る(くる) → 来た(きた) + あとで"}],"rule":["먼저 한 동작의 동사를 た형으로 바꾼다.","2그룹 동사는 끝의 る를 빼고 た를 붙인다(食べる -> 食べた).","1그룹 동사는 て형과 같은 소리 변화 뒤 た·だ를 붙인다(書く -> 書いた, 飲む -> 飲んだ). する는 した, 来る는 来た(きた).","た형 뒤에 あとで를 붙이고, 뒷문장에 나중 동작을 쓴다."],"why":"あと(後)는 '뒤'라는 명사이고 で가 그 시점을 나타낸다. 앞 동작은 이미 끝난 일이므로, 뒷문장이 미래라도 앞 동사는 항상 た형이다.","nu":"회화·문장 모두 쓴다. 한국어 '먹을 후에'처럼 사전형(食べるあとで)을 쓰면 틀린다. 정해진 절차의 순서(신발을 벗고 들어가기 등)를 말할 때는 てから가 더 자연스럽다.","cmp":[{"g":"～てから","d":"てから는 'A를 먼저 끝내고 그다음 B'라는 순서·전제를 강조한다. たあとで는 단순히 시간상 뒤라는 것만 말한다."},{"g":"～前に","d":"반대로 '~하기 전에'. 동사는 사전형 + 前に(寝る前に)."}],"ex":[{"jp":"宿題[しゅくだい]をしたあとで、テレビを見[み]ました。","ko":"숙제를 한 뒤에 TV를 봤어요."},{"jp":"ご飯[はん]を食[た]べたあとで、歯[は]を磨[みが]きます。","ko":"밥을 먹은 뒤에 이를 닦아요."},{"jp":"友[とも]だちが帰[かえ]ったあとで、部屋[へや]を掃除[そうじ]しました。","ko":"친구가 돌아간 뒤에 방을 청소했어요."}],"dr":[{"t":"make","q":"見る → ～たあとで","a":"見たあとで","hint":"2그룹: る를 빼고 た, 그다음 あとで."},{"t":"make","q":"読む → ～たあとで","a":"読んだあとで","hint":"1그룹 む는 ん+だ로 바뀐다."},{"t":"fill","q":"仕事[しごと]が終[お]わった（　）、ジムに行[い]きます。","a":"あとで","opts":["あとで","まえに","ながら","ために"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei11_2.pdf","https://bunpro.jp/grammar_points/64"],"vf":1,"u":7,"g":1,"gp":"gg_N5_04"},{"id":"g5_048","t":"～てから","ko":"~하고 나서, ~한 다음에","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"洗う → 洗って + から"},{"w":"2그룹 동사","f":"食べる → 食べて + から"},{"w":"する","f":"する → して + から (宿題をして + から)"},{"w":"来る","f":"来る(くる) → 来て(きて) + から"}],"rule":["먼저 할 동작의 동사를 て형으로 바꾼다(洗う -> 洗って, 食べる -> 食べて).","て형 뒤에 から를 붙인다.","뒷문장에 그다음 동작을 쓴다: 'A를 끝내고 나서 B'.","시제와 정중함은 뒷문장 동사가 정하고, 앞의 てから는 바뀌지 않는다."],"why":"から는 '~부터'라는 기점의 조사로, て형에 붙어 'A를 한 시점부터 B'라는 순서를 나타낸다.","nu":"회화·문장 모두 쓴다. A가 끝나야 B를 한다는 순서·전제를 강조하므로 절차 설명에 잘 맞는다. た형 + から(食べたから)나 사전형 + から(食べるから)는 '~니까(이유)'가 되므로 혼동 주의. '日本に来てから一年です'처럼 '~한 이래로'의 뜻도 있다.","cmp":[{"g":"～たあとで","d":"たあとで는 시간상 뒤라는 것만 말한다. 절차 순서(手を洗ってから食べます)는 てから가 자연스럽다."},{"g":"～て、～","d":"て는 동작을 단순히 잇는다. てから는 '먼저 A를 끝내고'를 더 분명히 한다."}],"ex":[{"jp":"手[て]を洗[あら]ってから、ご飯[はん]を食[た]べます。","ko":"손을 씻고 나서 밥을 먹어요."},{"jp":"宿題[しゅくだい]をしてから、遊[あそ]びに行[い]きました。","ko":"숙제를 하고 나서 놀러 갔어요."},{"jp":"日本[にほん]に来[き]てから、毎日[まいにち]日本語[にほんご]を話[はな]しています。","ko":"일본에 오고 나서 매일 일본어를 하고 있어요."}],"dr":[{"t":"make","q":"シャワーを浴びる → ～てから","a":"シャワーを浴びてから","hint":"2그룹: る를 て로, 그다음 から."},{"t":"make","q":"電話する → ～てから","a":"電話してから","hint":"する는 して, 그다음 から."},{"t":"fill","q":"靴[くつ]を脱[ぬ]いで（　）、部屋[へや]に入[はい]ってください。","a":"から","opts":["から","まえに","ながら","ので"]}],"src":["https://bunpro.jp/grammar_points/64","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei11_2.pdf"],"vf":1,"u":7,"g":1,"gp":"gg_N5_04"},{"id":"g5_061","t":"～前に","ko":"~하기 전에, ~ 전에","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"寝る + 前に → 寝る前に"},{"w":"동사 사전형(する)","f":"勉強する + 前に → 勉強する前に"},{"w":"명사","f":"食事 + の + 前に → 食事の前に"},{"w":"기간(수량)","f":"三年 + 前に → 三年前に(3년 전에)"}],"rule":["동사는 사전형 그대로 두고 뒤에 前に를 붙인다(寝る → 寝る前に). 어미가 바뀌지 않는다.","문장 전체가 과거라도 前に 앞의 동사는 과거형으로 바꾸지 않고 사전형을 쓴다(寝る前に歯を磨きました).","명사는 の를 넣어 연결한다(食事の前に).","기간을 나타내는 말에는 の 없이 바로 붙여 '~ 전(에)'이 된다(三年前に)."],"why":"前(まえ, 앞)라는 명사에 시점을 나타내는 조사 に가 붙은 형태다. 동사가 명사 前를 꾸미므로 연체형(=사전형)이 오고, 명사가 꾸밀 때는 の가 들어간다.","nu":"회화·문어 모두 쓰는 기본 표현. 앞 동작(前に 앞)은 아직 일어나지 않은 일이므로 항상 사전형이다. 한국어 '먹었기 전에'처럼 과거로 바꾸는 실수(×食べた前に)에 주의. 반대 의미는 ～た後で(~한 후에).","cmp":[{"g":"～た後で","d":"後で는 동작이 끝난 뒤를 말하므로 앞에 た형이 온다(食べた後で). 前に는 사전형(食べる前に)."},{"g":"～までに","d":"までに는 '~까지(기한)'로 마감 시점 안에 끝냄을 강조하고, 前に는 단순히 어떤 일보다 앞서는 순서를 말한다."}],"ex":[{"jp":"寝[ね]る前[まえ]に、歯[は]を磨[みが]きます。","ko":"자기 전에 이를 닦습니다."},{"jp":"出[で]かける前[まえ]に、窓[まど]を閉[し]めてください。","ko":"나가기 전에 창문을 닫아 주세요."},{"jp":"食事[しょくじ]の前[まえ]に、手[て]を洗[あら]いましょう。","ko":"식사 전에 손을 씻읍시다."}],"dr":[{"t":"make","q":"日本へ来る → ～前に","a":"日本へ来る前に","hint":"동사 사전형 그대로 + 前に."},{"t":"make","q":"ご飯 → ～前に","a":"ご飯の前に","hint":"명사는 の를 넣고 前に."},{"t":"fill","q":"テストを始[はじ]める（　）、名前[なまえ]を書[か]いてください。","a":"前に","opts":["前に","後で","ながら","たり"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/前に-まえに-mae-ni-meaning"],"vf":1,"u":7,"g":1,"gp":"gg_N5_05"},{"id":"g5_099","t":"～とき","ko":"~할 때, ~일 때","cat":"시간·순서","conn":[{"w":"동사 사전형 (아직 끝나지 않은 일)","f":"日本[にほん]へ行[い]くとき"},{"w":"동사 た형 (이미 끝난 일)","f":"日本[にほん]へ行[い]ったとき"},{"w":"い형용사","f":"寒[さむ]いとき"},{"w":"な형용사 + な","f":"暇[ひま]なとき"},{"w":"명사 + の","f":"子[こ]どものとき"}],"rule":["명사는 뒤에 の를 붙이고 とき를 놓는다(子ども → 子どものとき).","な형용사는 な를 붙인다(暇 → 暇なとき). い형용사는 그대로 붙인다(寒いとき).","동사는 보통형에 바로 とき를 붙인다. 바꾸는 글자는 없다.","동사의 시제는 뒤 문장과 비교해 정한다. とき 앞의 일이 아직이면 사전형(行くとき), 먼저 끝났으면 た형(行ったとき)."],"why":"とき는 명사 時(시간·때)이다. 그래서 명사를 꾸미는 규칙 그대로 명사는 の, な형용사는 な를 붙이고 동사·い형용사는 바로 붙는다.","nu":"회화·문장 모두 쓴다. 한국어 '~할 때'는 시제 구분이 약하지만, 일본어는 行くとき(가기 전·가는 길에)와 行ったとき(도착한 뒤에)의 뜻이 달라지므로 주의한다. 주절이 미래여도 먼저 끝나는 일은 た형을 쓴다(着いたとき、電話します). 명사에 の, な형용사에 な를 빼먹는 실수가 많다. 강조해 とき に 형태로도 쓴다.","cmp":[{"g":"～あいだ(に)","d":"あいだ는 일정 기간 동안을 나타내고, とき는 그 시점을 가리킨다."}],"ex":[{"jp":"子[こ]どものとき、よく川[かわ]で遊[あそ]びました。","ko":"어릴 때 자주 강에서 놀았습니다."},{"jp":"暇[ひま]なとき、本[ほん]を読[よ]みます。","ko":"한가할 때 책을 읽습니다."},{"jp":"日本[にほん]へ行[い]ったとき、この時計[とけい]を買[か]いました。","ko":"일본에 갔을 때 이 시계를 샀습니다."}],"dr":[{"t":"make","q":"学生[がくせい] → ～とき","a":"学生のとき","hint":"명사는 の를 붙이고 とき"},{"t":"make","q":"静[しず]か → ～とき","a":"静かなとき","hint":"な형용사는 な를 붙이고 とき"},{"t":"fill","q":"寒[さむ]い（　）、コートを着[き]ます。","a":"とき","opts":["とき","のとき","なとき","まえに"]}],"src":["https://aiueo.cc/pages_v2/ja/grammar/web/93.php","https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8D","https://elon.io/grammar/japanese/conjunctions/toki-when"],"vf":1,"u":7,"g":1,"gp":"gg_N5_05"},{"id":"g5_130","t":"まだ～ないです","ko":"아직 ~하지 않았어요","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"書く → まだ書いていないです"},{"w":"2그룹 동사","f":"食べる → まだ食べていないです"},{"w":"する / 来る","f":"まだしていないです / まだ来ていないです"},{"w":"い형용사","f":"寒い → まだ寒くないです"}],"rule":["동사를 て형으로 바꾼다(食べる의 る를 떼고 て → 食べて).","て형 뒤에 いる의 부정 いない를 붙인다(食べていない).","앞에 まだ, 뒤에 です를 붙여 정중하게 만든다(まだ食べていないです).","い형용사는 끝의 い를 くない로 바꾼 뒤 です를 붙인다(寒い → まだ寒くないです)."],"why":"～ていない는 ～ている의 부정이라 '아직 그 동작이 일어난 상태가 아니다'를 나타낸다. ないです는 보통형 부정 ない에 です를 더한 정중형이다.","nu":"ないです와 ません은 둘 다 정중한 부정이지만, ないです는 말할 때 많이 쓰고 특히 い형용사 뒤(寒くないです)에서 흔하다. 윗사람에게 보내는 메일 등에서는 ません 쪽이 무난하다. 한국어 '아직 안 먹었어요'의 과거형에 끌려 まだ食べなかったです라고 하는 실수가 많다.","cmp":[{"g":"まだ～ていません","d":"뜻은 같다. ません이 더 격식 있는 정중형."}],"ex":[{"jp":"まだ宿題[しゅくだい]をしていないです。","ko":"아직 숙제를 안 했어요."},{"jp":"バスはまだ来[き]ていないです。","ko":"버스는 아직 안 왔어요."},{"jp":"四月[しがつ]ですが、まだ暖[あたた]かくないです。","ko":"4월인데 아직 따뜻하지 않아요."}],"dr":[{"t":"make","q":"食べる → まだ～ないです","a":"まだ食べていないです","hint":"る를 떼고 て, 이어서 いない + です."},{"t":"make","q":"書く → まだ～ないです","a":"まだ書いていないです","hint":"く는 いて로 바뀐다(イ음편)."},{"t":"fill","q":"A：もう昼[ひる]ご飯[はん]を食[た]べましたか。B：いいえ、まだ食[た]べて（　）。","a":"いないです","opts":["いないです","いました","います","ありません"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A0-%E3%81%A6%E3%81%84%E3%81%BE%E3%81%9B%E3%82%93","https://hiroshima.repo.nii.ac.jp/records/2031546"],"vf":1,"u":7,"g":1,"gp":"gg_N5_05"},{"id":"g5_131","t":"まだ～ません","ko":"아직 ~하지 않았습니다","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"読む → まだ読んでいません"},{"w":"2그룹 동사","f":"起きる → まだ起きていません"},{"w":"する / 来る","f":"まだしていません / まだ来ていません"},{"w":"상태 동사 (わかる 등)","f":"まだわかりません"}],"rule":["동사를 て형으로 바꾼다. む로 끝나는 1그룹 동사는 む를 んで로 바꾼다(読む → 読んで).","て형 뒤에 いる의 정중 부정 いません을 붙인다(読んでいません).","맨 앞에 まだ를 둔다(まだ読んでいません).","질문 もう～ましたか에 짧게 답할 때는 いいえ、まだです라고 한다."],"why":"いません은 いる의 ます형 부정이다. ～ている(그 상태에 있다)를 부정하므로 '아직 그 동작을 한 상태가 아니다'라는 뜻이 된다.","nu":"정중체. 한국어 '아직 안 읽었습니다'의 과거형에 끌려 まだ読みませんでした라고 하면 틀린다. 끝났는지 묻는 もう～ましたか에는 まだ～ていません으로 답한다. わかる처럼 상태를 나타내는 동사는 まだわかりません처럼 ています 없이 쓴다.","cmp":[{"g":"まだ～ないです","d":"뜻은 같고, 회화에서 조금 가볍게 들린다."},{"g":"～ませんでした","d":"과거의 어느 때에 하지 않았다는 사실. 지금까지 아직 안 한 상태는 ていません."}],"ex":[{"jp":"その本[ほん]はまだ読[よ]んでいません。","ko":"그 책은 아직 안 읽었습니다."},{"jp":"父[ちち]はまだ帰[かえ]っていません。","ko":"아버지는 아직 안 돌아오셨습니다."},{"jp":"レポートはまだ出[だ]していません。","ko":"리포트는 아직 제출하지 않았습니다."}],"dr":[{"t":"make","q":"読む → まだ～ていません","a":"まだ読んでいません","hint":"む → んで, 이어서 いません."},{"t":"make","q":"帰る → まだ～ていません","a":"まだ帰っていません","hint":"帰る는 1그룹이라 る → って."},{"t":"fill","q":"A：もう宿題[しゅくだい]をしましたか。B：いいえ、まだ（　）。","a":"していません","opts":["していません","しませんでした","しました","しています"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A0-%E3%81%A6%E3%81%84%E3%81%BE%E3%81%9B%E3%82%93","https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A0"],"vf":1,"u":7,"g":1,"gp":"gg_N5_05"},{"id":"g5_073","t":"～から、～","ko":"~니까, ~때문에","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"ある + から → あるから"},{"w":"い형용사","f":"寒い + から → 寒いから"},{"w":"な형용사","f":"静か + だ + から → 静かだから"},{"w":"명사","f":"雨 + だ + から → 雨だから"},{"w":"정중형(매우 정중)","f":"雨です + から / 行きます + から"}],"rule":["동사와 い형용사는 보통형 그대로 から를 붙인다(寒い → 寒いから).","な형용사와 명사는 だ를 넣은 다음 から를 붙인다(雨 → 雨だ → 雨だから).","정중하게 말할 때는 です・ます 뒤에 から를 붙일 수도 있다(雨ですから).","から로 끝난 앞 절이 이유, 쉼표 뒤의 절이 그 결과·판단·부탁이 된다."],"why":"から는 이유를 나타내는 접속조사로, 앞 문장을 그대로 받아 뒤 문장의 근거로 잇는다. 명사·な형용사는 문장을 끝맺는 だ가 있어야 하므로 だ를 넣고 から를 붙인다.","nu":"회화에서 많이 쓰는 말투로, 말하는 사람의 주관적인 이유를 직접 드러낸다. 그래서 뒤에 명령·부탁·의지(~てください, ~よう)가 자연스럽게 온다. 한국어 '~니까'처럼 쓰면 되지만, 명사 뒤에 だ를 빼고 '雨から'라고 하면 '비로부터'라는 다른 뜻이 되므로 주의.","cmp":[{"g":"～ので","d":"ので는 객관적·부드러운 이유 설명으로 정중한 자리에서 무난하다. から는 주관적이고 직접적이라 친한 사이에서 부탁·명령과 잘 어울린다."},{"g":"だから","d":"だから는 문장 맨 앞에 오는 접속사(그러니까). から는 앞 문장 끝에 붙는다."}],"ex":[{"jp":"明日[あした]テストがあるから、今日[きょう]は早[はや]く寝[ね]ます。","ko":"내일 시험이 있으니까 오늘은 일찍 잘게요."},{"jp":"この部屋[へや]は寒[さむ]いから、窓[まど]を閉[し]めてください。","ko":"이 방은 추우니까 창문을 닫아 주세요."},{"jp":"雨[あめ]だから、傘[かさ]を持[も]っていきましょう。","ko":"비가 오니까 우산을 가져갑시다."}],"dr":[{"t":"make","q":"日曜日 → ～から","a":"日曜日だから","hint":"명사는 だ를 넣고 から를 붙인다."},{"t":"make","q":"高い → ～から","a":"高いから","hint":"い형용사는 그대로 から를 붙인다."},{"t":"fill","q":"暑[あつ]い（　）、水[みず]をたくさん飲[の]んでください。","a":"から","opts":["から","けど","まで","より"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%82%89-because","https://www.erin.jpf.go.jp/materials/key-phrases/download/erin_lesson19_key-phrases_explanation.pdf","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201612.html","https://www.seirei.ac.jp/media/about_setsuzoku-shi.pdf"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_074","t":"～からです","ko":"~이기 때문입니다, ~해서요","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"寝坊した + からです"},{"w":"い형용사","f":"安い + からです"},{"w":"な형용사","f":"好き + だ + からです → 好きだからです"},{"w":"명사","f":"休み + だ + からです → 休みだからです"}],"rule":["이유가 되는 말을 보통형으로 만든다(寝坊する → 寝坊した).","から를 붙인다. な형용사·명사는 だ를 먼저 넣는다(好きだから).","문장 끝에 です를 붙여 '~이기 때문입니다'로 맺는다(寝坊したからです)."],"why":"이유의 から로 끝난 절 뒤에 です를 붙여, 이유 자체를 문장의 술어로 만든 형태다. 그래서 결과를 먼저 말하고 이유를 나중에 따로 말할 때 쓴다.","nu":"どうして~か / なぜ~か 질문에 대한 대답이나, '~のは ~からです'(~한 것은 ~때문입니다) 형태로 결과를 먼저 말하고 이유를 뒤에 덧붙일 때 쓴다. 반말에서는 から로 끝내거나(寝坊したから) からだ를 쓴다. 한국 학습자는 です 앞에 정중형을 넣어 '寝坊しましたからです'라고 하기 쉬운데, から 앞은 보통형이 기본이다.","cmp":[{"g":"～から、～","d":"から、~는 이유를 먼저 말하고 결과를 이어 말한다. からです는 결과를 먼저 말한 뒤 이유만 따로 문장으로 말한다."}],"ex":[{"jp":"A：どうして遅[おく]れたんですか。B：寝坊[ねぼう]したからです。","ko":"A: 왜 늦었어요? B: 늦잠을 잤기 때문이에요."},{"jp":"この店[みせ]によく来[く]るのは、安[やす]いからです。","ko":"이 가게에 자주 오는 것은 싸기 때문입니다."},{"jp":"今日[きょう]学校[がっこう]がないのは、休[やす]みだからです。","ko":"오늘 학교가 없는 것은 휴일이기 때문입니다."}],"dr":[{"t":"make","q":"好き → ～からです","a":"好きだからです","hint":"な형용사는 だ를 넣고 からです."},{"t":"make","q":"頭が痛い → ～からです","a":"頭が痛いからです","hint":"い형용사는 그대로 からです."},{"t":"fill","q":"A：どうして学校[がっこう]に行[い]かないんですか。B：今日[きょう]は休[やす]み（　）。","a":"だからです","opts":["だからです","からです","なからです","のからです"]}],"src":["https://www.erin.jpf.go.jp/materials/key-phrases/download/erin_lesson19_key-phrases_explanation.pdf","https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%82%89-because","https://oercollective.caul.edu.au/japanese/?p=3280"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_088","t":"だから、～","ko":"그러니까, 그래서","cat":"원인·이유","conn":[{"w":"문장 맨 앞(접속사)","f":"雨だ。だから、傘を持っていく。"},{"w":"정중형","f":"雨です。ですから、傘を持っていきます。"}],"rule":["앞 문장에서 이유를 말하고 일단 끝낸다(雨だ。).","다음 문장 맨 앞에 だから를 놓고, 그 이유에서 나오는 결과·판단을 말한다.","だから는 단정의 だ + から가 합쳐진 한 단어이며, 그 자체는 활용하지 않는다.","정중하게 말할 때는 ですから로 바꾼다."],"why":"단정의 조동사 だ에 이유를 나타내는 접속조사 から가 붙은 것이 하나의 접속사로 굳어진 말이다(사전 기록상 에도 시대 말 용례가 있다).","nu":"회화체. 친한 사이에서 자연스럽고, 윗사람에게는 ですから를 쓴다. 강하게 말하면 '그러니까 말했잖아'처럼 따지는 느낌이 날 수 있다. '雨だから、…'처럼 문장 끝에 붙은 だから는 접속사가 아니라 だ + から(~니까) 용법이므로, だから를 문장 앞에 쓰는 형태와 구별해야 한다.","cmp":[{"g":"～から","d":"から는 앞 문장 끝에 붙는다(雨だから、…). だから는 문장을 끊은 뒤 다음 문장 맨 앞에 온다(雨だ。だから、…)."},{"g":"それで","d":"それで는 일어난 사실의 경과를 설명하는 '그래서'로, 뒤에 명령·의지가 오기 어렵다. だから는 말하는 사람의 판단·부탁도 이을 수 있다."}],"ex":[{"jp":"今日[きょう]は雨[あめ]だ。だから、傘[かさ]を持[も]っていく。","ko":"오늘은 비가 와. 그러니까 우산을 가져갈 거야."},{"jp":"明日[あした]はテストです。ですから、今日[きょう]は早[はや]く寝[ね]ます。","ko":"내일은 시험입니다. 그래서 오늘은 일찍 잡니다."},{"jp":"この店[みせ]は安[やす]い。だから、いつも人[ひと]が多[おお]い。","ko":"이 가게는 싸. 그래서 늘 사람이 많아."}],"dr":[{"t":"make","q":"お腹がすいた。／ご飯を食べる。 → だから로 잇기","a":"お腹がすいた。だから、ご飯を食べる。","hint":"이유 문장을 끝내고 다음 문장 맨 앞에 だから를 놓는다."},{"t":"make","q":"だから → 정중하게","a":"ですから","hint":"だ를 정중한 です로 바꾼다."},{"t":"fill","q":"道[みち]が込[こ]んでいました。（　）、遅[おく]れました。","a":"だから","opts":["だから","でも","それとも","しかし"]}],"src":["https://kotobank.jp/word/%E3%81%A0%E3%81%8B%E3%82%89","https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%82%89-because"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_120","t":"なんで","ko":"왜, 어째서 (회화체)","cat":"원인·이유","conn":[{"w":"なんで + 동사 보통형 + の","f":"なんで遅れたの"},{"w":"なんで + い형용사 + の","f":"なんでこんなに高いの"},{"w":"なんで + な형용사·명사 + なの","f":"なんで静かなの"},{"w":"정중하게: どうして + ～んですか","f":"どうして遅れたんですか"}],"rule":["문장 앞에 なんで를 두어 이유를 묻는다(なんで + 遅れたの).","친구끼리는 문말을 の로 끝내는 경우가 많다(遅れたの？).","정중하게 물을 때는 なんで를 どうして로 바꾸고 문말을 ～んですか로 한다(なんで遅れたの → どうして遅れたんですか).","대답은 ～から / ～ので로 이유를 말한다."],"why":"何で를 なんで로 읽은 것으로, 何가 で 앞에서 なん이 되는 규칙에 따른 형태다. 같은 何で가 수단·재료를 묻는 뜻(무엇으로)도 가진다.","nu":"주로 회화체로 친구·가족에게 쓴다. 중립적인 말은 どうして, 딱딱하고 글에 많이 쓰는 말은 なぜ. 윗사람에게 なんで로 따지듯 물으면 실례가 될 수 있다. 何で来ましたか는 '왜 왔어요?'와 '무엇으로(교통수단) 왔어요?' 두 가지로 들릴 수 있으므로, 수단을 물을 때는 なにで를 쓰면 혼동이 없다.","cmp":[{"g":"どうして","d":"뜻은 같지만 회화·문장 어디서나 쓰는 중립적인 말."},{"g":"なぜ","d":"격식·문어적이며 논리적인 이유를 물을 때 잘 쓴다."}],"ex":[{"jp":"なんで遅[おく]れたの？","ko":"왜 늦었어?"},{"jp":"なんでこの部屋[へや]はこんなに寒[さむ]いの？","ko":"왜 이 방은 이렇게 추워?"},{"jp":"なんで日本語[にほんご]を勉強[べんきょう]しているの？","ko":"왜 일본어를 공부하고 있어?"}],"dr":[{"t":"make","q":"どうして遅れたんですか → 친구에게 반말로","a":"なんで遅れたの","hint":"どうして → なんで, ～んですか → ～の."},{"t":"make","q":"なんで来なかったの → 정중하게","a":"どうして来なかったんですか","hint":"なんで → どうして, ～の → ～んですか."},{"t":"fill","q":"A：（　）泣[な]いているの？B：映画[えいが]が悲[かな]しかったから。","a":"なんで","opts":["なんで","なにで","なにか","なんの"]}],"src":["https://aiueo.cc/pages_v2/ja/grammar/web/19.php","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei06_6.pdf","https://en.wiktionary.com/wiki/%E3%81%AA%E3%82%93%E3%81%A7","https://community.bunpro.jp/t/topic/96800"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_052","t":"Vに来ます","ko":"~하러 옵니다","cat":"목적","conn":[{"w":"1그룹 동사(ます형)","f":"会う → 会い + に来ます"},{"w":"2그룹 동사(ます형)","f":"見る → 見 + に来ます"},{"w":"する동사","f":"質問する → 質問し + に来ます"},{"w":"동작성 명사","f":"買い物 + に来ます / 勉強 + に来ます"}],"rule":["동사를 ます형으로 바꾼 뒤 ます를 뗀다. 1그룹은 어미 う단을 い단으로(会う → 会い), 2그룹은 る를 뗀다(見る → 見).","する는 し, 来る는 き가 된다(質問する → 質問し).","그 뒤에 목적을 나타내는 に를 붙이고 이동 동사 来ます를 쓴다(会い + に + 来ます).","勉強・買い物 같은 동작성 명사는 명사 그대로 + に来ます로 쓸 수 있다."],"why":"ます형에서 ます를 뗀 부분(연용형)은 명사처럼 쓰일 수 있어서, 목적·도착점을 나타내는 に가 붙어 '~하는 것을 위해' 이동한다는 뜻이 된다.","nu":"뒤에는 来る・行く・帰る 같은 이동 동사만 온다. 来る는 말하는 사람이 있는 곳으로 오는 것이므로 화자 쪽 장소에 쓴다. 장소는 へ나 に로 표시하며, 거기서 행동을 하더라도 で를 쓰지 않는다(図書館で本を借りに来ました는 틀림, 図書館へ). 목적 문장은 何をしに来ましたか로 묻는다.","cmp":[{"g":"Vに行きます","d":"来ます는 말하는 사람 쪽으로 오는 것, 行きます는 말하는 사람이 있는 곳에서 멀어져 가는 것."}],"ex":[{"jp":"友達[ともだち]に会[あ]いに来[き]ました。","ko":"친구를 만나러 왔습니다."},{"jp":"日本[にほん]へ日本語[にほんご]を勉強[べんきょう]しに来[き]ました。","ko":"일본에 일본어를 공부하러 왔습니다."},{"jp":"明日[あした]、また本[ほん]を借[か]りに来[き]ます。","ko":"내일 또 책을 빌리러 오겠습니다."}],"dr":[{"t":"make","q":"遊ぶ → Vに来ます","a":"遊びに来ます","hint":"ぶ를 び로 바꾼 ます형 어간 + に来ます."},{"t":"make","q":"食べる → Vに来ました","a":"食べに来ました","hint":"2그룹, る를 떼고 に来ました."},{"t":"fill","q":"先生[せんせい]に質問[しつもん]し（　）来[き]ました。","a":"に","opts":["に","て","で","を"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei05_7.pdf","https://bunpro.jp/ja/grammar_points/verb-%E3%81%AB%E3%81%84%E3%81%8F"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_053","t":"Vに行きます","ko":"~하러 갑니다","cat":"목적","conn":[{"w":"1그룹 동사(ます형)","f":"遊ぶ → 遊び + に行きます"},{"w":"2그룹 동사(ます형)","f":"見る → 見 + に行きます"},{"w":"する동사","f":"勉強する → 勉強し + に行きます"},{"w":"동작성 명사","f":"買い物 + に行きます / 散歩 + に行きます"}],"rule":["동사를 ます형으로 바꾼 뒤 ます를 뗀다. 1그룹은 어미 う단을 い단으로(遊ぶ → 遊び), 2그룹은 る를 뗀다(見る → 見).","する는 し, 来る는 き가 된다.","그 뒤에 목적을 나타내는 に를 붙이고 行きます를 쓴다(遊び + に + 行きます).","買い物・散歩 같은 동작성 명사는 명사 그대로 + に行きます로 쓸 수 있다."],"why":"ます를 뗀 연용형이 명사처럼 쓰여 목적을 나타내는 に가 붙고, 그 목적을 위해 '가다'라는 뜻이 된다.","nu":"뒤에는 이동 동사만 온다. 목적지는 へ로 표시하는 것이 기본이고(公園へ遊びに行きます), 그곳에서 행동을 하더라도 で를 쓰지 않는다. 목적지와 목적을 둘 다 に로 쓰면 に가 겹치므로 목적지는 へ를 쓰는 편이 깔끔하다. 물을 때는 何をしに行きますか.","cmp":[{"g":"～ために行きます","d":"に行きます는 '~하러' 가는 가벼운 목적, ために는 더 무겁고 분명한 목적이며 ます형이 아닌 사전형에 붙는다."}],"ex":[{"jp":"日曜日[にちようび]、公園[こうえん]へ遊[あそ]びに行[い]きます。","ko":"일요일에 공원에 놀러 갑니다."},{"jp":"図書館[としょかん]へ勉強[べんきょう]しに行[い]きました。","ko":"도서관에 공부하러 갔습니다."},{"jp":"駅前[えきまえ]のスーパーへ買[か]い物[もの]に行[い]きます。","ko":"역 앞 슈퍼에 장 보러 갑니다."}],"dr":[{"t":"make","q":"泳ぐ → Vに行きます","a":"泳ぎに行きます","hint":"ぐ를 ぎ로 바꾼 ます형 어간 + に行きます."},{"t":"make","q":"映画を見る → Vに行きます","a":"映画を見に行きます","hint":"2그룹, る를 떼고 に行きます."},{"t":"fill","q":"海[うみ]へ泳[およ]ぎ（　）行[い]きました。","a":"に","opts":["に","で","を","から"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei05_7.pdf","https://bunpro.jp/ja/grammar_points/verb-%E3%81%AB%E3%81%84%E3%81%8F"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_002","t":"～。けれども、～","ko":"~. 하지만, 그렇지만","cat":"역접","conn":[{"w":"문장(보통체)","f":"晴れている。けれども、寒い。"},{"w":"문장(정중체)","f":"晴れています。けれども、寒いです。"},{"w":"(참고) 접속조사로 문장 중간","f":"晴れているけれども、寒い。"}],"rule":["앞 문장 A를 。로 끝낸다.","다음 문장 맨 앞에 けれども를 놓고 、를 찍는다.","뒤 문장 B에는 A에서 예상되는 것과 반대되는 내용을 쓴다.","けれども 자체는 활용하지 않으며, A·B의 보통체/정중체는 서로 맞춘다."],"why":"けど·けれど·けれども는 같은 계열의 말로, けど가 가장 짧고 가벼운 형태, けれども가 가장 온전한 형태다.","nu":"だけど·でも보다 조금 정돈된 느낌이지만 경어는 아니다. 공식 문서·논문에는 しかし가 더 어울린다. 문장 중간에 붙이는 접속조사 용법(～けれども、～)과 문장 첫머리 접속사 용법이 모두 있다.","cmp":[{"g":"しかし","d":"しかし는 딱딱하고 글말 느낌이 강하다. けれども는 회화에도 무난하다."},{"g":"でも","d":"でも는 더 구어적이고 가볍다."}],"ex":[{"jp":"今日[きょう]は晴[は]れています。けれども、とても寒[さむ]いです。","ko":"오늘은 맑아요. 하지만 아주 추워요."},{"jp":"この店[みせ]は小[ちい]さいです。けれども、いつも人[ひと]が多[おお]いです。","ko":"이 가게는 작아요. 그렇지만 항상 사람이 많아요."},{"jp":"たくさん練習[れんしゅう]しました。けれども、勝[か]てませんでした。","ko":"많이 연습했어요. 하지만 이기지 못했어요."}],"dr":[{"t":"make","q":"晴れています / 寒いです → けれども","a":"晴れています。けれども、寒いです。","hint":"A 문장 。 + けれども、 + B 문장."},{"t":"make","q":"高いです / おいしいです → けれども","a":"高いです。けれども、おいしいです。","hint":"예상과 반대되는 B 앞에 けれども、를 놓는다."},{"t":"fill","q":"この本[ほん]は古[ふる]いです。（　）、とても面白[おもしろ]いです。","a":"けれども","opts":["けれども","だから","それから","たとえば"]}],"src":["https://bunpro.jp/ja/grammar_points/361","https://news.mynavi.jp/article/20231025-2786232/"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_003","t":"～。しかし、～","ko":"~. 그러나, 하지만","cat":"역접","conn":[{"w":"문장(보통체)","f":"高い。しかし、おいしい。"},{"w":"문장(정중체)","f":"高いです。しかし、おいしいです。"}],"rule":["앞 문장 A를 。로 끝낸다.","다음 문장 맨 앞에 しかし를 놓고 、를 찍는다.","뒤 문장 B는 A와 대립하거나 A에서 예상되는 것과 다른 내용이다.","しかし는 접속사이므로 앞 문장에 직접 붙지 않고 반드시 새 문장 첫머리에 온다."],"why":"しかし는 흔히 しかしながら를 줄인 꼴로 여겨지며 뜻은 거의 같다.","nu":"딱딱한 말투로 글·뉴스·연설·발표에서 많이 쓴다. 친구와의 대화에는 でも·けど가 자연스럽다. けど처럼 앞 문장 끝에 붙여 쓰지 않는다(×高いしかし).","cmp":[{"g":"でも","d":"でも는 회화체. しかし는 글말·격식."},{"g":"けれども","d":"けれども는 접속조사로 문장 중간에도 붙지만, しかし는 문장 첫머리에만 온다."}],"ex":[{"jp":"この料理[りょうり]は高[たか]いです。しかし、とてもおいしいです。","ko":"이 요리는 비싸요. 그러나 아주 맛있어요."},{"jp":"彼[かれ]は疲[つか]れていた。しかし、宿題[しゅくだい]を全部[ぜんぶ]やった。","ko":"그는 지쳐 있었다. 그러나 숙제를 전부 했다."},{"jp":"駅[えき]は近[ちか]い。しかし、道[みち]がわかりにくい。","ko":"역은 가깝다. 그러나 길이 알기 어렵다."}],"dr":[{"t":"make","q":"高いです / おいしいです → しかし","a":"高いです。しかし、おいしいです。","hint":"A 。 다음 문장 첫머리에 しかし、."},{"t":"make","q":"勉強した / 試験はだめだった → しかし","a":"勉強した。しかし、試験はだめだった。","hint":"보통체 문장끼리 。しかし、로 잇는다."},{"t":"fill","q":"薬[くすり]を飲[の]みました。（　）、まだ頭[あたま]が痛[いた]いです。","a":"しかし","opts":["しかし","だから","そして","では"]}],"src":["https://news.mynavi.jp/article/20231025-2786232/","https://dime.jp/genre/1823870/"],"vf":1,"u":8,"g":1,"gp":"gg_N5_05"},{"id":"g5_008","t":"～。でも、～","ko":"~. 하지만, 그래도","cat":"역접","conn":[{"w":"문장(보통체)","f":"寒かった。でも、今日は暖かい。"},{"w":"문장(정중체)","f":"寒かったです。でも、今日は暖かいです。"}],"rule":["앞 문장 A를 。로 끝낸다.","다음 문장 첫머리에 でも를 놓고 、를 찍는다.","B에는 A와 반대되거나 A에서 예상되는 것과 다른 내용을 쓴다.","でも 자체는 활용하지 않는다(앞 문장에 붙여 쓰지 않음)."],"why":"","nu":"대표적인 회화체 역접 접속사. 친구·가족 대화에 자연스럽고, 변명을 꺼낼 때도 자주 쓰인다. 회의나 거래처 등 격식 있는 자리, 글에서는 しかし·ですが 등이 낫다. 명사 + でも('~라도')와 구별할 것.","cmp":[{"g":"しかし","d":"しかし는 글말·격식. でも는 회화체."},{"g":"けれども","d":"けれども는 상대 말을 일단 받아들이는 느낌이 있어 でも보다 부드럽게 들린다."}],"ex":[{"jp":"昨日[きのう]は寒[さむ]かった。でも、今日[きょう]は暖[あたた]かい。","ko":"어제는 추웠어. 하지만 오늘은 따뜻해."},{"jp":"この部屋[へや]は狭[せま]いです。でも、とても静[しず]かです。","ko":"이 방은 좁아요. 하지만 아주 조용해요."},{"jp":"テストは難[むずか]しかった。でも、全部[ぜんぶ]書[か]けたよ。","ko":"시험은 어려웠어. 그래도 다 썼어."}],"dr":[{"t":"make","q":"寒かった / 今日は暖かい → でも","a":"寒かった。でも、今日は暖かい。","hint":"A 。 + でも、 + 반대 내용 B."},{"t":"make","q":"忙しいです / 毎日運動します → でも","a":"忙しいです。でも、毎日運動します。","hint":"정중체끼리 。でも、로 잇는다."},{"t":"fill","q":"このかばんは安[やす]い。（　）、とても丈夫[じょうぶ]だ。","a":"でも","opts":["でも","だから","それに","では"]}],"src":["https://dime.jp/genre/1823870/","https://news.mynavi.jp/article/20231025-2786232/"],"vf":1,"u":8,"g":1,"gp":"gg_N5_06"},{"id":"g5_072","t":"～が、～（접속조사）","ko":"~지만, ~인데","cat":"역접","conn":[{"w":"동사","f":"行きました + が、"},{"w":"い형용사","f":"おいしい(です) + が、"},{"w":"な형용사","f":"便利だ / 便利です + が、"},{"w":"명사","f":"学生だ / 学生です + が、"}],"rule":["앞 문장을 종지형(문장이 끝나는 형태) 그대로 두고 が、를 붙인 뒤 뒷문장을 잇는다(おいしいが、高い).","정중체에도 그대로 붙인다(おいしいですが、高いです).","な형용사·명사는 だ 또는 です 뒤에 붙인다(便利だが / 便利ですが)."],"why":"사전에 따르면 접속조사 が는 활용어의 종지형에 붙어 앞뒤 내용이 반대됨(역접)을 나타내며, 단순히 앞말을 뒤로 이어 주는 용법도 있다.","nu":"역접(~지만) 외에 본론 앞에 까는 말로도 쓴다(すみませんが、…/ 明日のことですが、…). けど(けれど)보다 약간 딱딱해 보통체 + が는 글이나 뉴스에서, です·ます + が는 회화에서도 자연스럽다. な형용사·명사에서 だ를 빼고 ×便利が라고 하지 않도록 주의.","cmp":[{"g":"～けど","d":"뜻은 거의 같지만 けど는 회화체, が는 조금 더 격식 있는 말."},{"g":"～のに","d":"のに는 기대가 어긋난 불만·아쉬움이 담기고, が는 사실을 중립적으로 대비한다."}],"ex":[{"jp":"このレストランはおいしいですが、高[たか]いです。","ko":"이 레스토랑은 맛있지만 비싸요."},{"jp":"薬[くすり]を飲[の]みましたが、まだ頭[あたま]が痛[いた]いです。","ko":"약을 먹었지만 아직 머리가 아파요."},{"jp":"すみませんが、駅[えき]はどこですか。","ko":"죄송한데요, 역은 어디예요?"}],"dr":[{"t":"make","q":"部屋は広いです / 古いです → が로 잇기","a":"部屋は広いですが、古いです","hint":"앞 문장 끝에 が、를 붙인다."},{"t":"make","q":"この町は静かだ / 不便だ → が로 잇기","a":"この町は静かだが、不便だ","hint":"な형용사는 だ 뒤에 が."},{"t":"fill","q":"日本語[にほんご]は難[むずか]しいです（　）、おもしろいです。","a":"が","opts":["が","まで","へ","を"]}],"src":["https://kotobank.jp/word/が"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_077","t":"～けど、～","ko":"~지만, ~는데","cat":"역접","conn":[{"w":"동사 보통형","f":"行った + けど"},{"w":"い형용사","f":"高い + けど"},{"w":"な형용사","f":"きれい + だ + けど → きれいだけど"},{"w":"명사","f":"学生 + だ + けど → 学生だけど"},{"w":"정중형","f":"高いです + けど / 行きます + けど"}],"rule":["동사·い형용사는 보통형 그대로 けど를 붙인다(高い → 高いけど).","な형용사·명사는 だ를 넣은 다음 けど를 붙인다(きれい → きれいだ → きれいだけど).","정중하게 말할 때는 です・ます 뒤에 けど를 붙인다(きれいですけど).","けど 앞 절과 뒤 절은 서로 반대되거나 예상과 다른 내용이 된다."],"why":"けど는 けれども를 줄인 회화체 형태로, 뜻은 같고 격식만 다르다. 앞 문장을 그대로 받으므로 な형용사·명사는 だ가 필요하다.","nu":"친한 사이의 회화체. 역접(~지만) 외에 '~는데'처럼 화제를 꺼내는 앞말(すみません、ちょっと聞きたいんですけど…)이나, 뒤를 생략해 말을 부드럽게 흐리는 데도 많이 쓴다. な형용사 きれい·嫌い는 い로 끝나도 な형용사이므로 'きれいけど'가 아니라 'きれいだけど'.","cmp":[{"g":"～けれど／けれども","d":"뜻은 같고 けれども가 가장 격식, けど가 가장 회화체."},{"g":"～が","d":"が(~지만)는 회화·문어 모두에서 쓰는 좀 더 딱딱한 표현."}],"ex":[{"jp":"この服[ふく]はきれいだけど、ちょっと高[たか]い。","ko":"이 옷은 예쁘지만 좀 비싸."},{"jp":"昨日[きのう]は寒[さむ]かったけど、今日[きょう]は暖[あたた]かいね。","ko":"어제는 추웠는데 오늘은 따뜻하네."},{"jp":"たくさん食[た]べたけど、まだおなかがすいている。","ko":"많이 먹었지만 아직 배가 고파."}],"dr":[{"t":"make","q":"静か → ～けど","a":"静かだけど","hint":"な형용사는 だ를 넣고 けど."},{"t":"make","q":"雨 → ～けど","a":"雨だけど","hint":"명사도 だ를 넣고 けど."},{"t":"fill","q":"この店[みせ]は安[やす]い（　）、おいしくない。","a":"けど","opts":["けど","まで","を","へ"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%91%E3%81%A9-%E3%81%A0%E3%81%91%E3%81%A9","https://kotobank.jp/jeword/-%E3%81%91%E3%82%8C%E3%81%A9%28%E3%82%82%29"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_078","t":"～けれど、～","ko":"~지만, ~하였으나","cat":"역접","conn":[{"w":"동사 보통형","f":"待った + けれど"},{"w":"い형용사","f":"狭い + けれど"},{"w":"な형용사","f":"親切 + だ + けれど → 親切だけれど"},{"w":"명사","f":"日曜日 + だ + けれど → 日曜日だけれど"},{"w":"정중형","f":"狭いです + けれど / 待ちました + けれど"}],"rule":["동사·い형용사는 보통형 그대로 けれど를 붙인다(待った → 待ったけれど).","な형용사·명사는 だ를 넣은 다음 けれど를 붙인다(親切だけれど).","끝에 も를 붙여 けれども라고 해도 뜻은 같고, 조금 더 격식 있게 들린다."],"why":"けれど(けれども)는 역접을 나타내는 접속조사로, 회화에서는 이것을 줄인 けど를 많이 쓴다. 뜻은 같고 けれども → けれど → けど 순서로 격식이 낮아진다.","nu":"けど보다 조금 정돈된 말투로, 회화와 글 모두에 쓸 수 있다. 역접 외에 앞말(お願いがあるんですけれど…)이나 말끝을 부드럽게 흐리는 용법도 있다. 데이터에 있는 '親切けれど'처럼 だ를 빼는 것은 틀린 형태이며 '親切だけれど'가 맞다.","cmp":[{"g":"～けど","d":"けど는 けれど의 축약형으로 더 가볍고 친근한 회화체."},{"g":"～のに","d":"のに는 '~인데도'라는 불만·의외의 감정이 강하다. けれど는 단순히 대비만 나타낸다."}],"ex":[{"jp":"三十分[さんじゅっぷん]待[ま]ったけれど、友達[ともだち]は来[こ]なかった。","ko":"30분 기다렸지만 친구는 오지 않았다."},{"jp":"この部屋[へや]は狭[せま]いけれど、明[あか]るいです。","ko":"이 방은 좁지만 밝습니다."},{"jp":"彼[かれ]は親切[しんせつ]だけれど、少[すこ]し話[はな]しにくい。","ko":"그는 친절하지만 조금 말 붙이기 어렵다."}],"dr":[{"t":"make","q":"親切 → ～けれど","a":"親切だけれど","hint":"な형용사는 だ를 넣고 けれど."},{"t":"make","q":"勉強した → ～けれど","a":"勉強したけれど","hint":"동사 보통형은 그대로 けれど."},{"t":"fill","q":"薬[くすり]を飲[の]んだ（　）、まだ頭[あたま]が痛[いた]い。","a":"けれど","opts":["けれど","から","ので","ために"]}],"src":["https://kotobank.jp/jeword/-%E3%81%91%E3%82%8C%E3%81%A9%28%E3%82%82%29","https://bunpro.jp/grammar_points/%E3%81%91%E3%81%A9-%E3%81%A0%E3%81%91%E3%81%A9"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_001","t":"～が一番～","ko":"~이/가 가장(제일) ~","cat":"비교·정도","conn":[{"w":"명사","f":"すし + が一番 + 好きです"},{"w":"명사 + い형용사","f":"この公園 + が一番 + きれいです / 夏 + が一番 + 暑い"},{"w":"범위(명사 + の中で)","f":"果物の中で + りんご + が一番 + 好き"},{"w":"의문사","f":"何 / だれ / どこ / どれ + が一番 + ～ですか"}],"rule":["가장 ~한 대상(명사)에 조사 が를 붙인다.","그 뒤에 부사 一番(いちばん, 가장)을 놓고 형용사·동사 술어를 이어 쓴다.","비교 범위를 밝힐 때는 문장 앞에 '명사 + の中で'(~ 중에서)나 '명사 + で'를 둔다.","활용 변화는 없고 어순만 지키면 된다: 범위 → 대상 + が → 一番 → 술어."],"why":"一番은 원래 '첫 번째'라는 뜻의 명사로, 부사로 쓰이면 '가장, 제일'이 되어 최상급을 나타낸다. が는 '여럿 중 바로 이것'을 골라 내는 역할을 한다.","nu":"회화·문장 모두 쓰는 기본 표현. 범위는 셋 이상(그룹)일 때 쓰고, 둘을 비교할 때는 より / ほうが를 쓴다. 한국어 '~은 제일'에 끌려 は를 쓰기 쉬운데, 고르는 대상에는 が가 자연스럽다(예: 何が一番好きですか에 답할 때 すしが一番好きです).","cmp":[{"g":"AはBより～","d":"두 개만 비교할 때 쓴다. 一番은 셋 이상 그룹 안에서 '가장'."}],"ex":[{"jp":"果物[くだもの]の中[なか]で、りんごが一番[いちばん]好[す]きです。","ko":"과일 중에서 사과를 제일 좋아해요."},{"jp":"クラスでだれが一番[いちばん]背[せ]が高[たか]いですか。","ko":"반에서 누가 제일 키가 커요?"},{"jp":"兄[あに]が家族[かぞく]で一番[いちばん]早[はや]く起[お]きます。","ko":"형이 가족 중에서 제일 일찍 일어나요."}],"dr":[{"t":"make","q":"すし / 好きです → ～が一番～","a":"すしが一番好きです","hint":"대상 명사에 が, 그다음 一番, 마지막에 술어."},{"t":"make","q":"日本の山 / 富士山 / 高い → ～の中で～が一番～","a":"日本の山の中で富士山が一番高い","hint":"범위 + の中で → 대상 + が → 一番 → 형용사."},{"t":"fill","q":"スポーツの中[なか]で、サッカー（　）一番[いちばん]好[す]きです。","a":"が","opts":["が","を","より","に"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/の中でが一番-のなかでがいちばん-no-naka-de-ga-ichiban-meaning/","https://bunpro.jp/ja/grammar_points/%E3%81%AE%E3%81%AA%E3%81%8B%E3%81%A7-%E3%81%8C%E3%81%84%E3%81%A1%E3%81%B0%E3%82%93"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_009","t":"AとBとどちら～","ko":"A와 B 중 어느 쪽이 ~?","cat":"비교·정도","conn":[{"w":"명사","f":"犬 + と + ねこ + と + どちらが好きですか"},{"w":"동사(こと/の로 명사화)","f":"泳ぐの + と + 走るの + と + どちらが好きですか"},{"w":"두 번째 と 생략","f":"犬とねこ、どちらが好きですか"}],"rule":["첫 번째 선택지 명사 A에 と를 붙인다.","두 번째 선택지 명사 B에도 と를 붙인다(생략 가능).","의문사 どちら(어느 쪽)를 놓고 が + 술어 + か로 묻는다.","동사를 비교할 때는 동사 사전형에 の/こと를 붙여 명사로 만든 뒤 넣는다.","대답은 보통 'B のほうが～'로 한다."],"why":"どちら는 방향·쪽을 가리키는 こ・そ・あ・ど 계열의 말로, 두 가지 중 '어느 쪽'을 묻는다.","nu":"선택지가 꼭 둘일 때만 쓴다. 셋 이상이면 'の中で 何/どれ/だれ が一番'을 쓴다. 정중한 형태이며, 회화체는 どっち. 한국어처럼 'どれ'를 쓰면 셋 이상 중의 선택이 되어 어색하다.","cmp":[{"g":"AとBとどっち","d":"같은 뜻의 회화체."},{"g":"～の中で何が一番","d":"셋 이상 가운데 하나를 고를 때."}],"ex":[{"jp":"犬[いぬ]とねこと、どちらが好[す]きですか。","ko":"개와 고양이 중 어느 쪽을 좋아해요?"},{"jp":"電車[でんしゃ]とバスと、どちらが速[はや]いですか。","ko":"전철과 버스 중 어느 쪽이 빨라요?"},{"jp":"本[ほん]を読[よ]むのと映画[えいが]を見[み]るのと、どちらが好[す]きですか。","ko":"책 읽는 것과 영화 보는 것 중 어느 쪽을 좋아해요?"}],"dr":[{"t":"make","q":"りんご / みかん / 好きですか → AとBとどちら","a":"りんごとみかんとどちらが好きですか","hint":"A + と, B + と, どちら + が + 술어 + か."},{"t":"make","q":"泳ぐ / 走る / 好きですか → AとBとどちら","a":"泳ぐのと走るのとどちらが好きですか","hint":"동사는 の를 붙여 명사로 만든다."},{"t":"fill","q":"コーヒーと紅茶[こうちゃ]と、（　）が好[す]きですか。","a":"どちら","opts":["どちら","どれ","だれ","いつ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8-%E3%81%A8-%E3%81%A9%E3%81%A1%E3%82%89%E3%81%8C"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_010","t":"AとBとどっち～","ko":"A랑 B 중 어느 쪽? (회화체)","cat":"비교·정도","conn":[{"w":"명사","f":"肉 + と + 魚 + と + どっちがいい"},{"w":"동사(の로 명사화)","f":"行くの + と + 行かないの + と + どっちがいい"},{"w":"か 형태","f":"肉か魚か、どっちがいい"}],"rule":["선택지 A와 B에 각각 と를 붙인다(두 번째 と는 자주 생략).","의문사 どっち를 놓고 が + 술어로 묻는다.","どっち는 どちら의 회화체 형태다(どちら → どっち).","대답은 'B のほうが～' 또는 'B がいい'처럼 한다."],"why":"どっち는 どちら보다 나중에 생긴 회화적인 형태로, 뜻은 같다.","nu":"친구·가족 사이의 반말 대화에 쓴다. 윗사람이나 손님에게는 どちら를 쓴다. どちら와 마찬가지로 선택지가 둘일 때만 쓴다.","cmp":[{"g":"AとBとどちら","d":"같은 뜻의 정중형."}],"ex":[{"jp":"肉[にく]と魚[さかな]と、どっちがいい？","ko":"고기랑 생선 중 뭐가 좋아?"},{"jp":"赤[あか]いシャツと青[あお]いシャツ、どっちを買[か]う？","ko":"빨간 셔츠랑 파란 셔츠 중 어느 걸 살 거야?"},{"jp":"海[うみ]に行[い]くのと山[やま]に行[い]くのと、どっちが好[す]き？","ko":"바다 가는 거랑 산 가는 거 중 어느 쪽이 좋아?"}],"dr":[{"t":"make","q":"どちら → 회화체","a":"どっち","hint":"どちら의 회화체 형태."},{"t":"make","q":"コーヒー / 紅茶 / 好き？ → AとBとどっち","a":"コーヒーと紅茶とどっちが好き？","hint":"A + と, B + と, どっち + が + 술어."},{"t":"fill","q":"ねえ、カレーとラーメンと、（　）が食[た]べたい？","a":"どっち","opts":["どっち","どれ","どこ","なに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8-%E3%81%A8-%E3%81%A9%E3%81%A1%E3%82%89%E3%81%8C"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_012","t":"AはBより～","ko":"A는 B보다 ~","cat":"비교·정도","conn":[{"w":"명사 + い형용사","f":"夏 + は + 冬 + より + 暑い"},{"w":"명사 + な형용사","f":"この町 + は + 東京 + より + 静かです"},{"w":"명사 + 동사(부사)","f":"彼女 + は + 私 + より + 速く走ります"},{"w":"동사 비교","f":"歩く + より + 自転車のほうが速い"}],"rule":["비교의 주인공 A에 は를 붙인다.","비교 기준 B에 より(~보다)를 붙인다.","마지막에 형용사(또는 부사 + 동사)를 놓는다. 형용사는 비교급으로 바뀌지 않는다.","같은 뜻을 'BよりAのほうが～'로도 말할 수 있다."],"why":"より는 비교의 기준점을 나타내는 조사로, 일본어 형용사에는 따로 비교급 활용이 없어 より만으로 비교를 나타낸다.","nu":"회화·문장 모두 쓰는 기본 표현. より 뒤의 형용사는 원형 그대로 쓰며 따로 비교급으로 바꾸지 않는다. より가 붙는 쪽이 비교의 기준(덜한 쪽)으로, 한국어 '~보다'와 같다. 'AとBとどちらが～' 질문에는 'AのほうがBより～' 형태로 답하는 것이 자연스럽다.","cmp":[{"g":"BよりAのほうが～","d":"A를 더 강조해 말할 때. 'どちら' 질문의 대답에 주로 쓴다."},{"g":"～が一番～","d":"셋 이상 가운데 최상."}],"ex":[{"jp":"夏[なつ]は冬[ふゆ]より暑[あつ]いです。","ko":"여름은 겨울보다 더워요."},{"jp":"この町[まち]は東京[とうきょう]より静[しず]かです。","ko":"이 마을은 도쿄보다 조용해요."},{"jp":"妹[いもうと]はわたしより速[はや]く走[はし]ります。","ko":"여동생은 저보다 빨리 달려요."}],"dr":[{"t":"make","q":"夏 / 冬 / 暑い → AはBより～","a":"夏は冬より暑い","hint":"A + は, B + より, 형용사 원형."},{"t":"make","q":"電車 / バス / 速いです → AはBより～","a":"電車はバスより速いです","hint":"비교 기준 バス에 より."},{"t":"fill","q":"今日[きょう]は昨日[きのう]（　）寒[さむ]いです。","a":"より","opts":["より","から","まで","ほど"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%82%8A-%E3%81%AE%E3%81%BB%E3%81%86%E3%81%8C"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_013","t":"AよりBのほうが～","ko":"A보다 B 쪽이 (더) ~","cat":"비교·정도","conn":[{"w":"명사","f":"夏より + 冬のほうが + 寒い"},{"w":"동사 사전형","f":"歩くより + 走るほうが + 速い"},{"w":"い형용사","f":"高いより + 安いほうが + いい"},{"w":"な형용사","f":"にぎやかなより + 静かなほうが + 好きだ"}],"rule":["비교 기준이 되는 A 바로 뒤에 より(~보다)를 붙인다.","더 ~한 쪽인 B가 명사이면 の를 넣어 'B + のほうが'로 쓴다(ほう=方, 쪽).","B가 동사·い형용사이면 の 없이 그대로, な형용사이면 な를 붙여 ほうが에 잇는다.","마지막에 형용사 등 술어를 놓는다. 활용 변화는 없고 어순만 지킨다."],"why":"より는 비교의 기준을 나타내는 조사이고, ほう(方)는 '방향, 쪽'이라는 뜻의 명사라서 'B 쪽이 ~하다'라는 구조가 된다.","nu":"둘을 비교할 때 쓰는 기본 표현으로 회화·문장 모두 쓴다. 'A より'나 'B のほうが' 중 하나만 써도 된다(冬のほうが寒い / 夏より冬が寒い). 한국어 '~보다'에 끌려 명사 뒤 の를 빠뜨리기 쉬운데 '冬ほうが'는 틀리고 '冬のほうが'가 맞다. 질문은 'AとBとどちらが～ですか'로 하는 것이 일반적이다.","cmp":[{"g":"AはBほど～ない","d":"'A는 B만큼 ~하지 않다'는 부정형 비교. より～のほうが는 긍정으로 B가 더하다고 말한다."},{"g":"～が一番～","d":"셋 이상 중에서 '가장'을 말할 때 쓴다."}],"ex":[{"jp":"夏[なつ]より冬[ふゆ]のほうが好[す]きです。","ko":"여름보다 겨울을 더 좋아해요."},{"jp":"バスより電車[でんしゃ]のほうが速[はや]いです。","ko":"버스보다 전철이 더 빨라요."},{"jp":"このかばんより、あのかばんのほうが安[やす]いです。","ko":"이 가방보다 저 가방이 더 싸요."}],"dr":[{"t":"make","q":"コーヒー / お茶 / 好きです → AよりBのほうが～","a":"コーヒーよりお茶のほうが好きです","hint":"기준 A + より, 더한 쪽 B(명사) + のほうが, 마지막에 술어."},{"t":"make","q":"東京 / 大阪 / 寒い → 東京のほうが寒い (大阪と比べて)","a":"大阪より東京のほうが寒い","hint":"비교 기준인 大阪에 より를 붙이고 東京 뒤에 のほうが."},{"t":"fill","q":"肉[にく]より魚[さかな]の（　）好[す]きです。","a":"ほうが","opts":["ほうが","ほど","まで","だけ"]}],"src":["https://www.bunpro.jp/grammar_points/%E3%82%88%E3%82%8A-%E3%81%AE%E3%81%BB%E3%81%86%E3%81%8C"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_026","t":"Nくらい","ko":"~정도, 약 ~, ~쯤","cat":"비교·정도","conn":[{"w":"수량 명사","f":"20分 + くらい / 300ページ + くらい"},{"w":"의문사","f":"どの + くらい / いくら + くらい"},{"w":"こそあど","f":"これ + くらい / それ + くらい"},{"w":"명사(비교 기준)","f":"兄 + と同じ + くらい"}],"rule":["수량·시간·금액을 나타내는 명사 뒤에 くらい를 그대로 붙인다(20分くらい).","앞의 명사와 くらい 모두 형태가 바뀌지 않는다.","그 뒤에 동사(かかります, あります 등)나 です를 이어 쓴다.","くらい는 ぐらい로 바꿔 말해도 뜻이 같다."],"why":"","nu":"회화체 중심의 기본 표현. 정확한 수가 아니라 대략적인 양임을 나타내며, 앞의 수는 보통 딱 떨어지는 수(10분, 1000엔)다. 시각(3時)의 '쯤'에도 쓰이지만 시각에는 ごろ가 더 일반적이다. 今日・今週 같은 말에는 붙이지 않는다.","cmp":[{"g":"～ごろ","d":"ごろ는 시각·날짜 같은 '시점'의 무렵에만 쓴다. 기간·양(20分, 300ページ)에는 くらい."}],"ex":[{"jp":"駅[えき]まで歩[ある]いて20分[にじゅっぷん]くらいかかります。","ko":"역까지 걸어서 20분 정도 걸려요."},{"jp":"この本[ほん]は300[さんびゃく]ページくらいあります。","ko":"이 책은 300페이지쯤 돼요."},{"jp":"東京[とうきょう]までどのくらいですか。","ko":"도쿄까지 얼마나 걸려요?"}],"dr":[{"t":"make","q":"1時間 / かかります → ～くらい","a":"1時間くらいかかります","hint":"수량 명사 뒤에 くらい를 그대로 붙이고 동사를 잇는다."},{"t":"make","q":"千円 / です → ～くらい","a":"千円くらいです","hint":"금액 + くらい + です."},{"t":"fill","q":"毎日[まいにち]、2時間[にじかん]（　）日本語[にほんご]を勉強[べんきょう]します。","a":"くらい","opts":["くらい","ごろ","から","より"]}],"src":["https://tofugu.com/japanese-grammar/kurai","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_6.pdf"],"vf":1,"u":9,"g":1,"gp":"gg_N5_06"},{"id":"g5_027","t":"Nぐらい","ko":"~정도, 약 ~, ~쯤","cat":"비교·정도","conn":[{"w":"수량 명사","f":"5個 + ぐらい / 8時間 + ぐらい"},{"w":"금액","f":"3000円 + ぐらい"},{"w":"의문사","f":"何時間 + ぐらい / いくら + ぐらい"},{"w":"こそあど","f":"これ + ぐらい"}],"rule":["수량·시간·금액 명사 뒤에 ぐらい를 그대로 붙인다(5個ぐらい).","ぐらい는 くらい의 く가 탁음 ぐ로 된 형태로, 뜻과 쓰임은 くらい와 같다.","명사 형태는 바뀌지 않고, 뒤에 동사나 です를 잇는다."],"why":"くらい와 같은 문법 항목이며, ぐらい는 그 탁음 형태다. 둘 사이에 뜻 차이는 없다.","nu":"회화에서 자주 쓰는 형태. くらい와 자유롭게 바꿔 쓸 수 있다. 정확한 수가 아니라 대략임을 나타내며, 앞에는 보통 딱 떨어지는 수가 온다. 시각의 '쯤'에는 ごろ가 더 자연스럽고, 今日・今年 같은 말에는 붙이지 않는다.","cmp":[{"g":"～くらい","d":"같은 뜻. 표기·발음만 다르다."},{"g":"～ごろ","d":"ごろ는 시점(3時, 3月)의 무렵, ぐらい는 양·기간(3時間)의 대략."}],"ex":[{"jp":"りんごを5個[ごこ]ぐらい食[た]べました。","ko":"사과를 5개쯤 먹었어요."},{"jp":"昨日[きのう]は8時間[はちじかん]ぐらい寝[ね]ました。","ko":"어제는 8시간 정도 잤어요."},{"jp":"このかばんはいくらぐらいですか。","ko":"이 가방은 얼마 정도예요?"}],"dr":[{"t":"make","q":"30分 / 待ちました → ～ぐらい","a":"30分ぐらい待ちました","hint":"시간 명사 뒤에 ぐらい를 붙이고 동사를 잇는다."},{"t":"make","q":"何人 / 来ますか → ～ぐらい","a":"何人ぐらい来ますか","hint":"의문사 수량 + ぐらい로 대략의 수를 묻는다."},{"t":"fill","q":"学校[がっこう]まで自転車[じてんしゃ]で15分[じゅうごふん]（　）かかります。","a":"ぐらい","opts":["ぐらい","ごろ","だけに","までに"]}],"src":["https://tofugu.com/japanese-grammar/kurai","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei04_6.pdf"],"vf":1,"u":10,"g":1,"gp":"gg_N5_06"},{"id":"g5_110","t":"どちら","ko":"(둘 중) 어느 쪽, 어디, 어느 분","cat":"비교·정도","conn":[{"w":"どちら + が (주어)","f":"どちらが好きですか"},{"w":"どちら + を / に (목적어·방향)","f":"どちらにしますか"},{"w":"どちら + の + 명사","f":"どちらのかばんですか"},{"w":"AとBと、どちら(のほう)が","f":"犬とねこと、どちらが好きですか"}],"rule":["두 가지 중 하나를 물을 때 どちら를 쓰고 뒤에 필요한 조사(が・を・に)를 붙인다.","비교 대상은 AとBと로 앞에 둔다(犬とねこと、どちらが好きですか).","대답은 どちら 자리에 고른 쪽을 넣고 のほう를 붙인다(どちらが → ねこのほうが).","둘 다면 どちらも, 아무거나 좋으면 どちらでもいいです로 답한다."],"why":"사전은 どちら(何方)에 방향·장소, 여럿 중 어느 쪽, 사람을 정중히 가리키는 뜻을 모두 싣고 있다. どち는 방향을 뜻하던 옛말 いづち가 변한 형태이고, 여기에 촉음이 들어간 회화체가 どっち이다.","nu":"どちら는 정중, どっち는 친구끼리의 회화체. 선택지가 셋 이상이면 どれ를 쓴다. 장소를 정중하게 물을 때도 쓴다(お国はどちらですか, どちらへ行きますか). 한국어 '어느 것'에 이끌려 둘 중 고를 때 どれ를 쓰는 실수가 많다.","cmp":[{"g":"どれ","d":"どれ는 셋 이상 중에서 '어느 것'. どちら는 두 가지 중에서 '어느 쪽'."},{"g":"どっち","d":"뜻은 같고 회화체. 윗사람·손님에게는 どちら를 쓴다."}],"ex":[{"jp":"コーヒーと紅茶[こうちゃ]と、どちらがいいですか。","ko":"커피와 홍차 중에 어느 쪽이 좋아요?"},{"jp":"A：どちらが高[たか]いですか。B：こちらのほうが高[たか]いです。","ko":"A: 어느 쪽이 비싸요? B: 이쪽이 더 비쌉니다."},{"jp":"すみません、駅[えき]はどちらですか。","ko":"실례합니다, 역은 어느 쪽입니까?"}],"dr":[{"t":"make","q":"どちらが好きですか → '고양이 쪽을 좋아해요'로 대답","a":"ねこのほうが好きです","hint":"どちら 자리에 고른 쪽 + のほう."},{"t":"make","q":"どっちがいい？ → 정중하게","a":"どちらがいいですか","hint":"どっち를 どちら로, 문말은 ですか."},{"t":"fill","q":"肉[にく]と魚[さかな]と、（　）が好[す]きですか。","a":"どちら","opts":["どちら","どれ","どこ","だれ"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei15_6.pdf","https://kotobank.jp/word/何方"],"vf":1,"u":10,"g":1,"gp":"gg_N5_06"},{"id":"g5_134","t":"もっと～","ko":"더, 더욱, 좀 더","cat":"비교·정도","conn":[{"w":"もっと + 동사","f":"もっと食べたい"},{"w":"もっと + い형용사","f":"もっと大きいかばん"},{"w":"もっと + な형용사","f":"もっと静かな所"},{"w":"もっと + 부사/부사형","f":"もっとゆっくり話してください"}],"rule":["もっと는 활용하지 않는 부사이므로 글자가 바뀌지 않는다.","꾸밀 말(食べたい, 大きい, 静かな …) 바로 앞에 もっと를 둔다.","형용사는 원래 활용형 그대로 쓴다(もっと大きい, もっと静かな所, もっと早く)."],"why":"","nu":"회화·문장 모두 쓴다. 지금 상태보다 정도를 더 높이는 말이라 바람(~たい), 부탁(~てください), 비교 문장과 잘 어울린다. 한국어 '더'처럼 수량에도 쓰지만 명사를 직접 꾸미지는 않으므로 'もっとご飯' 대신 'ご飯をもっとください'처럼 동사 앞에 둔다. 격식 있는 글에서는 さらに・より를 쓰기도 한다.","cmp":[{"g":"もう少し","d":"'조금 더'. 더하는 양이 적다는 느낌. もっと는 양을 정하지 않고 '더'."},{"g":"いちばん","d":"'가장'(최상급). もっと는 지금보다 정도가 높아지는 비교."}],"ex":[{"jp":"もっと食[た]べたいです。","ko":"더 먹고 싶어요."},{"jp":"もっと大[おお]きい靴[くつ]はありますか。","ko":"더 큰 신발 있어요?"},{"jp":"もっとゆっくり話[はな]してください。","ko":"좀 더 천천히 말해 주세요."}],"dr":[{"t":"make","q":"勉強します → '더 공부해요'","a":"もっと勉強します","hint":"동사 앞에 もっと를 둔다."},{"t":"make","q":"静かな部屋 → '더 조용한 방'","a":"もっと静かな部屋","hint":"な형용사는 な를 그대로 두고 앞에 もっと."},{"t":"fill","q":"この靴[くつ]は小[ちい]さいです。（　）大[おお]きいのはありますか。","a":"もっと","opts":["もっと","もう","よく","ときどき"]}],"src":["https://www.weblio.jp/content/もっと"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_029","t":"Nだけ","ko":"~만, ~뿐","cat":"강조·한정","conn":[{"w":"명사","f":"コーヒー + だけ"},{"w":"동사 사전형","f":"見る + だけ"},{"w":"い형용사","f":"安い + だけ"},{"w":"な형용사","f":"きれいな + だけ"}],"rule":["명사 뒤에 だけ를 그대로 붙인다(コーヒーだけ).","동사·い형용사는 사전형(보통형)에, な형용사는 な를 붙인 형태에 だけ를 잇는다(きれいなだけ).","だけ 자체는 형태가 바뀌지 않으며, 뒤에 긍정문·부정문 모두 올 수 있다."],"why":"여러 가능성 가운데 그것 하나에만 해당함을 나타내는 조사다.","nu":"회화·문장 모두 쓰는 기본 표현. 명사 + を/が + 동사일 때 を・が는 だけ로 대신하는 일이 많다(コーヒーだけ飲んだ). 한국어 '~밖에 없다'의 뜻으로 강하게 제한할 때는 しか～ない를 쓰며, しか 뒤에는 반드시 부정형이 와야 한다.","cmp":[{"g":"～しか～ない","d":"しか는 반드시 부정형과 함께 쓰고 '그것밖에 없다'는 부족함을 더 강하게 나타낸다. だけ는 중립적으로 '그것만'."}],"ex":[{"jp":"朝[あさ]はコーヒーだけ飲[の]みました。","ko":"아침은 커피만 마셨어요."},{"jp":"今日[きょう]は見[み]るだけです。","ko":"오늘은 보기만 할게요."},{"jp":"クラスで日本人[にほんじん]は田中[たなか]さんだけです。","ko":"반에서 일본인은 다나카 씨뿐이에요."}],"dr":[{"t":"make","q":"水を飲みました → 水 + だけ","a":"水だけ飲みました","hint":"명사 뒤에 だけ를 붙이고 を는 생략한다."},{"t":"make","q":"見ます(사전형) / です → ～だけ","a":"見るだけです","hint":"동사는 사전형 見る에 だけ를 잇는다."},{"t":"fill","q":"財布[さいふ]に百円[ひゃくえん]（　）あります。","a":"だけ","opts":["だけ","しか","ごろ","まで"]}],"src":["https://bunpro.jp/grammar_points/だけ"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_092","t":"だれでも","ko":"누구든지, 누구라도","cat":"강조·한정","conn":[{"w":"だれでも + 가능 동사","f":"だれでもできます"},{"w":"だれでも + 형용사·명사문","f":"だれでも大丈夫です"},{"w":"だれでも + 동사(일반)","f":"だれでも知っています"}],"rule":["의문사 だれ 바로 뒤에 でも를 붙인다(だれ → だれでも).","뒤에는 긍정문이 와서 '누구든 예외 없이 그렇다'는 뜻이 된다(だれでもできます).","が・を 같은 조사는 붙이지 않는다(×だれがでも).","같은 방식으로 なんでも(무엇이든), どこでも(어디든), いつでも(언제든)를 만든다."],"why":"でも는 예시·전면 긍정을 나타내는 조사로, 의문사 뒤에 붙으면 '어느 것을 넣어도 다 해당된다'는 뜻이 된다. で+も가 합쳐진 것으로 보는 견해도 있지만 하나의 조사로 보는 견해도 있다.","nu":"회화·문장 모두 쓴다. 뒤에 긍정문이 오는 것이 기본이다. 부정문으로 '아무도 ~않다'라고 할 때는 だれでも가 아니라 だれも를 쓴다. 한국어 '누구나'와 거의 같아 だれでも + 가능형(できる, 参加できる) 조합이 자주 나온다.","cmp":[{"g":"だれも","d":"だれも는 주로 부정문에서 '아무도 ~않다'. だれでも는 긍정문에서 '누구든지 ~한다'."},{"g":"だれか","d":"だれか는 정해지지 않은 '한 사람(누군가)'. だれでも는 '모든 사람 누구든'."}],"ex":[{"jp":"このゲームはだれでもできます。","ko":"이 게임은 누구든지 할 수 있습니다."},{"jp":"このパーティーにはだれでも来[き]ていいですよ。","ko":"이 파티에는 누구든지 와도 돼요."},{"jp":"だれでも間違[まちが]えることがあります。","ko":"누구나 틀릴 때가 있습니다."}],"dr":[{"t":"make","q":"だれ → '누구든지'","a":"だれでも","hint":"だれ 뒤에 でも를 붙인다."},{"t":"make","q":"子どもも大人も使えます → だれでも로 바꾸기","a":"だれでも使えます","hint":"'누구든'을 だれでも 한 마디로 묶고 긍정문을 그대로 쓴다."},{"t":"fill","q":"この本[ほん]はやさしいので、（　）読[よ]めます。","a":"だれでも","opts":["だれでも","だれも","だれか","だれが"]}],"src":["https://bunpro.jp/ja/grammar_points/88","https://bunpro.jp/ja/grammar_points/714"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_093","t":"だれも～ないです","ko":"아무도 ~않습니다","cat":"강조·한정","conn":[{"w":"1그룹 동사","f":"知る → 知らない + です → だれも知らないです"},{"w":"2그룹 동사","f":"食べる → 食べない + です"},{"w":"불규칙 동사","f":"来る → 来(こ)ない / する → しない"},{"w":"ある/いる","f":"いる → いない (だれもいないです)"}],"rule":["문장 앞쪽에 だれも를 놓는다. 이 자리의 が・を는 쓰지 않는다(だれもが가 아니라 だれも).","동사를 ない형으로 바꾼다. 1그룹은 어미 う단을 あ단으로 바꾸고 ない(知る → 知らない), 2그룹은 る를 떼고 ない.","来る는 불규칙으로 くる → こない, する는 しない가 된다.","끝에 です를 붙여 정중하게 만든다(来ないです)."],"why":"だれ(누구)에 '~도'의 も가 붙어, 부정문과 함께 '누구도(어느 사람도) ~않다'라는 전부 부정을 만든다.","nu":"ないです는 ません보다 조금 부드럽고 회화적인 정중체(だれも来ません과 같은 뜻). 문장 끝은 반드시 부정이어야 한다(×だれも来ます). 동작의 대상에 붙을 때는 조사를 앞에 둔다(だれにも言わない, だれとも話さない). 한국인 실수: だれもが来ない처럼 が를 붙이는 것.","cmp":[{"g":"だれも～ません","d":"의미는 같다. ません이 더 격식 있고 교과서적이며, ないです는 회화에서 많이 쓴다."},{"g":"だれでも","d":"だれでも는 긍정문으로 '누구든지 ~한다'. だれも～ない는 '아무도 ~않다'."}],"ex":[{"jp":"パーティーにだれも来[こ]ないです。","ko":"파티에 아무도 오지 않아요."},{"jp":"この話[はなし]はだれも知[し]らないです。","ko":"이 이야기는 아무도 몰라요."},{"jp":"教室[きょうしつ]にはだれもいないです。","ko":"교실에는 아무도 없어요."}],"dr":[{"t":"make","q":"だれも + 来る → ～ないです","a":"だれも来ないです","hint":"来る는 불규칙: くる → こない, 끝에 です."},{"t":"make","q":"だれも + 書く → ～ないです","a":"だれも書かないです","hint":"1그룹은 く(う단)를 か(あ단)로 바꾸고 ない."},{"t":"fill","q":"日曜日[にちようび]なので、学校[がっこう]には（　）いないです。","a":"だれも","opts":["だれも","だれか","だれでも","だれが"]}],"src":["https://bunpro.jp/ja/grammar_points/714","https://bunpro.jp/ja/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_094","t":"だれも～ません","ko":"아무도 ~않습니다","cat":"강조·한정","conn":[{"w":"1그룹 동사","f":"知る → 知ります → 知りません"},{"w":"2그룹 동사","f":"食べる → 食べます → 食べません"},{"w":"불규칙 동사","f":"来る → 来ません / する → しません"},{"w":"과거","f":"答えません → 答えませんでした"}],"rule":["문장 앞쪽에 だれも를 놓는다(조사 が・を는 쓰지 않는다).","동사를 ます형으로 바꾼다. 1그룹은 어미 う단을 い단으로(知る → 知り), 2그룹은 る를 뗀다.","ます를 ません으로 바꾼다(知ります → 知りません).","과거는 ませんでした를 쓴다(だれも答えませんでした)."],"why":"だれ + も가 부정 표현과 짝을 이루어 '어느 누구도 ~않다'라는 전부 부정을 나타낸다. ません은 ます의 부정형이다.","nu":"정중체 기본형으로 시험·교과서에서 가장 많이 나온다. 동사 끝이 반드시 부정이어야 한다. 사람에게 무엇을 할 때는 조사를 앞에 넣는다(だれにも会いません, だれとも話しません). 한국어로 '아무도'라고 생각해 だれもが를 쓰면 '누구나 다'라는 긍정 의미가 되어 버리므로 주의.","cmp":[{"g":"だれも～ないです","d":"뜻은 같다. ないです는 회화적이고 조금 부드러우며, ません이 더 격식 있다."},{"g":"だれか","d":"だれか는 '누군가'로 긍정·질문문에 쓴다. 부정문에서 '아무도'는 だれも."}],"ex":[{"jp":"だれもその答[こた]えを知[し]りません。","ko":"아무도 그 답을 모릅니다."},{"jp":"昨日[きのう]はだれも来[き]ませんでした。","ko":"어제는 아무도 오지 않았습니다."},{"jp":"このことはだれにも言[い]いません。","ko":"이 일은 아무에게도 말하지 않겠습니다."}],"dr":[{"t":"make","q":"だれも + 飲む → ～ません","a":"だれも飲みません","hint":"む(う단)를 み(い단)로 바꿔 ます형, ます를 ません으로."},{"t":"make","q":"だれも + 答える → ～ませんでした","a":"だれも答えませんでした","hint":"2그룹은 る를 떼고 ませんでした."},{"t":"fill","q":"部屋[へや]には（　）いません。","a":"だれも","opts":["だれも","だれか","だれでも","どなたか"]}],"src":["https://bunpro.jp/ja/grammar_points/714","https://bunpro.jp/ja/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_103","t":"どこでも","ko":"어디서든, 어디든지","cat":"강조·한정","conn":[{"w":"どこでも + 가능 동사","f":"どこでも寝[ね]られます"},{"w":"どこでも + いい (허용)","f":"どこでもいいです"},{"w":"どこでも + 일반 동사","f":"どこでも売[う]っています"},{"w":"どこでも + 명사 + です","f":"どこでも同[おな]じです"}],"rule":["의문사 どこ 뒤에 でも를 붙여 どこでも를 만든다(どこ → どこでも).","どこでも는 '어느 장소라도 예외 없이'라는 뜻이 되어 뒤에 긍정 술어가 온다.","그 뒤에 가능 동사·いい 같은 술어를 놓는다(どこでも寝られます).","どこでも 자체는 활용하지 않는다."],"why":"의문사에 でも가 붙으면 '어떤 ~라도'라는 뜻이 된다(だれでも, なんでも, いつでも와 같은 방식). でも는 で + も로 보는 설명도 있다.","nu":"회화·문장 모두 쓴다. 긍정문에 쓰며 '어디든 OK'라는 느낌이다. 부정 '아무 데도 ~않다'는 どこにも／どこへも + 부정형을 써야 하며 どこでも～ない는 '어디서나 ~할 수 있는 것은 아니다' 쪽으로 뜻이 달라진다. どこでもいい는 '아무 데나 좋다'(상관없음)이다.","cmp":[{"g":"どこか","d":"どこか는 정해지지 않은 '어딘가 한 곳', どこでも는 '어느 곳이든 전부'."},{"g":"どこにも～ない","d":"부정문 '어디에도 ~없다'. どこでも는 긍정문용."}],"ex":[{"jp":"弟[おとうと]はどこでも寝[ね]られます。","ko":"남동생은 어디서든 잘 수 있습니다."},{"jp":"このパンはどこでも売[う]っています。","ko":"이 빵은 어디서든 팔고 있습니다."},{"jp":"A：どこで食[た]べますか。 B：どこでもいいですよ。","ko":"A: 어디서 먹을까요? B: 아무 데나 좋아요."}],"dr":[{"t":"make","q":"どこ → '어디서든'","a":"どこでも","hint":"의문사 + でも"},{"t":"make","q":"いいです → '아무 데나 좋아요'","a":"どこでもいいです","hint":"술어 앞에 どこでも"},{"t":"fill","q":"このカードは（　）使[つか]えます。とても便利[べんり]です。","a":"どこでも","opts":["どこでも","どこにも","どこか","どこへも"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A7%E3%82%82","https://www.vnjpclub.com/en/n5-grammar/dokodemo.html"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_104","t":"どこにも～ないです","ko":"어디에도 ~없어요 / 아무 데도 ~않아요","cat":"강조·한정","conn":[{"w":"どこにも + ない(ある의 부정) + です","f":"どこにもないです"},{"w":"どこにも + いない(いる의 부정) + です","f":"どこにもいないです"},{"w":"どこにも + 1그룹 동사 ない형 + です","f":"どこにも行[い]かないです"},{"w":"どこにも + ~ていない + です","f":"どこにも売[う]っていないです"}],"rule":["의문사 どこ 뒤에 장소의 조사 に를 먼저 붙인다(どこに).","그 뒤에 も를 붙인다: どこ + に + も. 순서를 どこもに로 바꾸지 않는다.","동사는 ない형으로 바꾼다. ある는 예외로 ない가 된다(ある → ない), 1그룹은 어미 う단 → あ단 + ない(行く → 行かない).","정중하게 하려면 ない 뒤에 です를 붙인다(ないです)."],"why":"의문사 + 조사 + も가 부정과 함께 쓰여 '어느 곳에도 ~하지 않다'는 전면 부정이 된다. に는 존재·도착 장소를 나타내는 조사 그대로다.","nu":"ないです는 회화에서 쓰는 부드러운 정중형이고, 같은 뜻의 ません(ありません・行きません)이 더 격식 있는 말이다. どこにも는 반드시 부정 술어와 함께 쓴다(どこにもあります는 틀림). 한국어 '어디에도'를 그대로 옮겨 どこもに라고 하는 실수에 주의한다. 장소에 있는지 없는지(ある・いる)는 に를 쓰는 どこにも가 기본이다.","cmp":[{"g":"どこへも～ない","d":"へ는 이동 방향이라 行く・来る 같은 이동 동사에만 쓴다. どこにも는 이동과 존재(ある・いる) 모두 쓴다."},{"g":"どこも～ない","d":"どこも는 장소 자체가 주어(어느 가게도 ~않다)일 때. '어디에 있다/없다'는 どこにも."}],"ex":[{"jp":"かぎがどこにもないです。","ko":"열쇠가 어디에도 없어요."},{"jp":"週末[しゅうまつ]はどこにも行[い]かないです。","ko":"주말에는 아무 데도 안 가요."},{"jp":"その本[ほん]はどこにも売[う]っていないです。","ko":"그 책은 어디에도 팔고 있지 않아요."}],"dr":[{"t":"make","q":"どこに + あります → '어디에도 없어요' (ないです)","a":"どこにもないです","hint":"に 뒤에 も, ある는 ない로"},{"t":"make","q":"どこにも + いる → ないです 형","a":"どこにもいないです","hint":"2그룹 いる: る를 빼고 ない"},{"t":"fill","q":"めがねを探[さが]しましたが、（　）ないです。","a":"どこにも","opts":["どこにも","どこでも","どこか","どこへ"]}],"src":["https://jplang.tufs.ac.jp/en/bu/9/9-8.html","https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/doko-kani-doko-nimo-genki-i-chapter-10/","https://elon.io/grammar/japanese/questions/mo-negatives"],"vf":1,"u":10,"g":1,"gp":"gg_N5_07"},{"id":"g5_105","t":"どこにも～ません","ko":"어디에도 ~없습니다 / 아무 데도 ~않습니다","cat":"강조·한정","conn":[{"w":"どこにも + ありません","f":"どこにもありません"},{"w":"どこにも + いません","f":"どこにもいません"},{"w":"どこにも + 동사 ません","f":"どこにも行[い]きません"},{"w":"과거: ませんでした","f":"どこにもいませんでした"}],"rule":["의문사 どこ 뒤에 장소의 조사 に를 붙이고, 그 뒤에 も를 붙인다(どこ + に + も).","동사는 ます형의 ます를 ません으로 바꾼다(います → いません, あります → ありません).","과거라면 ません 뒤에 でした를 붙인다(いませんでした).","긍정형 ます와는 함께 쓸 수 없다."],"why":"의문사 + 조사 + も가 부정과 결합하면 '어느 ~에도 ~않다'는 전면 부정이 된다. ません은 정중형 ます의 부정이다.","nu":"정중체로 수업·업무 등 어디서나 쓴다. ないです보다 격식 있다. 질문 どこかにありますか에 대한 부정 대답으로 자주 쓴다(いいえ、どこにもありません). 한국인은 '아무 데도 없어요'를 どこもありません으로 줄이기 쉬운데, 장소에 있는지 없는지는 に를 넣은 どこにも가 기본이다.","cmp":[{"g":"どこにも～ないです","d":"뜻은 같고 말투만 다르다. ません이 더 격식, ないです는 회화에서 부드러운 정중형."}],"ex":[{"jp":"猫[ねこ]がどこにもいません。","ko":"고양이가 어디에도 없습니다."},{"jp":"A：どこかに間違[まちが]いがありますか。 B：いいえ、どこにもありません。","ko":"A: 어딘가 틀린 곳이 있습니까? B: 아니요, 어디에도 없습니다."},{"jp":"昨日[きのう]はどこにも行[い]きませんでした。","ko":"어제는 아무 데도 가지 않았습니다."}],"dr":[{"t":"make","q":"どこにも + います → 부정","a":"どこにもいません","hint":"ます → ません"},{"t":"make","q":"どこにもありません → 과거","a":"どこにもありませんでした","hint":"ません 뒤에 でした"},{"t":"fill","q":"子[こ]どもを探[さが]しましたが、どこにも（　）。","a":"いませんでした","opts":["いませんでした","いました","います","いましょう"]}],"src":["https://jplang.tufs.ac.jp/en/bu/9/9-8.html","https://bunpro.jp/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82","https://elon.io/grammar/japanese/questions/mo-negatives"],"vf":1,"u":11,"g":1,"gp":"gg_N5_07"},{"id":"g5_106","t":"どこへも～ないです","ko":"아무 데도 (가지) 않아요","cat":"강조·한정","conn":[{"w":"どこへも + 行かない + です","f":"どこへも行[い]かないです"},{"w":"どこへも + 出かけない + です (2그룹)","f":"どこへも出[で]かけないです"},{"w":"どこへも + 来ない + です (불규칙 来る)","f":"どこへも来[こ]ないです"},{"w":"과거: なかったです","f":"どこへも行[い]かなかったです"}],"rule":["의문사 どこ 뒤에 방향의 조사 へ를 붙이고, 그 뒤에 も를 붙인다(どこ + へ + も).","이동 동사를 ない형으로 바꾼다. 1그룹은 う단 → あ단 + ない(行く → 行かない), 2그룹은 る를 빼고 ない(出かける → 出かけない).","정중하게 하려면 ない 뒤에 です를 붙인다. 과거는 なかったです.","へ는 '~쪽으로'라는 방향이므로 이동 동사(行く・来る・帰る・出かける)와만 쓴다."],"why":"방향 조사 へ에 も가 붙고 부정과 결합해 '어느 쪽으로도 가지 않는다'는 전면 부정이 된다.","nu":"ないです는 회화에서 쓰는 부드러운 정중형이고, 같은 뜻의 ません(ありません・行きません)이 더 격식 있는 말이다. 이동이 아닌 동사(売る・食べる 등)에 どこへも를 쓰는 것은 틀린다. 일상 회화에서는 같은 뜻으로 どこにも行かない도 많이 쓴다.","cmp":[{"g":"どこにも～ない","d":"どこにも는 존재(ある・いる)와 이동 모두에 쓰고, どこへも는 이동 동사에만 쓴다."}],"ex":[{"jp":"今週末[こんしゅうまつ]はどこへも行[い]かないです。","ko":"이번 주말은 아무 데도 안 가요."},{"jp":"雨[あめ]なので、今日[きょう]はどこへも出[で]かけないです。","ko":"비가 와서 오늘은 아무 데도 안 나가요."},{"jp":"夏休[なつやす]みはどこへも行[い]かなかったです。","ko":"여름방학에는 아무 데도 안 갔어요."}],"dr":[{"t":"make","q":"どこへも + 行く → ないです 형","a":"どこへも行かないです","hint":"行く: く → か + ない, 뒤에 です"},{"t":"make","q":"どこへも + 帰る → ないです 형","a":"どこへも帰らないです","hint":"帰る는 1그룹: る → ら + ない"},{"t":"fill","q":"日曜日[にちようび]は家[いえ]にいて、どこへも（　）。","a":"行かないです","opts":["行かないです","行きたいです","食べないです","あります"]}],"src":["https://jplang.tufs.ac.jp/en/bu/9/9-8.html","https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/doko-kani-doko-nimo-genki-i-chapter-10/","https://bunpro.jp/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_07"},{"id":"g5_107","t":"どこへも～ません","ko":"아무 데도 (가지) 않습니다","cat":"강조·한정","conn":[{"w":"どこへも + 行きません","f":"どこへも行[い]きません"},{"w":"どこへも + 出かけません","f":"どこへも出[で]かけません"},{"w":"과거: ませんでした","f":"どこへも行[い]きませんでした"},{"w":"どこへも + ~に行きません (목적)","f":"どこへも買[か]い物[もの]に行[い]きません"}],"rule":["의문사 どこ 뒤에 방향의 조사 へ, 그 뒤에 も를 붙인다(どこ + へ + も).","이동 동사의 ます를 ません으로 바꾼다(行きます → 行きません).","과거는 ません 뒤에 でした(行きませんでした).","へ는 방향을 나타내므로 이동 동사에만 쓴다."],"why":"방향 조사 へ + も + 정중 부정 ません. 의문사 + 조사 + も가 부정과 함께 쓰여 전면 부정이 된다.","nu":"정중체로 어디서나 쓴다. ないです보다 격식 있다. 질문 どこかへ行きましたか에 대한 부정 대답으로 자주 쓴다(いいえ、どこへも行きませんでした). 走る·売る처럼 방향이 아닌 동사에는 쓰지 않는다. 조사 순서를 どこもへ로 바꾸지 않는다.","cmp":[{"g":"どこへも～ないです","d":"뜻은 같고, ません이 더 격식 있는 정중형이다."}],"ex":[{"jp":"今日[きょう]はどこへも行[い]きません。","ko":"오늘은 아무 데도 가지 않습니다."},{"jp":"A：昨日[きのう]、どこかへ行[い]きましたか。 B：いいえ、どこへも行[い]きませんでした。","ko":"A: 어제 어딘가 갔습니까? B: 아니요, 아무 데도 가지 않았습니다."},{"jp":"雨[あめ]の日[ひ]はどこへも出[で]かけません。","ko":"비 오는 날에는 아무 데도 나가지 않습니다."}],"dr":[{"t":"make","q":"どこへも + 行きます → 부정","a":"どこへも行きません","hint":"ます → ません"},{"t":"make","q":"どこへも出かけません → 과거","a":"どこへも出かけませんでした","hint":"ません 뒤에 でした"},{"t":"fill","q":"A：週末[しゅうまつ]、どこかへ行[い]きましたか。 B：いいえ、（　）行[い]きませんでした。","a":"どこへも","opts":["どこへも","どこかへ","どこでも","どこへ"]}],"src":["https://jplang.tufs.ac.jp/en/bu/9/9-8.html","https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/doko-kani-doko-nimo-genki-i-chapter-10/","https://bunpro.jp/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_07"},{"id":"g5_108","t":"どこも～ないです","ko":"어디도 ~않아요 (모든 곳이 ~아님)","cat":"강조·한정","conn":[{"w":"どこも + 동사 ない형 + です","f":"どこも開[あ]いていないです"},{"w":"どこも + い형용사 く + ないです","f":"どこも痛[いた]くないです"},{"w":"どこも + 명사 じゃないです","f":"どこも休[やす]みじゃないです"},{"w":"(참고) 긍정이면 '어디나 다'","f":"どこも人[ひと]がいっぱいです"}],"rule":["どこ가 주어일 때 주격 조사 が를 빼고 그 자리에 も를 붙인다(どこが → どこも). どこがも라고 하지 않는다.","술어를 부정형으로 바꾼다. 동사는 ない형, い형용사는 い → く + ない(痛い → 痛くない), 명사는 じゃない.","정중하게 하려면 끝에 です를 붙인다(開いていないです).","부정이면 '모든 곳이 ~아니다', 긍정이면 '어디나 다 ~하다'라는 뜻이 된다."],"why":"의문사 + も에서 が・を는 も에 흡수되어 사라진다(だれも, なにも와 같은 규칙). どこ는 장소어라서 긍정 술어와 쓰면 '어디나'라는 뜻도 된다.","nu":"ないです는 회화에서 쓰는 부드러운 정중형이고, 같은 뜻의 ません(ありません・行きません)이 더 격식 있는 말이다. どこも는 장소 자체가 주어(가게가 어디도 안 열었다, 어디도 안 아프다)일 때 쓴다. '물건이 어디에도 없다'처럼 장소에 존재하는지 묻는 말은 に를 넣어 どこにもないです라고 하는 것이 기본이다(どこも鍵がない보다 どこにも鍵がない). 회화에서는 に가 생략된 どこも도 들리지만 학습자는 구별해 쓰는 편이 안전하다.","cmp":[{"g":"どこにも～ない","d":"どこにも는 '어느 장소에도 (무엇이) 없다'(장소 = に), どこも는 '어느 장소도 ~아니다'(장소 = 주어)."}],"ex":[{"jp":"お正月[しょうがつ]なので、お店[みせ]はどこも開[あ]いていないです。","ko":"설날이라 가게는 어디도 열려 있지 않아요."},{"jp":"A：どこか痛[いた]いですか。 B：いいえ、どこも痛[いた]くないです。","ko":"A: 어디 아파요? B: 아니요, 아무 데도 안 아파요."},{"jp":"この辺[へん]のレストランはどこも高[たか]くないです。","ko":"이 근처 레스토랑은 어디도 비싸지 않아요."}],"dr":[{"t":"make","q":"どこが + 痛い → '아무 데도 안 아파요' (ないです)","a":"どこも痛くないです","hint":"が를 빼고 も, い → く + ない + です"},{"t":"make","q":"店はどこが + 開いている → ないです 형","a":"店はどこも開いていないです","hint":"が → も, いる → いない + です"},{"t":"fill","q":"日曜日[にちようび]の朝[あさ]は、店[みせ]は（　）開[あ]いていないです。","a":"どこも","opts":["どこも","どこか","どこでも","どこへも"]}],"src":["https://elon.io/grammar/japanese/questions/mo-negatives","https://bunpro.jp/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82","https://jplang.tufs.ac.jp/en/bu/9/9-8.html"],"vf":1,"u":11,"g":1,"gp":"gg_N5_07"},{"id":"g5_113","t":"どれでも","ko":"어느 것이든, 어느 것이라도","cat":"강조·한정","conn":[{"w":"どれでも + いいです","f":"どれでもいいです"},{"w":"どれでも + 동사 긍정","f":"どれでも使えます"},{"w":"どれでも + い형용사","f":"どれでもおいしいです"},{"w":"どれ + 조사 + でも","f":"どれにでも合います"}],"rule":["의문사 どれ 뒤에 でも를 붙인다(どれ → どれでも).","뒤에는 긍정 술어를 쓴다(いいです, 使えます).","が・を는 쓰지 않고, に 같은 조사는 どれ와 でも 사이에 넣는다(どれにでも).","'셋 이상 중 어느 것을 골라도 다 해당된다'는 뜻이 된다."],"why":"의문사 + でも는 대상을 제한하지 않음을 나타내는 형태로, なんでも, だれでも, いつでも, どこでも와 같은 구조다.","nu":"회화에서 많이 쓴다. どれでもいいです는 '아무거나 괜찮다'는 허락이지만 말투에 따라 무관심하게 들릴 수 있다. 부정문에는 쓰지 않으며, '어느 것도 ~않다'는 どれも + 부정이다. 둘 중이면 どちらでも를 쓴다.","cmp":[{"g":"どれも","d":"どれも는 '어느 것도/모두'(どれもおいしい, どれも好きじゃない). どれでも는 '어느 것을 골라도 상관없음'."},{"g":"どちらでも","d":"두 가지 중 어느 쪽이든. どれでも는 셋 이상."}],"ex":[{"jp":"どれでも好[す]きなのを取[と]ってください。","ko":"어느 것이든 좋아하는 걸 가져가세요."},{"jp":"この店[みせ]のケーキはどれでもおいしいです。","ko":"이 가게 케이크는 어느 것이든 맛있습니다."},{"jp":"どれでも一[ひと]つ選[えら]んでください。","ko":"어느 것이든 하나 골라 주세요."}],"dr":[{"t":"make","q":"どれ + いいです → '어느 것이든 좋아요'","a":"どれでもいいです","hint":"どれ 뒤에 でも를 붙인다."},{"t":"make","q":"どちら + いいです → '어느 쪽이든 좋아요'","a":"どちらでもいいです","hint":"둘 중이면 どちら + でも."},{"t":"fill","q":"ここにある本[ほん]は（　）読[よ]んでいいですよ。","a":"どれでも","opts":["どれでも","どれも","どれか","どの"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei16_4.pdf"],"vf":1,"u":11,"g":1,"gp":"gg_N5_07"},{"id":"g5_004","t":"～。じゃ、～","ko":"그럼, 그러면 (회화체)","cat":"부사·접속사","conn":[{"w":"상대의 말·상황 뒤(보통체)","f":"雨だ。じゃ、バスで行こう。"},{"w":"정중체 문장 앞","f":"じゃ、また明日。/ じゃ、これをください。"},{"w":"길게 늘인 형태","f":"じゃあ、～"}],"rule":["앞에서 나온 말이나 상황 A를 받는다.","다음 말 첫머리에 じゃ(또는 じゃあ)를 놓고 、를 찍는다.","뒤 B에는 A를 근거로 한 결정·제안·질문, 또는 헤어지는 인사를 쓴다.","じゃ는 では의 で+は가 줄어 じゃ가 된 꼴이다(では → じゃ)."],"why":"それでは를 짧게 한 では, 그 では를 다시 줄인 것이 じゃ(あ)다. 구조상 それ + で + は로 '그렇다면'이라는 뜻이 된다.","nu":"매우 구어적. 친구·가족, 가게에서의 짧은 대화에 쓴다. 회의나 발표 시작처럼 격식 있는 자리에서는 では / それでは를 쓴다. 헤어질 때 じゃ、また만으로 인사가 된다.","cmp":[{"g":"それでは","d":"같은 뜻의 격식형. じゃ는 가장 가벼운 형태."}],"ex":[{"jp":"雨[あめ]だね。じゃ、バスで行[い]こう。","ko":"비 오네. 그럼 버스로 가자."},{"jp":"じゃ、このシャツをください。","ko":"그럼 이 셔츠 주세요."},{"jp":"もう六時[ろくじ]だ。じゃあ、また明日[あした]。","ko":"벌써 6시다. 그럼 내일 봐."}],"dr":[{"t":"make","q":"では → 회화체로 줄이기","a":"じゃ","hint":"で+は가 합쳐져 じゃ가 된다."},{"t":"make","q":"お腹がすいた / ご飯を食べよう → じゃ","a":"お腹がすいた。じゃ、ご飯を食べよう。","hint":"상황 A 。 + じゃ、 + 제안 B."},{"t":"fill","q":"A：もう時間[じかん]がないよ。 B：（　）、タクシーで行[い]こう。","a":"じゃ","opts":["じゃ","でも","しかし","けれども"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%AF-%E3%81%9D%E3%82%8C%E3%81%A7%E3%81%AF-%E3%81%98%E3%82%83%E3%81%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_08"},{"id":"g5_005","t":"～。それじゃ、～","ko":"그럼, 그렇다면 (회화체)","cat":"부사·접속사","conn":[{"w":"상대의 말·상황 뒤(보통체)","f":"休みだ。それじゃ、出かけよう。"},{"w":"정중체","f":"休みです。それじゃ、出かけましょう。"},{"w":"늘인 형태","f":"それじゃあ、～"}],"rule":["앞의 말이나 상황 A를 받는다.","다음 말 첫머리에 それじゃ를 놓고 、를 찍는다.","B에는 A를 근거로 한 판단·제안, 또는 마무리·작별 인사를 쓴다.","それじゃ는 それでは의 では가 じゃ로 줄어든 꼴이다(それでは → それじゃ)."],"why":"それ(그것) + で + は로 '그렇다면'이라는 뜻이며, では 부분이 회화에서 じゃ로 줄어 それじゃ가 되었다.","nu":"회화체. じゃ보다 '그것'을 받는 느낌이 조금 분명하다. 윗사람 앞의 격식 있는 마무리에는 それでは가 낫다.","cmp":[{"g":"じゃ","d":"それ를 뺀 더 짧은 형태로 뜻은 같다."},{"g":"それでは","d":"같은 뜻의 격식형."}],"ex":[{"jp":"明日[あした]は休[やす]みだ。それじゃ、映画[えいが]を見[み]に行[い]こう。","ko":"내일은 쉬는 날이다. 그럼 영화 보러 가자."},{"jp":"レストランが込[こ]んでいます。それじゃ、ほかの店[みせ]にしましょう。","ko":"레스토랑이 붐벼요. 그럼 다른 가게로 하죠."},{"jp":"それじゃあ、また来週[らいしゅう]。","ko":"그럼 다음 주에 봐."}],"dr":[{"t":"make","q":"それでは → 회화체","a":"それじゃ","hint":"では가 じゃ로 줄어든다."},{"t":"make","q":"電気が消えた / ろうそくを使おう → それじゃ","a":"電気が消えた。それじゃ、ろうそくを使おう。","hint":"상황 A 。 + それじゃ、 + 제안 B."},{"t":"fill","q":"A：このパン、もう古[ふる]いよ。 B：（　）、新[あたら]しいのを買[か]おう。","a":"それじゃ","opts":["それじゃ","それから","けれども","しかし"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%AF-%E3%81%9D%E3%82%8C%E3%81%A7%E3%81%AF-%E3%81%98%E3%82%83%E3%81%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_08"},{"id":"g5_006","t":"～。それでは、～","ko":"그러면, 그럼 (격식)","cat":"부사·접속사","conn":[{"w":"상대의 말·상황 뒤","f":"時間です。それでは、始めます。"},{"w":"화제 전환","f":"それでは、次の問題です。"},{"w":"마무리 인사","f":"それでは、失礼します。"}],"rule":["앞의 말이나 상황 A를 받는다.","다음 말 첫머리에 それでは를 놓고 、를 찍는다.","B에는 A를 근거로 한 결론·제안, 다음 화제로 넘어가는 말, 또는 마무리 인사가 온다.","회화에서는 では → じゃ로 줄어 それじゃ / じゃ가 된다."],"why":"それ(그것) + で + は로 이루어져 '그렇다면'의 뜻이 된다. 그 줄임꼴이 では, じゃ(あ)다.","nu":"では·じゃ 계열 중 가장 격식 있는 형태. 회의·수업·방송·발표의 시작과 끝, 장면 전환에 자주 쓴다. 친구 사이에서는 딱딱하게 들린다.","cmp":[{"g":"では","d":"それ를 뺀 형태로 역시 정중하지만 それでは보다 약간 짧고 가볍다."},{"g":"じゃ","d":"가장 구어적인 줄임꼴."}],"ex":[{"jp":"時間[じかん]になりました。それでは、始[はじ]めましょう。","ko":"시간이 됐습니다. 그럼 시작합시다."},{"jp":"それでは、次[つぎ]のページを見[み]てください。","ko":"그러면 다음 페이지를 봐 주세요."},{"jp":"雨[あめ]が降[ふ]ってきました。それでは、中[なか]で遊[あそ]びましょう。","ko":"비가 오기 시작했어요. 그러면 안에서 놉시다."}],"dr":[{"t":"make","q":"じゃ → 격식형(それ 포함)","a":"それでは","hint":"じゃ는 では의 줄임, 앞에 それ를 붙인다."},{"t":"make","q":"みんな来ました / 会議を始めます → それでは","a":"みんな来ました。それでは、会議を始めます。","hint":"상황 A 。 + それでは、 + B."},{"t":"fill","q":"皆[みな]さん、そろいましたね。（　）、授業[じゅぎょう]を始[はじ]めます。","a":"それでは","opts":["それでは","しかし","それに","けれども"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%AF-%E3%81%9D%E3%82%8C%E3%81%A7%E3%81%AF-%E3%81%98%E3%82%83%E3%81%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_08"},{"id":"g5_007","t":"～。では、～","ko":"그럼, 그러면","cat":"부사·접속사","conn":[{"w":"상대의 말·상황 뒤","f":"雨です。では、家にいましょう。"},{"w":"화제 전환·시작","f":"では、始めます。"},{"w":"작별","f":"では、また。"}],"rule":["앞의 말이나 상황 A를 받는다.","다음 말 첫머리에 では를 놓고 、를 찍는다.","B에는 A를 근거로 한 결론·제안, 새 화제, 또는 작별 인사가 온다.","では는 それでは에서 それ를 뺀 꼴이며(それでは → では), 회화에서는 다시 じゃ로 줄어든다."],"why":"それでは(それ + で + は, '그렇다면')에서 それ가 빠진 형태로, 같은 '그럼, 그렇다면'의 뜻을 갖는다.","nu":"정중한 정도는 それでは > では > じゃ 순. 수업·회의·가게 응대 등 정중한 자리에 무난하다. 명사 + では('~에서는', で + は)와 모양이 같으니 문장 첫머리에서 、와 함께 쓰이는지로 구별한다.","cmp":[{"g":"それでは","d":"같은 뜻이지만 それでは가 조금 더 격식 있다."},{"g":"じゃ","d":"では의 회화체 줄임꼴."}],"ex":[{"jp":"A：明日[あした]は雨[あめ]ですよ。 B：では、家[いえ]で映画[えいが]を見[み]ましょう。","ko":"A: 내일은 비 와요. B: 그럼 집에서 영화 봐요."},{"jp":"では、テストを始[はじ]めます。","ko":"그럼 시험을 시작하겠습니다."},{"jp":"では、また明日[あした]。","ko":"그럼 내일 또 봐요."}],"dr":[{"t":"make","q":"それでは → それ를 뺀 형태","a":"では","hint":"それでは에서 それ만 빠진다."},{"t":"make","q":"雨です / 家にいましょう → では","a":"雨です。では、家にいましょう。","hint":"상황 A 。 + では、 + 결론 B."},{"t":"fill","q":"A：その本[ほん]はもう読[よ]みました。 B：（　）、この本[ほん]はどうですか。","a":"では","opts":["では","しかし","けれども","それから"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%AF-%E3%81%9D%E3%82%8C%E3%81%A7%E3%81%AF-%E3%81%98%E3%82%83%E3%81%82"],"vf":1,"u":11,"g":1,"gp":"gg_N5_08"},{"id":"g5_062","t":"あまり～ありません","ko":"별로 ~하지 않습니다 (정중)","cat":"부사·접속사","conn":[{"w":"い형용사","f":"高い → あまり高くありません"},{"w":"い형용사(いい)","f":"いい → あまりよくありません"},{"w":"な형용사","f":"静か → あまり静かではありません(じゃありません)"},{"w":"명사 + が(ある)","f":"時間がある → あまり時間がありません"},{"w":"동사","f":"飲む → あまり飲みません(ます형 + ません)"}],"rule":["い형용사는 끝의 い를 く로 바꾸고 ありません을 붙인다(高い → 高くありません). いい는 よくありません.","な형용사·명사는 では(じゃ) + ありません을 붙인다(静かではありません).","동사는 ありません을 직접 붙이지 않고 ます형의 ます를 ません으로 바꾼다(飲みます → 飲みません).","그 앞에 정도를 나타내는 부사 あまり를 두어 '별로 ~하지 않다'가 된다."],"why":"あまり(余り)는 원래 '남음, 나머지'라는 명사인데, 부정 표현과 함께 부사로 쓰이면 정도·빈도가 높지 않음을 나타낸다. ありません은 ある의 정중 부정형으로, 형용사의 정중 부정(くありません / ではありません)에 쓰인다.","nu":"〜ないです보다 더 격식 있는 정중 부정. あまり는 반드시 부정과 함께 써야 '별로'라는 뜻이 된다(×あまり高いです). 회화에서는 あんまり라고도 한다. 동사에 '飲まないありません'처럼 붙이는 실수에 주의.","cmp":[{"g":"あまり～ないです","d":"뜻은 같고 ないです가 더 일상적인 정중체, ありません이 더 격식 있다."},{"g":"全然～ない","d":"全然은 '전혀'로 완전 부정, あまり는 '별로'로 정도가 낮음을 말한다."}],"ex":[{"jp":"このかばんはあまり高[たか]くありません。","ko":"이 가방은 별로 비싸지 않습니다."},{"jp":"この町[まち]はあまり静[しず]かではありません。","ko":"이 동네는 별로 조용하지 않습니다."},{"jp":"今日[きょう]はあまり時間[じかん]がありません。","ko":"오늘은 시간이 별로 없습니다."}],"dr":[{"t":"make","q":"寒い → あまり～ありません","a":"あまり寒くありません","hint":"い를 く로 바꾸고 ありません."},{"t":"make","q":"上手 → あまり～ありません","a":"あまり上手ではありません","hint":"な형용사는 では + ありません."},{"t":"fill","q":"この料理[りょうり]は（　）おいしくありません。","a":"あまり","opts":["あまり","とても","もっと","よく"]}],"src":["https://www.tofugu.com/japanese-grammar/amarinai/"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_063","t":"あまり～ないです","ko":"별로 ~하지 않아요","cat":"부사·접속사","conn":[{"w":"1그룹 동사","f":"飲む → 飲まない + です"},{"w":"2그룹 동사","f":"食べる → 食べない + です"},{"w":"する / 来る","f":"する → しない、来る → 来(こ)ない + です"},{"w":"い형용사","f":"面白い → 面白くない + です (いい → よくない)"},{"w":"な형용사·명사","f":"親切 → 親切じゃない + です"}],"rule":["동사를 ない형으로 바꾼다. 1그룹은 어미 う단을 あ단으로 바꾸고 ない(飲む → 飲まない), 2그룹은 る를 떼고 ない(食べる → 食べない).","する는 しない, 来る는 こない가 된다.","い형용사는 い를 くない로(面白い → 面白くない), な형용사·명사는 じゃない(ではない)를 붙인다.","부정형 뒤에 です를 붙여 정중하게 만들고, 앞에 あまり를 둔다."],"why":"보통체 부정(～ない) 뒤에 です를 붙여 정중하게 만든 형태다. あまり는 원래 '남음'을 뜻하는 명사(余り)로, 부정과 함께 쓰이면 정도·빈도가 높지 않음을 나타내는 부사가 된다.","nu":"회화에서 흔한 정중체로, ～ありません보다 부드럽고 덜 딱딱하다. 동사에 쓰면 '자주/많이 하지 않는다'(빈도·양)를 나타낸다. 설명하는 느낌으로 ～ないんです도 자주 쓴다. 회화체로 あんまり도 가능.","cmp":[{"g":"あまり～ありません","d":"같은 뜻이지만 ありません 쪽이 더 격식 있다. 동사는 ～ません(飲みません)이 된다."},{"g":"全然～ない","d":"全然은 '전혀'로 완전 부정, あまり는 정도가 낮을 뿐 조금은 있음."}],"ex":[{"jp":"朝[あさ]ご飯[はん]はあまり食[た]べないです。","ko":"아침밥은 별로 안 먹어요."},{"jp":"この映画[えいが]はあまり面白[おもしろ]くないです。","ko":"이 영화는 별로 재미없어요."},{"jp":"私[わたし]の部屋[へや]はあまりきれいじゃないです。","ko":"제 방은 별로 깨끗하지 않아요."}],"dr":[{"t":"make","q":"行く → あまり～ないです","a":"あまり行かないです","hint":"く를 か로 바꾸고 ない + です."},{"t":"make","q":"難しい → あまり～ないです","a":"あまり難しくないです","hint":"い를 くない로 + です."},{"t":"fill","q":"お酒[さけ]は（　）飲[の]まないです。","a":"あまり","opts":["あまり","たくさん","とても","いつも"]}],"src":["https://www.tofugu.com/japanese-grammar/amarinai/"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_067","t":"いつか","ko":"언젠가 (미래), 언젠가 한번 (과거)","cat":"부사·접속사","conn":[{"w":"문장 앞(미래·희망)","f":"いつか + 日本に行きたい"},{"w":"문장 앞(추측)","f":"いつか + 有名になるでしょう"},{"w":"과거 문장","f":"いつか + 来たことがある道"}],"rule":["의문사 いつ(언제)에 か를 붙이면 '언젠가'라는 정해지지 않은 때가 된다.","활용은 없고 문장 앞이나 주어 뒤에 놓아 '언젠가 ~하고 싶다/하겠다'처럼 쓴다(いつか日本に行きたい).","의문문이 아니므로 문장 끝에 か를 붙이지 않는다."],"why":"いつ(何時)는 '언제'를 묻는 의문사이고, 의문사 + か는 なにか(무언가)·だれか(누군가)처럼 '정해지지 않은 무엇'을 나타낸다. 그래서 いつか는 시점을 특정하지 않은 '언젠가'가 된다.","nu":"주로 미래의 막연한 희망·예정(～たい, ～つもり, ～でしょう)과 함께 쓴다. 과거의 불확실한 때(언젠가 전에)에도 쓸 수 있다. 회화·문어 모두 가능. いつかは는 '언젠가는'으로 강조. 의문사 いつ(언제?)와 혼동하지 말 것: いつ行きますか(언제 가요?) / いつか行きます(언젠가 갈게요).","cmp":[{"g":"いつも","d":"いつも는 '항상', いつか는 '언젠가 한 번'으로 정해지지 않은 한 시점."},{"g":"いつでも","d":"いつでも는 '언제든지(어느 때라도)', いつか는 '언젠가(어느 한 때)'."}],"ex":[{"jp":"いつか日本[にほん]に行[い]きたいです。","ko":"언젠가 일본에 가고 싶어요."},{"jp":"いつか一緒[いっしょ]に旅行[りょこう]しましょう。","ko":"언젠가 같이 여행해요."},{"jp":"この歌[うた]はいつか聞[き]いたことがあります。","ko":"이 노래는 언젠가 들은 적이 있어요."}],"dr":[{"t":"make","q":"いつ + か → '언젠가 집을 사고 싶다' (家を買いたい)","a":"いつか家を買いたい","hint":"いつ에 か를 붙여 문장 앞에 둔다."},{"t":"make","q":"いつ行きますか → '언젠가 가요'","a":"いつか行きます","hint":"의문사 いつ에 か를 붙이고 끝의 か는 없앤다."},{"t":"fill","q":"（　）富士山[ふじさん]に登[のぼ]りたいです。","a":"いつか","opts":["いつか","いつ","いつも","いくつ"]}],"src":["https://kotobank.jp/word/何時か","https://www.vnjpclub.com/en/n5-grammar/itsuka.html"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_068","t":"いつでも","ko":"언제든지, 언제라도","cat":"부사·접속사","conn":[{"w":"동사 て형 + ください","f":"いつでも + 来てください"},{"w":"가능형","f":"いつでも + 会えます"},{"w":"명사·형용사 술어","f":"いつでも + 元気です"},{"w":"いい","f":"いつでもいいです(언제라도 좋아요)"}],"rule":["의문사 いつ에 でも를 붙이면 '언제든지'라는 뜻이 된다(いつ + でも).","활용은 없고 동사·형용사 앞에 놓는다. 특히 ～てください, 가능형, いい와 잘 어울린다(いつでも来てください)."],"why":"사전에 따르면 대명사 いつ에 조사 で와 も가 붙어 생긴 말이다. 의문사 + でも는 だれでも(누구든지)·どこでも(어디든지)처럼 '어떤 ~라도'를 뜻한다.","nu":"'어느 때라도 상관없다'는 허용·환영의 뉘앙스가 강해 초대·제안에 자주 쓴다(いつでも連絡してください). '항상'의 뜻으로도 쓰지만, 습관을 말할 때는 いつも가 더 자연스럽다. 회화·문어 모두 가능.","cmp":[{"g":"いつも","d":"いつも는 '평소에 늘(습관)', いつでも는 '어느 때든지(때를 가리지 않음)'."},{"g":"いつか","d":"いつか는 정해지지 않은 어느 한 때, いつでも는 모든 때."}],"ex":[{"jp":"いつでも遊[あそ]びに来[き]てください。","ko":"언제든지 놀러 오세요."},{"jp":"この店[みせ]はいつでも開[あ]いています。","ko":"이 가게는 언제든지 열려 있어요."},{"jp":"電話[でんわ]はいつでもいいですよ。","ko":"전화는 언제라도 괜찮아요."}],"dr":[{"t":"make","q":"いつ + でも → '언제든지 질문해 주세요' (質問してください)","a":"いつでも質問してください","hint":"いつ에 でも를 붙여 앞에 둔다."},{"t":"make","q":"どこでも行けます → '언제든지 갈 수 있어요'","a":"いつでも行けます","hint":"どこでも를 시간의 의문사 いつ + でも로 바꾼다."},{"t":"fill","q":"困[こま]ったら、（　）電話[でんわ]してください。","a":"いつでも","opts":["いつでも","いつか","いくつ","いつ"]}],"src":["https://kotobank.jp/word/何時でも"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_069","t":"いつも","ko":"항상, 늘, 평소","cat":"부사·접속사","conn":[{"w":"동사","f":"いつも + 7時に起きます"},{"w":"い형용사","f":"いつも + 忙しい"},{"w":"な형용사·명사","f":"いつも + 元気です"},{"w":"명사로 (いつもの)","f":"いつも + の + 店"}],"rule":["의문사 いつ에 も를 붙이면 '언제나, 항상'이 된다(いつ + も).","활용 없이 동사·형용사 앞에 놓는다(いつも7時に起きます).","명사처럼 の를 붙여 '평소의, 늘 가던'을 만들 수 있다(いつもの店)."],"why":"의문사 いつ(언제)에 も가 붙은 말로, '어느 때나'라는 뜻에서 '항상'이 된다. 사전에서는 부사(늘)와 명사(평소) 두 용법을 싣고 있다.","nu":"습관·반복을 말할 때 가장 기본적인 말. 현재형 동사와 쓰면 습관이 된다(いつも歩いて行きます). いつもは는 '평소에는'(오늘은 다르다는 대비). 부정문 いつも～ない는 '늘 ~하지 않는다'. 강조 회화체는 いっつも. 문어적인 동의어는 常に.","cmp":[{"g":"いつでも","d":"いつでも는 '언제든지(때를 가리지 않음)'로 허용·환영에 쓰고, いつも는 실제로 늘 그렇게 하는 습관."},{"g":"よく","d":"よく는 '자주'(빈도가 높음), いつも는 거의 예외 없이 '항상'."}],"ex":[{"jp":"私[わたし]はいつも七時[しちじ]に起[お]きます。","ko":"저는 항상 7시에 일어나요."},{"jp":"兄[あに]はいつも忙[いそが]しいです。","ko":"형은 늘 바빠요."},{"jp":"いつもの店[みせ]で会[あ]いましょう。","ko":"늘 가던 가게에서 만나요."}],"dr":[{"t":"make","q":"いつ + も → '항상 버스로 가요' (バスで行きます)","a":"いつもバスで行きます","hint":"いつ에 も를 붙여 동사 앞에 둔다."},{"t":"make","q":"店 → '평소의 가게' (いつも 사용)","a":"いつもの店","hint":"いつも + の + 명사."},{"t":"fill","q":"父[ちち]は（　）朝[あさ]コーヒーを飲[の]みます。","a":"いつも","opts":["いつも","いつか","いくつ","いかが"]}],"src":["https://kotobank.jp/word/何時も"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_080","t":"さっき","ko":"아까, 조금 전에","cat":"부사·접속사","conn":[{"w":"동사 과거형","f":"さっき + 電話がありました"},{"w":"명사 수식","f":"さっき + の + 人"},{"w":"から(그때부터 계속)","f":"さっき + から + 待っている"}],"rule":["さっき는 조금 전의 때를 나타내는 말로 문장 앞쪽에 둔다.","뒤의 동사는 이미 끝난 일이므로 과거형(た／ました)으로 맺는다(あった／ありました).","명사를 꾸밀 때는 の를 넣고(さっきの人), 그때부터 지금까지 계속이면 さっきから를 쓴다."],"why":"さっき는 先(さき, 앞·이전)에 촉음(っ)이 더해진 말로, '조금 앞의 때'를 뜻한다.","nu":"회화체. 격식 있는 자리나 손님에게는 先ほど(さきほど)를 쓴다. 몇 분~몇 시간 전 정도의 가까운 과거에 쓰며, 며칠 전 일에는 쓰지 않는다. さっきから ~ている는 '아까부터 계속 ~하고 있다'.","cmp":[{"g":"先ほど","d":"뜻은 같고 先ほど가 더 정중한 말."},{"g":"今","d":"今(지금)는 현재나 '방금'을 나타내고, さっき는 그보다 조금 더 이전의 때."}],"ex":[{"jp":"さっき友達[ともだち]から電話[でんわ]がありました。","ko":"아까 친구에게서 전화가 왔어요."},{"jp":"さっきの人[ひと]はだれですか。","ko":"아까 그 사람은 누구예요?"},{"jp":"さっきから雨[あめ]が降[ふ]っている。","ko":"아까부터 비가 오고 있다."}],"dr":[{"t":"make","q":"さっき＋ご飯を食べる → 과거 정중형으로","a":"さっきご飯を食べました","hint":"끝난 일이므로 ます를 ました로."},{"t":"make","q":"さっき＋人 → 명사를 꾸미는 형태","a":"さっきの人","hint":"명사 앞에서는 の를 넣는다."},{"t":"fill","q":"（　）田中[たなか]さんに会[あ]いました。","a":"さっき","opts":["さっき","あした","これから","らいしゅう"]}],"src":["https://www.weblio.jp/content/%E3%81%95%E3%81%A3%E3%81%8D","https://kotobank.jp/word/%E5%85%88%E5%88%BB"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_081","t":"すぐに","ko":"곧, 바로, 즉시","cat":"부사·접속사","conn":[{"w":"동사","f":"すぐに + 行きます"},{"w":"동사(すぐ만)","f":"すぐ + 帰ります"},{"w":"거리(すぐ)","f":"駅は すぐ そこです"}],"rule":["すぐに는 동사 앞에 두어 그 동작이 지체 없이 일어남을 나타낸다(すぐに行きます).","に를 빼고 すぐ만 써도 같은 뜻이다(すぐ行きます).","すぐ는 거리·쉬움에도 쓰이지만(すぐそこ: 바로 저기), 이때는 보통 に를 붙이지 않는다."],"why":"すぐ(直ぐ)는 시간 간격이 거의 없음, 거리가 매우 가까움, 손쉬움을 나타내는 부사이고, すぐに는 그 시간의 뜻으로 쓰는 형태다.","nu":"회화와 글 모두에 쓴다. 명령·부탁(すぐに来てください)과 잘 어울린다. 더 딱딱한 말은 ただちに(공지·명령). 한국어 '곧'은 '조금 뒤에'라는 뜻도 있지만 すぐに는 '바로, 즉시'에 가깝다.","cmp":[{"g":"もうすぐ","d":"もうすぐ는 '머지않아, 이제 곧'(앞으로 다가올 때). すぐに는 어떤 일 다음에 '바로'."},{"g":"ただちに","d":"뜻은 비슷하지만 ただちに는 격식체로 명령·안내문에 주로 쓴다."}],"ex":[{"jp":"家[いえ]に帰[かえ]ったら、すぐに手[て]を洗[あら]います。","ko":"집에 돌아가면 바로 손을 씻어요."},{"jp":"呼[よ]ばれて、すぐに行[い]きました。","ko":"불려서 바로 갔습니다."},{"jp":"この本[ほん]はやさしいから、すぐ読[よ]めます。","ko":"이 책은 쉬우니까 금방 읽을 수 있어요."}],"dr":[{"t":"make","q":"来てください → '바로' 의미를 더해서","a":"すぐに来てください","hint":"동사 앞에 すぐに를 둔다."},{"t":"make","q":"帰ります → 'すぐ'를 써서","a":"すぐ帰ります","hint":"すぐ는 に 없이도 동사 앞에 쓴다."},{"t":"fill","q":"電話[でんわ]が鳴[な]ったので、（　）出[で]ました。","a":"すぐに","opts":["すぐに","ぜんぜん","あまり","もうすぐ"]}],"src":["https://kotobank.jp/word/%E7%9B%B4%E3%81%90-541214"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_082","t":"ぜんぜん～ない","ko":"전혀 ~하지 않다","cat":"부사·접속사","conn":[{"w":"동사 ない형","f":"ぜんぜん + わからない"},{"w":"い형용사 부정","f":"ぜんぜん + 寒くない"},{"w":"な형용사·명사 부정","f":"ぜんぜん + 静かじゃない"},{"w":"정중형","f":"ぜんぜん + わかりません"}],"rule":["ぜんぜん(全然)을 서술어 앞에 둔다.","서술어는 부정형으로 바꾼다. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다(わかる → わから + ない).","い형용사는 い를 く로 바꾸고 ない(寒い → 寒くない), な형용사·명사는 じゃない를 붙인다."],"why":"全然은 본래 '남김없이, 모두'라는 뜻의 한어로 메이지 시대에 퍼졌고, 다이쇼 말~쇼와 무렵부터 부정 표현과 강하게 결합해 '조금도 ~않다'라는 뜻이 표준 용법이 되었다.","nu":"부정과 함께 쓰는 것이 표준 용법이다. 회화에서 'ぜんぜん大丈夫(완전 괜찮아)'처럼 긍정을 강조하는 용법도 있지만 속된 말투이므로 시험·격식 있는 글에서는 피한다. 정도가 약한 '별로 ~않다'는 あまり~ない.","cmp":[{"g":"あまり～ない","d":"あまり~ない는 '별로 ~않다'(조금은 함). ぜんぜん~ない는 '전혀 ~않다'(0에 가까움)."},{"g":"少しも～ない","d":"뜻은 거의 같고, 少しも는 조금 더 문어적인 느낌."}],"ex":[{"jp":"この問題[もんだい]はぜんぜんわからない。","ko":"이 문제는 전혀 모르겠어."},{"jp":"今日[きょう]はぜんぜん寒[さむ]くないですね。","ko":"오늘은 전혀 춥지 않네요."},{"jp":"昨日[きのう]はぜんぜん寝[ね]ませんでした。","ko":"어제는 전혀 자지 않았습니다."}],"dr":[{"t":"make","q":"飲む → ぜんぜん～ない","a":"ぜんぜん飲まない","hint":"1그룹: 어미 む를 ま로 바꾸고 ない."},{"t":"make","q":"高い → ぜんぜん～ない","a":"ぜんぜん高くない","hint":"い형용사: い를 く로 바꾸고 ない."},{"t":"fill","q":"日本語[にほんご]が（　）話[はな]せません。","a":"ぜんぜん","opts":["ぜんぜん","とても","ぜひ","もっと"]}],"src":["https://kotobank.jp/word/%E5%85%A8%E7%84%B6"],"vf":1,"u":12,"g":1,"gp":"gg_N5_08"},{"id":"g5_083","t":"そして、～","ko":"그리고, 그러고 나서","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"食べました。そして、寝ました。"},{"w":"명사·형용사 나열(뒤에 더함)","f":"安くて、そして おいしい"}],"rule":["앞 문장을 마침표로 끝낸 뒤, 다음 문장 맨 앞에 そして를 둔다.","뒤 문장은 앞 문장에 이어지는 다음 일(순서)이나 덧붙이는 내용(첨가)이 된다.","そして 뒤에는 보통 쉼표(、)를 찍는다."],"why":"そして는 앞의 내용에 뒤의 내용을 더하는(並立・添加) 접속사로, 영어 and에 해당한다.","nu":"회화와 글 모두에 쓰는 중립적인 말. 한 문장 안에서 동작을 이을 때는 て형(食べて、寝た)이 더 자연스럽고, そして는 문장과 문장을 이을 때 주로 쓴다. 회화에서 순서를 강조하면 それから도 많이 쓴다. 이유·결과를 잇는 말(그래서)이 아니다.","cmp":[{"g":"それから","d":"それから는 '그다음에'로 시간 순서를 더 분명히 한다. そして는 순서와 단순 첨가 모두에 쓴다."},{"g":"だから","d":"だから는 '그러니까, 그래서'로 원인·결과를 잇는다. そして에는 이유의 뜻이 없다."}],"ex":[{"jp":"晩[ばん]ご飯[はん]を食[た]べました。そして、すぐ寝[ね]ました。","ko":"저녁을 먹었습니다. 그리고 바로 잤습니다."},{"jp":"この店[みせ]は安[やす]いです。そして、とてもおいしいです。","ko":"이 가게는 쌉니다. 그리고 아주 맛있습니다."},{"jp":"駅[えき]で友達[ともだち]に会[あ]った。そして、一緒[いっしょ]に映画[えいが]を見[み]た。","ko":"역에서 친구를 만났다. 그리고 함께 영화를 봤다."}],"dr":[{"t":"make","q":"シャワーを浴びました／寝ました → そして로 잇기","a":"シャワーを浴びました。そして、寝ました。","hint":"앞 문장을 끝내고 다음 문장 앞에 そして."},{"t":"make","q":"部屋はきれいです／広いです → そして로 잇기","a":"部屋はきれいです。そして、広いです。","hint":"덧붙이는 내용도 そして로 잇는다."},{"t":"fill","q":"朝[あさ]、顔[かお]を洗[あら]いました。（　）、ご飯[はん]を食[た]べました。","a":"そして","opts":["そして","でも","だから","しかし"]}],"src":["https://www.seirei.ac.jp/media/about_setsuzoku-shi.pdf"],"vf":1,"u":12,"g":1,"gp":"gg_N5_09"},{"id":"g5_085","t":"それから、～","ko":"그러고 나서, 그 다음에 / 그리고 또","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"ご飯を食べました。それから、寝ました。"},{"w":"て형 + それから","f":"宿題をして、それから遊びました。"},{"w":"명사 열거(추가)","f":"りんごとみかん、それからバナナも買いました。"}],"rule":["앞 문장(또는 て형으로 끝난 절)을 먼저 말한다.","그 뒤에 それから를 넣고, 시간상 그 다음에 일어난 일을 말한다(食べた。それから寝た。).","활용은 없다. それから 자체는 모양이 바뀌지 않고 문장 맨 앞이나 て형 뒤에 놓인다.","물건·내용을 덧붙일 때도 쓴다(A、それからB도)."],"why":"지시어 それ(그것) + から(~부터)로 이루어져 '그것으로부터 (이어서)', 즉 앞 일이 끝난 다음을 가리킨다.","nu":"회화·문장 모두 쓰는 중립적인 말. 순서(그 다음에)와 추가(그리고 또) 두 가지 용법이 있다. 원인·결과를 잇는 말이 아니므로 '그래서'의 뜻으로 쓰면 틀린다(그래서는 それで / だから). 한국어 '그리고'를 모두 それから로 옮기면 어색할 때가 있어, 단순 병렬은 そして도 쓴다.","cmp":[{"g":"そして","d":"そして는 앞뒤를 단순히 잇는 '그리고'로 문어적 느낌도 있다. それから는 '그 일이 끝난 다음에'라는 시간 순서가 더 뚜렷하다."},{"g":"それで","d":"それで는 '그래서'로 앞 일이 뒤 일의 원인이 된다. それから는 원인 관계 없이 순서만 나타낸다."}],"ex":[{"jp":"朝[あさ]ご飯[はん]を食[た]べました。それから、学校[がっこう]へ行[い]きました。","ko":"아침밥을 먹었습니다. 그러고 나서 학교에 갔습니다."},{"jp":"手[て]を洗[あら]って、それから晩[ばん]ご飯[はん]を食[た]べましょう。","ko":"손을 씻고 나서 저녁을 먹읍시다."},{"jp":"パンと牛乳[ぎゅうにゅう]、それから卵[たまご]も買[か]ってください。","ko":"빵이랑 우유, 그리고 달걀도 사 주세요."}],"dr":[{"t":"make","q":"シャワーを浴びました。／寝ました。 → それから로 잇기","a":"シャワーを浴びました。それから寝ました。","hint":"먼저 한 일 다음에 それから를 넣고 나중에 한 일을 말한다."},{"t":"make","q":"本を読んで／テレビを見ました → て형 + それから","a":"本を読んで、それからテレビを見ました。","hint":"て형으로 앞 절을 끝내고 바로 それから를 붙인다."},{"t":"fill","q":"駅[えき]で電車[でんしゃ]を降[お]りました。（　）、バスに乗[の]りました。","a":"それから","opts":["それから","でも","しかし","それとも"]}],"src":["https://aiueo.cc/pages_v2/ja/grammar/web/38.php","https://www.seirei.ac.jp/media/about_setsuzoku-shi.pdf"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_086","t":"だいたい～","ko":"대략, 대체로, 거의","cat":"부사·접속사","conn":[{"w":"수량·시간 앞","f":"だいたい + 5分 → だいたい5分です"},{"w":"동사 앞(정도)","f":"だいたい + わかります → だいたいわかります"},{"w":"だいたいの + 명사","f":"だいたいの人 (대부분의 사람)"}],"rule":["숫자·시간·양 앞에 だいたい를 놓아 '대략 그 정도'임을 나타낸다(5分 → だいたい5分).","끝에 です를 붙이면 정중한 문장이 된다(だいたい5分です).","동사 앞에 두면 '대체로, 거의 다' 그렇다는 뜻이 된다(だいたいわかります).","명사를 꾸밀 때는 の를 넣는다(だいたいの人)."],"why":"한자로 大体(큰 몸체)라고 쓰며, 사물의 큰 줄기·대강을 뜻하는 명사에서 '대강, 대략'이라는 부사 용법이 나왔다.","nu":"회화에서 매우 자주 쓴다. 정확하지 않은 어림수를 말할 때 쓰며, 뒤에 ぐらい(くらい)를 함께 붙여 だいたい5分ぐらい처럼 말하는 일도 많다. 회화에서 '애초에, 원래(だいたい君が悪い)'라는 비난조 용법도 있지만 N5에서는 '대략'의 뜻부터 익힌다. 빈도(대개, 보통)를 말할 때는 たいてい가 더 자연스럽다.","cmp":[{"g":"たいてい","d":"たいてい는 '대개, 보통'으로 어떤 일이 일어나는 빈도를 말한다. だいたい는 주로 수량·정도가 '대략' 그렇다는 뜻이다."},{"g":"～ぐらい","d":"ぐらい는 수량 뒤에 붙는 조사(5分ぐらい). だいたい는 수량 앞에 오는 부사로, 둘을 함께 쓸 수도 있다."}],"ex":[{"jp":"家[いえ]から駅[えき]までだいたい10分[じゅっぷん]です。","ko":"집에서 역까지 대략 10분입니다."},{"jp":"先生[せんせい]の話[はなし]はだいたいわかりました。","ko":"선생님 이야기는 대체로 이해했습니다."},{"jp":"このクラスのだいたいの人[ひと]は電車[でんしゃ]で来[き]ます。","ko":"이 반의 대부분의 사람은 전철로 옵니다."}],"dr":[{"t":"make","q":"30人です → だいたい～","a":"だいたい30人です","hint":"수량 바로 앞에 だいたい를 놓는다."},{"t":"make","q":"人 → だいたい～ (명사 수식)","a":"だいたいの人","hint":"명사를 꾸밀 때는 だいたい 뒤에 の를 넣는다."},{"t":"fill","q":"東京[とうきょう]から大阪[おおさか]まで新幹線[しんかんせん]で（　）3時間[さんじかん]です。","a":"だいたい","opts":["だいたい","ぜんぜん","あまり","けっして"]}],"src":["https://kotobank.jp/word/%E5%A4%A7%E4%BD%93","https://kotobank.jp/word/%E5%A4%A7%E4%BD%93-557714"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_087","t":"たいてい～","ko":"대개, 보통, 대부분","cat":"부사·접속사","conn":[{"w":"동사 앞","f":"たいてい + 7時に起きます"},{"w":"たいていの + 명사","f":"たいていの人 (대부분의 사람)"},{"w":"형용사 앞","f":"この店はたいてい安いです"}],"rule":["습관·반복되는 일을 말하는 문장 앞쪽에 たいてい를 놓는다(たいてい7時に起きます).","동사는 보통 현재형(ます형)으로 습관을 나타낸다.","명사를 꾸밀 때는 の를 넣는다(たいていの人).","활용은 없고, たいてい 자체의 모양은 바뀌지 않는다."],"why":"한자로 大抵라고 쓰지만 보통 히라가나로 쓴다. 옛 사전에서는 '대체로, 대부분'이라는 뜻에서 大体와 같은 말로 다루기도 했다.","nu":"회화·문장 모두 쓴다. '항상(いつも)'보다는 낮고 '가끔(ときどき)'보다는 높은 빈도. 한 번만 일어난 과거 사건에는 쓰지 않는다(×昨日はたいてい雨でした). 한국어 '대개'와 거의 같지만, 수량의 '대략'은 だいたい를 쓴다.","cmp":[{"g":"いつも","d":"いつも는 '항상, 늘'로 예외가 거의 없다. たいてい는 예외가 조금 있는 '대개'."},{"g":"だいたい","d":"だいたい는 주로 수량·정도의 '대략'(だいたい5分). たいてい는 빈도의 '보통'."}],"ex":[{"jp":"日曜日[にちようび]はたいてい家[いえ]で本[ほん]を読[よ]みます。","ko":"일요일에는 대개 집에서 책을 읽습니다."},{"jp":"たいていの学生[がくせい]は自転車[じてんしゃ]で来[き]ます。","ko":"대부분의 학생은 자전거로 옵니다."},{"jp":"この店[みせ]の料理[りょうり]はたいてい安[やす]くておいしいです。","ko":"이 가게 요리는 대개 싸고 맛있습니다."}],"dr":[{"t":"make","q":"朝ご飯はパンを食べます → たいてい를 넣기","a":"朝ご飯はたいていパンを食べます","hint":"습관을 말하는 동작 앞에 たいてい를 넣는다."},{"t":"make","q":"人 → たいてい～ (명사 수식)","a":"たいていの人","hint":"명사를 꾸밀 때는 の를 넣는다."},{"t":"fill","q":"わたしは（　）夜[よる]11時[じゅういちじ]に寝[ね]ます。","a":"たいてい","opts":["たいてい","ぜんぜん","あまり","けっして"]}],"src":["https://en.wiktionary.com/wiki/%E3%81%9F%E3%81%84%E3%81%A6%E3%81%84","https://kotobank.jp/word/%E5%A4%A7%E4%BD%93"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_097","t":"どうやって","ko":"어떻게 (방법·수단)","cat":"부사·접속사","conn":[{"w":"どうやって + 동사 (정중형 질문)","f":"どうやって行[い]きますか"},{"w":"どうやって + 동사 과거","f":"どうやって作[つく]りましたか"},{"w":"どうやって + 동사 보통형 (회화)","f":"どうやって使[つか]うの？"},{"w":"どうやって + 동사 사전형 + か (간접의문)","f":"どうやって読[よ]むか教[おし]えてください"}],"rule":["의문사 どう(어떻게) 뒤에 동사 やる(하다)의 て형을 붙인다.","やる는 1그룹 동사라 어미 る가 촉음 っ로 바뀌고 て가 붙어 やって가 된다(やる → やって).","그래서 どう + やって = どうやって가 되고, 그 뒤에 방법을 묻고 싶은 동사(行きますか 등)를 놓는다.","どうやって 자체는 활용하지 않는다. 시제·정중함은 뒤 동사에서 바꾼다."],"why":"どう(어떻게)에 やる(하다)의 て형 やって가 붙은 말로, 글자 그대로 '어떻게 해서'라는 뜻이다. て형이 '~해서 (그 방법으로)'를 나타내므로 수단·방법을 묻는 말이 된다.","nu":"회화·정중체 모두 쓴다. 방법·수단·경로를 물을 때 쓰고, 이유를 묻는 '어째서'에는 どうして·なぜ를 쓴다. 한국어 '어떻게'는 상태(어떻습니까)에도 쓰이지만, 상태·감상을 물을 때는 どう(どうですか)를 쓰고 どうやって는 쓰지 않는다. 격식 있는 자리에서는 どのように를 쓰기도 한다.","cmp":[{"g":"どうして","d":"どうして는 이유(왜)를 묻고, どうやって는 방법(어떻게 해서)을 묻는다."},{"g":"どう","d":"どう는 상태·의견(어때요)을 묻는 말. どうやって는 행동의 방법·수단만 묻는다."}],"ex":[{"jp":"駅[えき]までどうやって行[い]きますか。","ko":"역까지 어떻게 갑니까?"},{"jp":"このカメラはどうやって使[つか]うの？","ko":"이 카메라는 어떻게 써?"},{"jp":"日本語[にほんご]をどうやって勉強[べんきょう]しましたか。","ko":"일본어를 어떻게 공부했습니까?"}],"dr":[{"t":"make","q":"どう + やる (て형)","a":"どうやって","hint":"やる는 1그룹: る → っ + て"},{"t":"make","q":"学校[がっこう]へ来[き]ますか → 방법을 묻는 문장으로","a":"学校へどうやって来ますか","hint":"동사 바로 앞에 どうやって를 넣는다"},{"t":"fill","q":"A：家[うち]から会社[かいしゃ]まで（　）来[き]ますか。 B：バスで来[き]ます。","a":"どうやって","opts":["どうやって","どうして","いつ","だれと"]}],"src":["https://aiueo.cc/pages_v2/en/grammar/web/109.php","https://eikaiwa.weblio.jp/column/phrases/how-to-say-in-english/douyatte-english"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_100","t":"ときどき","ko":"가끔, 때때로","cat":"부사·접속사","conn":[{"w":"ときどき + 동사","f":"ときどき料理[りょうり]をします"},{"w":"ときどき + 날씨 (일기예보)","f":"晴[は]れときどき雨[あめ]"},{"w":"명사 + は + ときどき + 동사","f":"父[ちち]はときどき料理[りょうり]をします"}],"rule":["명사 とき(時, 때)를 두 번 겹친다.","뒤의 とき의 첫 글자 と가 탁음 ど로 바뀐다(연탁): とき + とき → ときどき.","한자로는 時々라고 쓰며, 々는 앞 글자를 반복한다는 표시다.","부사이므로 활용하지 않고 동사 앞에 놓는다."],"why":"時(とき)를 반복한 말이고, 두 번째 とき가 연탁으로 どき가 되었다. 時々는 時時를 줄여 쓴 표기다.","nu":"회화·문장 모두 쓴다. 빈도는 いつも(항상) > よく(자주) > ときどき(가끔) > あまり～ない(별로 ~않다) 순이다. ときどき는 긍정문에 쓰는 것이 기본이다. 일기예보의 '晴れときどき雨'는 '맑고 가끔 비'라는 뜻이다.","cmp":[{"g":"よく","d":"よく는 자주(빈도가 높음), ときどき는 가끔(빈도가 중간 이하)."},{"g":"たまに","d":"たまに는 ときどき보다 더 드문 '어쩌다 가끔'의 느낌이다."}],"ex":[{"jp":"父[ちち]はときどき料理[りょうり]をします。","ko":"아버지는 가끔 요리를 합니다."},{"jp":"ときどき駅[えき]の前[まえ]の店[みせ]でコーヒーを飲[の]みます。","ko":"가끔 역 앞 가게에서 커피를 마십니다."},{"jp":"明日[あした]は晴[は]れときどき雨[あめ]です。","ko":"내일은 맑고 가끔 비가 옵니다."}],"dr":[{"t":"make","q":"とき + とき → 한 단어로","a":"ときどき","hint":"뒤 とき의 と가 ど로 바뀐다(연탁)"},{"t":"make","q":"映画[えいが]を見[み]ます → '가끔' 넣기","a":"ときどき映画を見ます","hint":"부사 ときどき를 문장 앞(동사 앞)에 놓는다"},{"t":"fill","q":"毎日[まいにち]ではありませんが、（　）テニスをします。","a":"ときどき","opts":["ときどき","いつも","ぜんぜん","あまり"]}],"src":["https://en.wiktionary.org/wiki/%E6%99%82%E3%80%85"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_127","t":"ほとんど～","ko":"거의, 대부분","cat":"부사·접속사","conn":[{"w":"ほとんど + 동사 (긍정)","f":"ほとんど食べました"},{"w":"ほとんど + 동사 부정","f":"ほとんど食べません"},{"w":"ほとんど + の + 명사","f":"ほとんどの人"},{"w":"명사 + が + ほとんど + ない","f":"お金がほとんどない"}],"rule":["동사 앞에 ほとんど를 두면 '거의 다'라는 뜻이 된다(ほとんど食べました).","같은 동사의 ました를 ません으로 바꾸면 '거의 ~않다'로 뜻이 뒤집힌다(ほとんど食べません).","명사를 꾸밀 때는 の를 넣어 ほとんどの + 명사로 쓴다(ほとんどの人)."],"why":"","nu":"회화·문장 모두 쓴다. 보통 히라가나로 쓴다. 부정과 함께 쓰면 '거의 없다, 거의 안 한다'처럼 아주 적은 양을 나타낸다. めったに～ない와 비슷하지만 めったに는 긍정문에 쓰지 않고, ほとんど는 긍정·부정 모두 쓴다. 명사 앞에서 の를 빼고 ほとんど人라고 하는 실수에 주의.","cmp":[{"g":"だいたい","d":"ほとんどの人 = だいたいの人처럼 겹치는 부분이 있지만, ほとんどない(거의 없다)를 だいたいない로 바꿀 수는 없다."},{"g":"めったに～ない","d":"'좀처럼 ~않다'. 부정문 전용이고, ほとんど～ない보다 횟수가 더 적은 느낌."}],"ex":[{"jp":"宿題[しゅくだい]はほとんど終[お]わりました。","ko":"숙제는 거의 끝났습니다."},{"jp":"わたしはテレビをほとんど見[み]ません。","ko":"저는 텔레비전을 거의 안 봅니다."},{"jp":"クラスのほとんどの人[ひと]が来[き]ました。","ko":"반의 거의 모든 사람이 왔습니다."}],"dr":[{"t":"make","q":"食べました → '거의 다 먹었어요'","a":"ほとんど食べました","hint":"동사 앞에 ほとんど."},{"t":"make","q":"ほとんど見ます → '거의 안 봐요'","a":"ほとんど見ません","hint":"ます → ません."},{"t":"fill","q":"（　）の学生[がくせい]は自転車[じてんしゃ]で来[き]ます。","a":"ほとんど","opts":["ほとんど","まだ","もう","なんでも"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BB%E3%81%A8%E3%82%93%E3%81%A9"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_128","t":"まあまあ","ko":"그럭저럭, 그런대로","cat":"부사·접속사","conn":[{"w":"명사 + は + まあまあです","f":"味はまあまあです"},{"w":"まあまあ + い형용사","f":"まあまあおいしいです"},{"w":"まあまあ + の + 명사","f":"まあまあの点数"},{"w":"단독 대답","f":"A：どうですか。B：まあまあです。"}],"rule":["まあまあ는 활용하지 않는다. 문장 끝에 둘 때는 뒤에 です를 붙인다(味はまあまあです).","형용사 앞에 두면 정도를 '그런대로'로 낮춘다(まあまあおいしい).","명사를 꾸밀 때는 の를 넣는다(まあまあの点数)."],"why":"","nu":"회화체. 아주 좋지는 않지만 일단 만족할 만한 정도를 말한다. 만든 사람 앞에서 그 음식을 まあまあ라고 하면 칭찬으로 들리지 않을 수 있다. 화난 사람을 '자, 자' 하고 달래는 감탄사 まあまあ(まあまあ、落ち着いて)도 있다.","cmp":[{"g":"まずまず","d":"사전에서 같은 뜻으로 풀이하는 비슷한 말로, 둘 다 '그런대로 괜찮다'."}],"ex":[{"jp":"このラーメンの味[あじ]はまあまあです。","ko":"이 라면 맛은 그럭저럭이에요."},{"jp":"テストはまあまあできました。","ko":"시험은 그런대로 봤어요."},{"jp":"今日[きょう]の天気[てんき]はまあまあいいですね。","ko":"오늘 날씨는 그런대로 좋네요."}],"dr":[{"t":"make","q":"おいしいです → '그럭저럭 맛있어요'","a":"まあまあおいしいです","hint":"형용사 앞에 まあまあ."},{"t":"make","q":"点数 → '그럭저럭인 점수'","a":"まあまあの点数","hint":"명사 앞에서는 の를 넣는다."},{"t":"fill","q":"A：日本語[にほんご]のテストはどうでしたか。B：（　）でした。","a":"まあまあ","opts":["まあまあ","ほとんど","もう","なんでも"]}],"src":["https://www.weblio.jp/content/%E3%81%BE%E3%81%82%E3%81%BE%E3%81%82"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_129","t":"まだ～","ko":"아직 (~하고 있다)","cat":"부사·접속사","conn":[{"w":"まだ + 동사 て형 + いる","f":"まだ降っています"},{"w":"まだ + い형용사","f":"まだ暑いです"},{"w":"まだ + 명사 + です","f":"まだ学生です"},{"w":"まだ + 동사 て형 + いない (부정)","f":"まだ来ていません"}],"rule":["상태가 계속됨을 말할 때는 동사를 て형 + いる로 만들고 그 앞에 まだ를 둔다(まだ降っています).","형용사·명사 문장은 형태를 바꾸지 않고 앞에 まだ만 둔다(まだ暑いです, まだ学生です).","부정 ていない/ていません과 함께 쓰면 '아직 ~하지 않았다'가 된다."],"why":"","nu":"회화·문장 모두 쓴다. 바뀔 줄 알았던 상태가 아직 계속된다는 느낌이다. 반대말은 もう(이미 바뀜). もう食べましたか에 짧게 답할 때는 いいえ、まだです. 한자 未だ로 쓰는 일은 드물다.","cmp":[{"g":"もう","d":"변화가 이미 일어났음. まだ는 변화가 아직 일어나지 않았거나 상태가 계속됨."}],"ex":[{"jp":"まだ雨[あめ]が降[ふ]っています。","ko":"아직 비가 오고 있습니다."},{"jp":"九月[くがつ]ですが、まだ暑[あつ]いです。","ko":"9월인데 아직 덥습니다."},{"jp":"弟[おとうと]はまだ学生[がくせい]です。","ko":"남동생은 아직 학생입니다."}],"dr":[{"t":"make","q":"雨が降っています → '아직 비가 오고 있어요'","a":"まだ雨が降っています","hint":"문장 앞에 まだ."},{"t":"make","q":"足が痛いです → '아직 발이 아파요'","a":"まだ足が痛いです","hint":"い형용사는 그대로 두고 まだ만 더한다."},{"t":"fill","q":"もう昼[ひる]の12時[じゅうにじ]ですが、兄[あに]は（　）寝[ね]ています。","a":"まだ","opts":["まだ","もう","ほとんど","なんでも"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A0"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_132","t":"もう～","ko":"벌써, 이미 / 이제 더 이상","cat":"부사·접속사","conn":[{"w":"もう + 동사 과거","f":"もう食べました"},{"w":"もう + 동사 부정","f":"もう食べません"},{"w":"もう + 수량","f":"もう一つください"},{"w":"もうすぐ + 명사/동사","f":"もうすぐ夏休みです"}],"rule":["동사의 ます를 ました로 바꿔 과거로 만든다(食べます → 食べました).","그 앞에 もう를 두면 '벌써/이미 ~했다'가 된다(もう食べました).","동사 부정형과 함께 쓰면 '이제 더 이상 ~않다'가 된다(もう食べません).","수량 앞에서는 '더'(もう一つ), すぐ와 합친 もうすぐ는 '곧'이라는 뜻이다."],"why":"","nu":"일상 회화에 어울리고 감정이 실린다. 같은 '이미'라도 すでに는 객관적이어서 문장이나 격식 있는 자리에 쓴다. もう～ましたか에 아직이라면 いいえ、まだです로 답한다. もう 하나만으로 짜증이나 불만(もう!)을 나타내기도 한다.","cmp":[{"g":"すでに","d":"뜻은 '이미'로 같지만 문장체·격식체. もう는 회화체이고 감정 표현으로도 쓴다."},{"g":"まだ","d":"반대말. 변화가 아직 일어나지 않았거나 상태가 계속됨."}],"ex":[{"jp":"もう昼[ひる]ご飯[はん]を食[た]べました。","ko":"벌써 점심을 먹었습니다."},{"jp":"もうたばこは吸[す]いません。","ko":"이제 담배는 안 피웁니다."},{"jp":"もう一[ひと]つください。","ko":"하나 더 주세요."}],"dr":[{"t":"make","q":"食べます → '벌써 먹었어요'","a":"もう食べました","hint":"ます → ました, 앞에 もう."},{"t":"make","q":"飲みます → '이제 더 이상 안 마셔요'","a":"もう飲みません","hint":"もう + ます를 ません으로."},{"t":"fill","q":"A：（　）宿題[しゅくだい]をしましたか。B：はい、しました。","a":"もう","opts":["もう","まだ","ほとんど","まあまあ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%81%86","https://bagustris.github.io/minna-no-nihongo/mnn_sho_1/minna_no_nihongo_sho_1_07.html"],"vf":1,"u":13,"g":1,"gp":"gg_N5_09"},{"id":"g5_133","t":"もうすぐ～","ko":"곧, 머지않아, 이제 곧","cat":"부사·접속사","conn":[{"w":"もうすぐ + 동사 (비과거형)","f":"もうすぐ来ます"},{"w":"もうすぐ + 명사 + です/だ","f":"もうすぐ春です"},{"w":"もうすぐ + 명사 + になる","f":"もうすぐ十時になります"},{"w":"명사 + は + もうすぐだ (술어로)","f":"誕生日はもうすぐです"}],"rule":["もうすぐ는 활용하지 않는 부사이므로 글자가 바뀌지 않는다.","문장(電車が来ます) 앞에 もうすぐ를 그대로 붙이면 '곧 ~한다'가 된다.","명사 문장에서는 もうすぐ + 명사 + です(もうすぐ春です)로, 술어 자리에서는 명사は + もうすぐです로 쓴다."],"why":"부사 もう에는 '머지않아, 이제 곧(まもなく)'이라는 뜻이 있고, 여기에 '곧바로'의 すぐ가 더해져 '이제 곧'이라는 가까운 미래를 나타낸다.","nu":"회화·문장 모두 쓰는 일상 표현이다. 앞으로 일어날 일에 쓰므로 뒤의 동사는 보통 비과거형(来ます, 終わる)이다. 과거형과 함께 '곧 ~했다'로 쓰지 않는다. もう만 쓰면 '벌써(이미)'의 뜻과 헷갈릴 수 있어, 가까운 미래를 분명히 할 때 もうすぐ를 쓴다.","cmp":[{"g":"すぐ","d":"'즉시, 바로'. 지금부터 시간을 두지 않고 하는 행동(すぐ行きます=바로 갈게요). もうすぐ는 '얼마 안 있으면 그때가 온다'는 시점의 접근."},{"g":"もう","d":"'벌써/이미'(もう食べました)가 기본. もうすぐ는 아직 일어나지 않은 가까운 미래."}],"ex":[{"jp":"もうすぐ電車[でんしゃ]が来[き]ます。","ko":"곧 전철이 와요."},{"jp":"もうすぐ夏休[なつやす]みです。","ko":"곧 여름방학이에요."},{"jp":"母[はは]の誕生日[たんじょうび]はもうすぐです。","ko":"어머니 생신이 얼마 안 남았어요."}],"dr":[{"t":"make","q":"春です → '곧 봄이에요'","a":"もうすぐ春です","hint":"문장 앞에 もうすぐ를 그대로 붙인다."},{"t":"make","q":"試験が終わります → '곧 시험이 끝나요'","a":"もうすぐ試験が終わります","hint":"동사는 비과거형 그대로 두고 앞에 もうすぐ."},{"t":"fill","q":"（　）バスが来[き]ますから、ここで待[ま]ちましょう。","a":"もうすぐ","opts":["もうすぐ","さっき","まだ","ずっと"]}],"src":["https://www.weblio.jp/content/もう","https://www.weblio.jp/content/もうすぐ","https://www.vnjpclub.com/en/n5-grammar/mousugu.html"],"vf":1,"u":14,"g":1,"gp":"gg_N5_09"},{"id":"g5_135","t":"よく～","ko":"자주; 잘","cat":"부사·접속사","conn":[{"w":"よく + 동사 (빈도: 자주)","f":"よく行きます"},{"w":"よく + 동사 (정도: 잘, 충분히)","f":"よく寝ました"},{"w":"よく + 동사 과거 습관","f":"よく遊んでいました"},{"w":"よく + 가능/상태 동사","f":"よく分かります"}],"rule":["형용사 よい(좋다)의 어미 い를 く로 바꾸면 부사 よく가 된다.","よく를 동사 앞에 두면 '자주'(よく行きます) 또는 '잘·충분히'(よく寝ました)의 뜻이 된다.","よく 자체는 더 이상 활용하지 않고, 시제·정중도는 뒤의 동사가 나타낸다."],"why":"よく는 형용사 よい의 연용형(い→く)에서 나온 부사다. 그래서 '좋게 → 잘, 충분히'의 뜻과 함께 같은 일을 '자주' 한다는 뜻도 갖게 되었다.","nu":"회화·문장 모두 쓴다. 빈도의 よく는 '자주'(よく図書館に行きます), 정도의 よく는 '잘/충분히'(よく分かりました)로, 문맥으로 구별한다. '잘한다(능숙하다)'는 よく보다 上手に・上手だ가 자연스럽다(テニスが上手です). よく来たね처럼 감탄·칭찬, よくそんなことが言えるね처럼 비꼼으로도 쓴다. いい에는 いく 형태가 없으므로 부사는 항상 よく다.","cmp":[{"g":"ときどき","d":"'가끔'. よく보다 빈도가 낮다."},{"g":"上手に","d":"'능숙하게'(기술이 좋음). よく는 '자주/충분히' 쪽이 기본."}],"ex":[{"jp":"週末[しゅうまつ]はよく図書館[としょかん]に行[い]きます。","ko":"주말에는 자주 도서관에 가요."},{"jp":"昨日[きのう]はよく寝[ね]ました。","ko":"어제는 푹 잤어요."},{"jp":"子[こ]どものころ、兄[あに]とよく遊[あそ]びました。","ko":"어릴 때 형이랑 자주 놀았어요."}],"dr":[{"t":"make","q":"よい → 부사형","a":"よく","hint":"어미 い를 く로 바꾼다."},{"t":"make","q":"映画を見ます → '영화를 자주 봐요'","a":"よく映画を見ます","hint":"문장 앞(또는 동사 앞)에 よく를 둔다."},{"t":"fill","q":"コーヒーが好[す]きなので、（　）この店[みせ]で飲[の]みます。","a":"よく","opts":["よく","あまり","全然","決して"]}],"src":["https://www.weblio.jp/content/%E8%89%AF%E3%81%8F"],"vf":1,"u":14,"g":1,"gp":"gg_N5_09"},{"id":"g5_065","t":"～はいかがですか","ko":"~은 어떠세요? (권유·안부)","cat":"경어","conn":[{"w":"명사 + は","f":"お茶 + は + いかがですか"},{"w":"동사 て형 + は","f":"休む → 休んで + は + いかがですか"},{"w":"단독(안부·상태)","f":"お体はいかがですか"}],"rule":["'명사 + は + いかがですか' 틀에 권할 물건을 넣는다(お茶はいかがですか).","보통의 どうですか에서 どう를 정중한 いかが로 바꾼 형태다(どうですか → いかがですか).","행동을 권할 때는 동사 て형 + は + いかがですか를 쓴다(休んではいかがですか)."],"why":"いかが(如何)는 '어떻게, 어떠한'을 뜻하는 부사로 どう의 격식 있는 말이다. 사전에 따르면 いかに에 조사 か가 붙은 いかにか가 소리가 변해 생긴 말이다.","nu":"상점·접객이나 손윗사람에게 쓰는 정중한 표현. 음식·물건을 권할 때(お一ついかがですか), 상대의 상태·의견을 물을 때(ご気分はいかがですか) 쓴다. 친구에게는 どう?가 자연스럽다. 권유에 대한 대답은 はい、いただきます / いいえ、けっこうです 등.","cmp":[{"g":"どうですか","d":"뜻은 같지만 どうですか는 보통의 정중체, いかがですか는 더 공손한 말."},{"g":"～ませんか","d":"ませんか는 '~하지 않을래요?'라는 권유이고, いかがですか는 무언가를 내밀며 '어떠세요?'라고 의향을 묻는다."}],"ex":[{"jp":"お茶[ちゃ]はいかがですか。","ko":"차 한 잔 어떠세요?"},{"jp":"このケーキ、お一[ひと]ついかがですか。","ko":"이 케이크 하나 드셔 보시겠어요?"},{"jp":"少[すこ]し休[やす]んではいかがですか。","ko":"좀 쉬시는 게 어떠세요?"}],"dr":[{"t":"make","q":"コーヒーはどうですか → 정중하게","a":"コーヒーはいかがですか","hint":"どう를 いかが로 바꾼다."},{"t":"make","q":"座る → ～てはいかがですか","a":"座ってはいかがですか","hint":"座る는 1그룹: る를 って로 바꾼 て형 + は + いかがですか."},{"t":"fill","q":"店員[てんいん]：こちらのシャツは（　）ですか。","a":"いかが","opts":["いかが","いくら","いくつ","いつ"]}],"src":["https://kotobank.jp/word/如何","https://news.mynavi.jp/article/20230209-2513813/"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_111","t":"どなた","ko":"어느 분, 누구 (だれ의 정중형)","cat":"경어","conn":[{"w":"どなた + ですか","f":"あの方はどなたですか"},{"w":"どなた + が (주어)","f":"どなたが来ますか"},{"w":"どなた + の + 명사","f":"どなたのかさですか"},{"w":"どなた + さま (더 정중)","f":"どなたさまですか"}],"rule":["사람을 묻는 だれ를 정중한 どなた로 바꾼다(だれ → どなた).","가리키는 사람도 정중하게 あの人 대신 あの方를 쓰는 경우가 많다(あの方はどなたですか).","조사 붙이는 법은 だれ와 같다(どなたが, どなたに, どなたの).","더 공손하게는 どなたさま라고 한다."],"why":"どなた는 だれ의 존경 표현으로, 사전에 따르면 옛날에는 방향(어느 쪽)을 가리키는 말이기도 했다.","nu":"손님·윗사람·모르는 사람에 대해 물을 때 쓰는 정중한 말. 가게·회사 전화 응대에서 どちらさまですか도 많이 쓴다. 친구끼리 だれ 대신 쓰면 지나치게 딱딱하다. 대답에서 자기 쪽 사람을 말할 때 どなた를 쓰지 않는다.","cmp":[{"g":"だれ","d":"뜻은 같지만 보통의 말. 친구·가족 사이에서 쓴다."}],"ex":[{"jp":"失礼[しつれい]ですが、どなたですか。","ko":"실례지만, 누구신가요?"},{"jp":"これはどなたのかばんですか。","ko":"이것은 어느 분의 가방입니까?"},{"jp":"きのう、どなたが来[き]ましたか。","ko":"어제 어느 분이 오셨습니까?"}],"dr":[{"t":"make","q":"あの人はだれですか → 정중하게","a":"あの方はどなたですか","hint":"あの人 → あの方, だれ → どなた."},{"t":"make","q":"だれのかさですか → 정중하게","a":"どなたのかさですか","hint":"だれ만 どなた로 바꾸고 の는 그대로."},{"t":"fill","q":"すみません、（　）が田中[たなか]さんですか。","a":"どなた","opts":["どなた","どちら","どれ","どこ"]}],"src":["https://kotobank.jp/word/何方"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_066","t":"いくつ","ko":"몇 개, 몇 살","cat":"기타","conn":[{"w":"명사 + は + いくつ","f":"りんごはいくつありますか"},{"w":"나이(정중)","f":"お子さんはおいくつですか"},{"w":"いくつ + か","f":"いくつか(몇 개인가, 몇몇)"},{"w":"いくつ + でも","f":"いくつでも(몇 개든지)"}],"rule":["'명사 + は + いくつ + ありますか' 틀로 개수를 묻는다.","대답은 いくつ 자리에 ひとつ·ふたつ·みっつ 같은 수를 넣고 ありますか의 か를 뗀다(みっつあります).","나이를 물을 때는 いくつですか, 정중하게는 おいくつですか라고 한다."],"why":"","nu":"조수사 없이 개수를 묻는 기본 의문사. 사람 수는 何人(なんにん), 납작한 것은 何枚처럼 조수사가 정해진 것은 何 + 조수사가 자연스럽다. 가격은 いくら로 묻는다(いくつ와 혼동 주의). いくつか는 '몇 개'라는 불특정 수(긍정문).","cmp":[{"g":"いくら","d":"いくら는 값·양(얼마), いくつ는 개수·나이(몇 개, 몇 살)."},{"g":"何個","d":"何個(なんこ)도 개수를 묻지만 조수사 個를 쓴 말이고, いくつ는 ひとつ·ふたつ 계열로 대답한다."}],"ex":[{"jp":"りんごはいくつありますか。","ko":"사과는 몇 개 있어요?"},{"jp":"お子[こ]さんはおいくつですか。","ko":"자제분은 몇 살이에요?"},{"jp":"卵[たまご]をいくつ買[か]いましたか。","ko":"달걀을 몇 개 샀어요?"}],"dr":[{"t":"make","q":"みかんがみっつあります → いくつ로 질문","a":"みかんはいくつありますか","hint":"수 자리에 いくつ, 끝에 か."},{"t":"make","q":"何歳ですか → 정중하게 (いくつ)","a":"おいくつですか","hint":"いくつ 앞에 お를 붙인다."},{"t":"fill","q":"A：箱[はこ]の中[なか]にボールが（　）ありますか。 B：よっつあります。","a":"いくつ","opts":["いくつ","いくら","いつ","どこ"]}],"src":["https://kotobank.jp/jeword/%E5%B9%BE%E3%81%A4"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_079","t":"こちら","ko":"이쪽, 이분, 이것(정중)","cat":"기타","conn":[{"w":"단독(주어)","f":"こちら + は + 田中さん + です"},{"w":"명사 수식","f":"こちら + の + 部屋"},{"w":"방향","f":"こちら + へ + どうぞ"}],"rule":["こちら는 말하는 사람 가까이에 있는 방향·장소·사람·물건을 정중하게 가리킨다.","사람을 소개할 때는 'こちら + は + 이름 + です'로 쓴다.","명사를 꾸밀 때는 の를 넣는다(こちらの部屋).","반말 형태는 こっち이다."],"why":"こそあど 체계의 こ(말하는 사람 쪽) 계열 말로, 본래 방향을 가리키는 말이다. 방향 말을 써서 사람이나 물건을 간접적으로 가리키므로 これ·この人보다 정중하게 들린다.","nu":"정중한 말투. 사람을 소개할 때 'この人は'라고 하면 실례가 될 수 있으므로 'こちらは'를 쓴다. 가게·호텔에서 '여기로 오세요'는 'こちらへどうぞ'. 전화나 대화에서 '저희 쪽'이라는 뜻으로도 쓴다(こちらこそ: 저야말로).","cmp":[{"g":"これ／ここ","d":"これ는 물건, ここ는 장소만 가리키는 보통 말. こちら는 방향·장소·사람·물건을 모두 정중하게 가리킨다."},{"g":"そちら","d":"そちら는 듣는 사람 쪽(그쪽)을 가리킨다."}],"ex":[{"jp":"こちらは田中[たなか]さんです。","ko":"이분은 다나카 씨입니다."},{"jp":"こちらの部屋[へや]は広[ひろ]いですね。","ko":"이쪽 방은 넓네요."},{"jp":"お席[せき]はこちらです。どうぞ。","ko":"자리는 이쪽입니다. 앉으세요."}],"dr":[{"t":"make","q":"この人は山田さんです → 정중하게","a":"こちらは山田さんです","hint":"この人 대신 こちら를 쓴다."},{"t":"make","q":"ここへどうぞ → 정중하게","a":"こちらへどうぞ","hint":"ここ 대신 방향을 나타내는 こちら."},{"t":"fill","q":"（소개하며）（　）は私[わたし]の母[はは]です。","a":"こちら","opts":["こちら","そこ","あそこ","どれ"]}],"src":["https://tofugu.com/japanese-grammar/kochira-sochira-achira-dochira","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei16_7.pdf"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_084","t":"そちら","ko":"그쪽, 그분, 그것(정중)","cat":"기타","conn":[{"w":"단독(주어)","f":"そちら + は + いかがですか"},{"w":"명사 수식","f":"そちら + の + 本"},{"w":"방향","f":"そちら + へ + 行きます"}],"rule":["そちら는 듣는 사람 가까이에 있는 방향·장소·물건이나 듣는 사람(쪽)을 정중하게 가리킨다.","명사를 꾸밀 때는 の를 넣는다(そちらの本).","반말 형태는 そっち이다."],"why":"こそあど 체계의 そ(듣는 사람 쪽) 계열 방향 말이다. 방향을 가리키는 말로 사람·물건을 간접적으로 가리키므로 それ·その人보다 정중하다.","nu":"정중한 말투. 가게에서 점원 쪽에 있는 물건을 가리킬 때(そちらの本をください), 상대방이나 상대 회사를 정중하게 부를 때(そちらは何時までですか) 쓴다. 한국어 '그쪽'을 사람에게 쓰면 무례할 수 있지만 일본어 そちら는 정중한 표현이다.","cmp":[{"g":"それ／そこ","d":"それ는 물건, そこ는 장소만 가리키는 보통 말. そちら는 방향·사람까지 정중하게 가리킨다."},{"g":"こちら","d":"こちら는 말하는 사람 쪽(이쪽), そちら는 듣는 사람 쪽(그쪽)."}],"ex":[{"jp":"すみません、そちらの本[ほん]を見[み]せてください。","ko":"죄송한데요, 그쪽 책을 보여 주세요."},{"jp":"そちらの天気[てんき]はどうですか。","ko":"그쪽 날씨는 어때요?"},{"jp":"今[いま]からそちらへ行[い]きます。","ko":"지금부터 그쪽으로 가겠습니다."}],"dr":[{"t":"make","q":"その傘をください → 정중하게","a":"そちらの傘をください","hint":"その 대신 そちらの."},{"t":"make","q":"そこへ行きます → 정중하게","a":"そちらへ行きます","hint":"そこ 대신 방향 말 そちら."},{"t":"fill","q":"（전화로）（　）は山田[やまだ]さんのお宅[たく]ですか。","a":"そちら","opts":["そちら","これ","ここ","どれ"]}],"src":["https://tofugu.com/japanese-grammar/kochira-sochira-achira-dochira","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei16_7.pdf"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_090","t":"だれ","ko":"누구","cat":"기타","conn":[{"w":"だれ + が (주어)","f":"だれが来ましたか"},{"w":"だれ + を / に / と","f":"だれを待っていますか / だれと行きますか"},{"w":"だれ + の (소유)","f":"これはだれの本ですか"},{"w":"명사 + は + だれですか","f":"あの人はだれですか"}],"rule":["대답이 될 사람 이름 자리에 だれ를 그대로 넣는다(田中さんが → だれが).","뒤의 조사는 문장 속 역할대로 붙인다(が, を, に, と, の).","문장 끝에 か를 붙여 질문으로 만든다(だれが食べましたか).","'누가 ~했나'처럼 주어를 물을 때는 だれは가 아니라 だれが를 쓴다."],"why":"","nu":"회화체 기본 의문사. 정중하게는 どなた, 더 공손하게는 どちらさま를 쓴다(초면·윗사람에게 だれですか는 무례하게 들릴 수 있다). 한국인이 자주 하는 실수: 의문사 주어에 は를 붙이는 것(×だれは来ましたか → ○だれが来ましたか). 대답도 が로 받는다(田中さんが来ました).","cmp":[{"g":"どなた","d":"どなた는 だれ의 정중한 말. 의미는 같고 상대를 높일 때 쓴다."},{"g":"だれか","d":"だれ는 '누구(를 묻는 말)', だれか는 '누군가'로 정해지지 않은 사람을 가리킨다."}],"ex":[{"jp":"だれがこのケーキを食[た]べましたか。","ko":"누가 이 케이크를 먹었어요?"},{"jp":"あの人[ひと]はだれですか。","ko":"저 사람은 누구예요?"},{"jp":"これはだれのかばんですか。","ko":"이건 누구 가방이에요?"}],"dr":[{"t":"make","q":"山田さんが来ました。 → 사람을 묻는 질문","a":"だれが来ましたか","hint":"사람 이름 자리에 だれ를 넣고, 조사 が는 그대로, 끝에 か."},{"t":"make","q":"これは先生の傘です。 → 주인을 묻는 질문","a":"これはだれの傘ですか","hint":"先生 자리에 だれ를 넣고 の는 그대로 둔다."},{"t":"fill","q":"A：（　）が窓[まど]を開[あ]けましたか。　B：田中[たなか]さんです。","a":"だれ","opts":["だれ","どこ","いつ","なに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A0%E3%82%8C"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_091","t":"だれか","ko":"누군가","cat":"기타","conn":[{"w":"だれか + が (주어)","f":"だれかが来ました"},{"w":"だれか + に / と","f":"だれかに聞きます / だれかと行きます"},{"w":"だれか + 동사 (부름·부탁)","f":"だれか、手伝ってください"},{"w":"だれかを (목적어)","f":"だれかを呼びましょう"}],"rule":["의문사 だれ 바로 뒤에 か를 붙인다(だれ → だれか).","그 다음에 필요한 조사를 붙인다. か가 먼저, 조사는 그 뒤다(だれかが, だれかに).","주어·목적어의 が・を는 회화에서 생략되기도 한다(だれか来ました).","문장은 긍정문·질문문으로 쓰며 '정해지지 않은 어떤 사람'을 가리킨다."],"why":"의문사 だれ(누구)에 불확실함을 나타내는 か가 붙어 '누구인지 모르는 어떤 사람'이 되었다. 같은 방식으로 なにか(무언가), どこか(어딘가), いつか(언젠가)가 만들어진다.","nu":"회화·문장 모두 쓴다. だれかが来ましたか는 '누군가 왔어요?'(예/아니요 질문)이고, だれが来ましたか는 '누가 왔어요?'(사람을 묻는 질문)로 뜻이 다르다. 대답도 각각 はい/いいえ와 사람 이름으로 달라진다. 조사 순서를 바꿔 だれにか라고 하지 않는다.","cmp":[{"g":"だれ","d":"だれ는 '누구'를 묻는 의문사. だれか는 묻지 않고 '누군가'라는 막연한 사람을 가리킨다."},{"g":"だれも","d":"だれも는 부정문에서 '아무도 (~않다)'. だれか는 긍정·질문에서 '누군가'."}],"ex":[{"jp":"だれかがドアをたたいています。","ko":"누군가가 문을 두드리고 있습니다."},{"jp":"すみません、だれか手伝[てつだ]ってください。","ko":"저기요, 누가 좀 도와주세요."},{"jp":"教室[きょうしつ]にだれかいますか。","ko":"교실에 누군가 있어요?"}],"dr":[{"t":"make","q":"だれ → '누군가가' (주어)","a":"だれかが","hint":"だれ에 か를 먼저 붙이고 그 뒤에 が."},{"t":"make","q":"だれ → '누군가에게'","a":"だれかに","hint":"か 다음에 조사 に를 붙인다."},{"t":"fill","q":"（　）がわたしの名前[なまえ]を呼[よ]びました。","a":"だれか","opts":["だれか","だれも","だれでも","どなた"]}],"src":["https://bunpro.jp/ja/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82","https://bunpro.jp/ja/grammar_points/714"],"vf":1,"u":14,"g":1,"gp":"gg_N5_10"},{"id":"g5_101","t":"どこ","ko":"어디","cat":"기타","conn":[{"w":"명사 + は + どこですか","f":"駅[えき]はどこですか"},{"w":"どこ + で + 동사 (동작 장소)","f":"どこで買[か]いましたか"},{"w":"どこ + に + 동사 (존재·도착 장소)","f":"どこに住[す]んでいますか"},{"w":"どこ + へ / に + 이동 동사","f":"どこへ行[い]きますか"},{"w":"どこ + の + 명사","f":"どこの国[くに]の人[ひと]ですか"}],"rule":["ここ・そこ・あそこ에 대응하는 장소 의문사가 どこ다.","장소를 물을 때는 '명사 + は + どこ + ですか' 틀에 단어를 넣는다(駅はどこですか).","동사와 쓸 때는 どこ 뒤에 조사를 붙인다. 동작 장소는 で, 존재·도착점은 に, 방향은 へ.","どこ + の + 명사는 '어느 곳의 ~'(소속·출신)를 묻는다."],"why":"こ・そ・あ・ど 체계의 ど 계열(의문) 장소어이다. ここ(여기)·そこ(거기)·あそこ(저기)와 짝을 이룬다.","nu":"회화·문장 모두 쓴다. 더 정중하게 물을 때는 どちら를 쓴다(お国はどちらですか). 한국인은 '어디에서 샀어요'의 '에서'를 に로 잘못 쓰기 쉬운데, 동작이 일어나는 장소는 で다. どこは처럼 의문사에 は를 붙이지 않고, 주어일 때는 どこが를 쓴다.","cmp":[{"g":"どちら","d":"どちら는 どこ의 정중한 말이며, 두 개 중 '어느 쪽'을 고를 때도 쓴다."}],"ex":[{"jp":"すみません、駅[えき]はどこですか。","ko":"실례합니다, 역은 어디입니까?"},{"jp":"そのかばん、どこで買[か]いましたか。","ko":"그 가방 어디에서 샀어요?"},{"jp":"今[いま]、どこに住[す]んでいますか。","ko":"지금 어디에 살고 있습니까?"}],"dr":[{"t":"make","q":"トイレ → 장소를 묻는 문장","a":"トイレはどこですか","hint":"명사 + は + どこですか"},{"t":"make","q":"昼[ひる]ごはんを食[た]べましたか → 장소를 묻기","a":"どこで昼ごはんを食べましたか","hint":"동작 장소는 どこ + で"},{"t":"fill","q":"A：トイレは（　）ですか。 B：あそこです。","a":"どこ","opts":["どこ","だれ","いつ","なに"]}],"src":["https://www.tofugu.com/japanese-grammar/koko-soko-asoko-doko","https://jplang.tufs.ac.jp/en/bu/9/9-8.html"],"vf":1,"u":15,"g":1,"gp":"gg_N5_10"},{"id":"g5_102","t":"どこか","ko":"어딘가","cat":"기타","conn":[{"w":"どこか + へ / に (방향·도착)","f":"どこかへ行[い]きたいです"},{"w":"どこか + で (장소)","f":"どこかで会[あ]いましたか"},{"w":"どこか + 명사 수식어 (どこか + 형용사 + 명사)","f":"どこか静[しず]かな所[ところ]"},{"w":"どこか + 질문 (예/아니요)","f":"どこかへ出[で]かけましたか"}],"rule":["의문사 どこ 바로 뒤에 か를 붙여 どこか를 만든다(どこ → どこか).","조사는 か 뒤에 붙인다: どこかへ, どこかで, どこかに. どこへか처럼 순서를 바꾸지 않는다.","へ・に는 회화에서 생략되기도 한다(どこか行きたい).","긍정문·예/아니요 질문에 쓰며 '정해지지 않은 어떤 곳'을 가리킨다."],"why":"의문사 どこ(어디)에 불확실함을 나타내는 か가 붙어 '어딘지 모르는 어떤 곳'이 되었다. だれか·なにか·いつか도 같은 방식이다.","nu":"회화·문장 모두 쓴다. どこかへ行きましたか(어딘가 갔어요? → 예/아니요로 대답)와 どこへ行きましたか(어디 갔어요? → 장소로 대답)는 질문 종류가 다르다. 부정 대답은 どこへも行きませんでした처럼 どこ + 조사 + も를 쓴다.","cmp":[{"g":"どこ","d":"どこ는 장소를 묻는 의문사, どこか는 묻지 않고 막연한 어떤 곳을 가리킨다."},{"g":"どこにも／どこへも","d":"부정문에서 '아무 데도 ~않다'. どこか는 긍정·질문에 쓴다."}],"ex":[{"jp":"夏休[なつやす]みにどこかへ行[い]きたいです。","ko":"여름방학에 어딘가 가고 싶습니다."},{"jp":"どこかで財布[さいふ]をなくしました。","ko":"어딘가에서 지갑을 잃어버렸습니다."},{"jp":"どこか静[しず]かな所[ところ]で話[はな]しましょう。","ko":"어딘가 조용한 곳에서 이야기합시다."}],"dr":[{"t":"make","q":"どこ → '어딘가'","a":"どこか","hint":"의문사 뒤에 か"},{"t":"make","q":"どこか + で → 会いましたか (질문 완성)","a":"どこかで会いましたか","hint":"조사는 か 뒤에 붙인다"},{"t":"fill","q":"A：日曜日[にちようび]、（　）へ行[い]きましたか。 B：はい、海[うみ]へ行[い]きました。","a":"どこか","opts":["どこか","どこも","どこでも","どこ"]}],"src":["https://jplang.tufs.ac.jp/en/bu/9/9-8.html","https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/doko-kani-doko-nimo-genki-i-chapter-10/","https://bunpro.jp/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":15,"g":1,"gp":"gg_N5_10"},{"id":"g5_109","t":"どこも～ません","ko":"어디도 ~하지 않습니다, 아무 데도 ~않습니다","cat":"기타","conn":[{"w":"どこも (주어·목적어, が・を 대신)","f":"どこも開いていません"},{"w":"どこ + に + も","f":"どこにもありません"},{"w":"どこ + へ + も","f":"どこへも行きません"},{"w":"どこ + から + も","f":"どこからも連絡がありません"}],"rule":["의문사 どこ 뒤에 も를 붙인다(どこ → どこも).","주어·목적어 자리의 が・を는 쓰지 않고 も로 바꾼다(どこが → どこも).","に・へ 같은 다른 조사는 남기고 그 뒤에 も를 붙인다(どこにも, どこへも).","술어는 부정형 ～ません / ～ない로 끝낸다(開いていません)."],"why":"의문사에 '~도'의 も가 붙어 '어느 곳이라도'라는 전체를 가리키게 되고, 부정과 함께 쓰면 '어느 곳도 ~않다'가 된다. 같은 방식으로 だれも, なにも가 있다.","nu":"회화·문장 모두 쓴다. 존재·이동을 말할 때는 조사를 넣어 どこにもいません, どこへも行きません처럼 쓰는 것이 자연스럽다. どこもありません처럼 に를 빼는 실수가 많다. 긍정문의 どこも는 '어디나 다'(どこも人がいっぱいです)라는 뜻이 되고, '어디든 상관없다'는 どこでも를 쓴다.","cmp":[{"g":"どこか","d":"どこか는 긍정·질문문에서 '어딘가'. どこも는 부정문에서 '어디도 (~않다)'."},{"g":"どこでも","d":"どこでも는 긍정 술어와 함께 '어디든지'. どこも+부정은 '어디도 아니다'."}],"ex":[{"jp":"日曜日[にちようび]は、店[みせ]はどこも開[あ]いていません。","ko":"일요일에는 가게가 어디도 열려 있지 않습니다."},{"jp":"かぎはどこにもありません。","ko":"열쇠는 어디에도 없습니다."},{"jp":"きのうはどこへも行[い]きませんでした。","ko":"어제는 아무 데도 가지 않았습니다."}],"dr":[{"t":"make","q":"どこ + が + 静かです → 부정 (어디도 조용하지 않습니다)","a":"どこも静かじゃありません","hint":"が를 も로 바꾸고 술어를 부정형으로."},{"t":"make","q":"どこ + へ + 行きます → 부정 (아무 데도 안 갑니다)","a":"どこへも行きません","hint":"へ는 남기고 그 뒤에 も, 동사는 ～ません."},{"t":"fill","q":"ねこはどこ（　）いません。","a":"にも","opts":["にも","でも","か","が"]}],"src":["https://bunpro.jp/ja/grammar_points/%E8%AA%B0%E3%81%8B-%E3%81%A9%E3%81%93%E3%81%8B-%E8%AA%B0%E3%82%82-%E3%81%A9%E3%81%93%E3%82%82"],"vf":1,"u":15,"g":1,"gp":"gg_N5_10"},{"id":"g5_115","t":"なに（何）","ko":"무엇","cat":"기타","conn":[{"w":"なに + を (목적어)","f":"なにを食べますか"},{"w":"なに + が (주어)","f":"なにが好きですか"},{"w":"なん + です (명사 술어)","f":"これはなんですか"},{"w":"なん + の + 명사","f":"なんの本ですか"},{"w":"なに + 명사 (어떤 종류)","f":"なに料理ですか"}],"rule":["何의 기본 읽기는 なに이고, を・が・に 같은 조사 앞에서는 なに로 읽는다(なにを, なにが).","뒤에 た・だ・な행 소리(です, で, の 등)가 오면 なん으로 읽는다(なにですか → なんですか).","개수·횟수를 묻는 조수사 앞에서도 なん이 된다(何人 なんにん, 何回 なんかい).","'어떤 종류의 ~'로 명사 앞에 붙을 때는 なに로 읽는 것이 많다(何料理 なにりょうり)."],"why":"なに가 본래 형태이고, なん은 발음하기 쉽게 줄어든 회화적인 형태다. 그래서 た・だ・な행 소리 앞에서 なん이 자연스럽게 쓰인다.","nu":"회화·문장 모두 쓴다. 한국어 '뭐'를 생각해 これはなにですか라고 하기 쉬운데, 보통은 これはなんですか가 자연스럽다. 같은 한자라도 읽기에 따라 뜻이 달라지는 경우가 있다(何で: なにで는 수단, なんで는 이유로 많이 쓰임). なんか는 なにか의 회화체다.","cmp":[{"g":"どれ","d":"どれ는 정해진 여러 개 중 '어느 것'. なに는 선택지 없이 '무엇'."},{"g":"なにか","d":"なにか는 '무언가'로 묻는 말이 아니라 막연한 것을 가리킨다."}],"ex":[{"jp":"これはなんですか。","ko":"이것은 무엇입니까?"},{"jp":"朝[あさ]ごはんになにを食[た]べましたか。","ko":"아침밥으로 무엇을 먹었어요?"},{"jp":"それはなんの本[ほん]ですか。","ko":"그것은 무슨 책입니까?"}],"dr":[{"t":"make","q":"何 + です + か (읽기를 가나로)","a":"なんですか","hint":"で 앞에서는 なに가 아니라 なん."},{"t":"make","q":"何 + を + 飲みますか (읽기를 가나로)","a":"なにを飲みますか","hint":"を 앞에서는 기본 읽기 なに."},{"t":"fill","q":"A：（　）が好[す]きですか。B：すしが好[す]きです。","a":"なに","opts":["なに","だれ","いつ","どこ"]}],"src":["https://community.bunpro.jp/t/topic/96800"],"vf":1,"u":15,"g":1,"gp":"gg_N5_10"},{"id":"g5_116","t":"なにか","ko":"무언가, 뭔가","cat":"기타","conn":[{"w":"なにか + 동사 (が・を 생략)","f":"なにか飲みませんか"},{"w":"なにか + 조사 (に・で 등)","f":"なにかに使います"},{"w":"なにか + 명사","f":"なにか質問がありますか"},{"w":"なにか + 형용사 + もの","f":"なにか冷たいものがほしいです"}],"rule":["의문사 なに 뒤에 か를 붙인다(なに → なにか).","주어·목적어의 が・を는 보통 생략한다(なにか飲みませんか).","に・で 같은 조사는 か 뒤에 붙인다(なにかに, なにかで).","뒤에 명사나 '형용사 + もの'를 붙여 범위를 좁힐 수 있다(なにか冷たいもの)."],"why":"의문사에 불확실함을 나타내는 か가 붙어 '무엇인지 정해지지 않은 어떤 것'이 된다. だれか, どこか, いつか와 같은 구조다.","nu":"긍정문·질문문에서 쓴다. なにか食べましたか는 '뭔가 먹었어요?'(예/아니요 질문)라서 はい/いいえ로 답하고, なにを食べましたか는 먹은 것을 묻는다. 회화에서는 なんか라고도 한다. 부정문에서 '아무것도 ~않다'는 なにも를 쓴다.","cmp":[{"g":"なに","d":"なに는 '무엇'을 묻는 의문사. なにか는 막연한 '무언가'를 가리킨다."},{"g":"なにも","d":"なにも는 부정문에서 '아무것도 (~않다)'."}],"ex":[{"jp":"なにか飲[の]みませんか。","ko":"뭔가 마시지 않을래요?"},{"jp":"なにか質問[しつもん]がありますか。","ko":"뭔가 질문이 있습니까?"},{"jp":"なにか冷[つめ]たいものが食[た]べたいです。","ko":"뭔가 차가운 것이 먹고 싶어요."}],"dr":[{"t":"make","q":"なに + 食べましたか → '뭔가 먹었어요?'","a":"なにか食べましたか","hint":"なに에 か를 붙이고 を는 생략."},{"t":"make","q":"なにか + 温かい + もの + が飲みたいです → 한 문장","a":"なにか温かいものが飲みたいです","hint":"なにか 뒤에 형용사 + もの로 범위를 좁힌다."},{"t":"fill","q":"のどがかわきました。（　）飲[の]みたいです。","a":"なにか","opts":["なにか","なにも","なんで","なにを"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei07_3.pdf","https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%AB%E3%81%8B-%E3%81%AA%E3%81%AB%E3%82%82"],"vf":1,"u":15,"g":1,"gp":"gg_N5_10"},{"id":"g5_117","t":"なにも～ないです","ko":"아무것도 ~하지 않아요","cat":"기타","conn":[{"w":"なにも + 동사 ない형 + です","f":"なにも食べないです"},{"w":"なにも + ない + です (존재)","f":"なにもないです"},{"w":"なにも + 동사 なかった + です (과거)","f":"なにもしなかったです"},{"w":"なにも + たい → たくない + です","f":"なにも食べたくないです"}],"rule":["주어·목적어의 が・を를 も로 바꾼다(なにがある → なにもない).","술어를 부정형으로 바꾼다(ある → ない, 食べる → 食べない).","정중하게 하려면 부정형 뒤에 です를 붙인다(ない → ないです).","과거는 なかった + です로 한다(なにもしなかったです)."],"why":"의문사 なに에 '~도'의 も가 붙어 '무엇이든 전부'를 가리키고, 부정과 함께 '어느 것도 ~않다'가 된다.","nu":"～ないです는 회화에서 많이 쓰는 정중형이고, 격식을 갖춘 자리나 글에서는 ～ません이 더 자연스럽다. なにも는 반드시 부정 술어와 함께 쓴다. 한국어처럼 なにもを라고 조사를 겹치지 않는다. 회화체로 なんにも, なんも라고도 한다.","cmp":[{"g":"なにも～ません","d":"뜻은 같고, ～ません이 더 격식 있는 정중형."},{"g":"なにか","d":"なにか는 긍정·질문에서 '무언가'."}],"ex":[{"jp":"冷蔵庫[れいぞうこ]になにもないです。","ko":"냉장고에 아무것도 없어요."},{"jp":"今日[きょう]はなにも食[た]べたくないです。","ko":"오늘은 아무것도 먹고 싶지 않아요."},{"jp":"きのうはなにもしなかったです。","ko":"어제는 아무것도 하지 않았어요."}],"dr":[{"t":"make","q":"なにを買う → '아무것도 안 사요' (ないです)","a":"なにも買わないです","hint":"を → も, 買う → 買わない, 뒤에 です."},{"t":"make","q":"なにがある → '아무것도 없었어요' (과거, ないです 형)","a":"なにもなかったです","hint":"が → も, ある → なかった, 뒤에 です."},{"t":"fill","q":"かばんの中[なか]には（　）ないです。","a":"なにも","opts":["なにも","なにか","なんでも","なにが"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%AB%E3%81%8B-%E3%81%AA%E3%81%AB%E3%82%82"],"vf":1,"u":15,"g":1,"gp":"gg_N5_11"},{"id":"g5_118","t":"なにも～ません","ko":"아무것도 ~하지 않습니다","cat":"기타","conn":[{"w":"なにも + 동사 ます형 + ません","f":"なにも食べません"},{"w":"なにも + 동사 ませんでした (과거)","f":"なにも食べませんでした"},{"w":"なにも + ありません (존재)","f":"なにもありません"},{"w":"なにも + 가능동사 + ません","f":"なにも見えません"}],"rule":["を・が를 も로 바꾼다(なにを → なにも).","동사는 ます형의 ます를 ません으로 바꾼다(食べます → 食べません).","과거는 ませんでした로 바꾼다(食べました → 食べませんでした).","に・で 같은 조사는 남기고 그 뒤에 も를 붙인다(なににも)."],"why":"의문사 なに + も가 부정 술어와 짝을 이루어 '어느 것도 ~않다'라는 전부 부정이 된다.","nu":"정중체로 회화·문장 모두 쓴다. も가 が・を 자리를 대신하므로 なにもを, なにもが처럼 겹치지 않는다. 긍정 술어와 함께 쓰지 않는다(なにも食べます는 틀림). 질문 なにか食べましたか에 대한 부정 대답으로 いいえ、なにも食べませんでした가 전형적이다.","cmp":[{"g":"なにも～ないです","d":"뜻은 같고 ないです는 좀 더 회화적인 정중형."},{"g":"なんでも","d":"なんでも는 긍정 술어와 '무엇이든'(なんでも食べます)."}],"ex":[{"jp":"昨日[きのう]はなにも食[た]べませんでした。","ko":"어제는 아무것도 먹지 않았습니다."},{"jp":"暗[くら]くて、なにも見[み]えません。","ko":"어두워서 아무것도 보이지 않습니다."},{"jp":"箱[はこ]の中[なか]にはなにもありません。","ko":"상자 안에는 아무것도 없습니다."}],"dr":[{"t":"make","q":"なにを飲みました → 부정 (아무것도 마시지 않았습니다)","a":"なにも飲みませんでした","hint":"を → も, ました → ませんでした."},{"t":"make","q":"なにがあります → 부정","a":"なにもありません","hint":"が → も, あります → ありません."},{"t":"fill","q":"A：なにか買[か]いましたか。B：いいえ、（　）買[か]いませんでした。","a":"なにも","opts":["なにも","なにか","なんでも","なにを"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%AB%E3%81%8B-%E3%81%AA%E3%81%AB%E3%82%82","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei07_3.pdf"],"vf":1,"u":15,"g":1,"gp":"gg_N5_11"},{"id":"g5_119","t":"なん（何）＋助数詞","ko":"몇 ~, 무슨 ~","cat":"기타","conn":[{"w":"なん + 조수사 (나이)","f":"何歳 (なんさい)"},{"w":"なん + 조수사 (사람 수)","f":"何人 (なんにん)"},{"w":"なん + 시간 단위","f":"何時 (なんじ) / 何曜日 (なんようび)"},{"w":"なん + です / の","f":"なんですか / なんの本"}],"rule":["개수·횟수·나이 등을 물을 때 조수사 앞에 なん을 둔다(なん + 歳 → 何歳).","그 뒤에 ですか를 붙여 묻는다(何歳ですか).","です・で・の 앞에서도 なに가 아니라 なん이 된다(なんですか, なんの).","같은 한자라도 '몇'의 뜻이면 なん, '어떤 종류'의 뜻이면 なに로 읽는 경우가 있다(何県: なんけん 몇 개 현, なにけん 어느 현)."],"why":"何의 본래 읽기 なに가 발음하기 쉽게 줄어든 형태가 なん이며, 수를 묻는 조수사 앞과 た・だ・な행 소리 앞에서 주로 쓰인다.","nu":"회화·문장 모두 쓴다. 나이를 정중하게 물을 때는 おいくつですか를 쓰는 것이 보통이다. 조수사에 따라 소리가 바뀌는 것이 있으니(何本 なんぼん, 何杯 なんばい) 하나씩 익혀야 한다.","cmp":[{"g":"いくつ","d":"いくつ는 조수사 없이 '몇 개/몇 살'. なん은 반드시 조수사와 함께 쓴다."},{"g":"なに","d":"を・が 앞이나 '어떤 종류'를 물을 때는 なに."}],"ex":[{"jp":"今[いま]、何時[なんじ]ですか。","ko":"지금 몇 시입니까?"},{"jp":"家族[かぞく]は何人[なんにん]ですか。","ko":"가족은 몇 명입니까?"},{"jp":"今日[きょう]は何曜日[なんようび]ですか。","ko":"오늘은 무슨 요일입니까?"}],"dr":[{"t":"make","q":"何 + 時 + ですか (읽기를 가나로)","a":"なんじですか","hint":"조수사 앞에서 何는 なん."},{"t":"make","q":"何 + 人 + 来ましたか (읽기를 가나로)","a":"なんにん来ましたか","hint":"사람 수를 물을 때 なん + にん."},{"t":"fill","q":"りんごを（　）個[こ]買[か]いましたか。","a":"なん","opts":["なん","どれ","どの","いつ"]}],"src":["https://community.bunpro.jp/t/topic/96800"],"vf":1,"u":15,"g":1,"gp":"gg_N5_11"},{"id":"g5_121","t":"なんでも～","ko":"무엇이든, 뭐든지","cat":"기타","conn":[{"w":"なんでも + 동사","f":"なんでも食べます"},{"w":"なんでも + いい/大丈夫","f":"なんでもいいです"},{"w":"なんでも + 가능 동사","f":"なんでもできます"},{"w":"なんでも + 동사 + 명사 (수식)","f":"なんでも知っている人"}],"rule":["의문사 何를 なん으로 읽고 바로 뒤에 조사 でも를 붙여 なんでも를 만든다.","なんでも는 그 자체로 '무엇이든'이라는 덩어리이므로 뒤에 が・を를 붙이지 않고 동사를 바로 쓴다(なんでも食べます).","뒤에는 긍정 표현이 온다. '아무것도 ~않다'는 なにも + 부정으로 따로 말한다."],"why":"의문사 何(무엇)에 '~라도'의 でも가 붙어 '무엇이라도 = 무엇이든'이 되었다. だれでも(누구든), どこでも(어디든), いつでも(언제든)도 같은 짜임이다.","nu":"회화·문장 모두 쓴다. なんでもいいです는 '아무거나 괜찮아요'. 문장 맨 앞의 なんでも가 '듣자 하니'라는 뜻으로 쓰이는 경우도 있지만 다른 용법이다. なんでもない(아무것도 아니다)는 관용 표현이다. 한국어 '아무것도'(부정)와 '아무거나'(긍정)를 헷갈려 なにも와 なんでも를 바꿔 쓰는 실수가 많다.","cmp":[{"g":"なにも","d":"부정문과 함께 '아무것도 ~않다'(なにも食べません). なんでも는 긍정문에서 '무엇이든'."},{"g":"なにか","d":"'무언가'(정해지지 않은 어떤 것 하나). なんでも는 '어떤 것이든 전부'."}],"ex":[{"jp":"わたしはなんでも食[た]べます。","ko":"저는 뭐든지 먹어요."},{"jp":"飲[の]み物[もの]はなんでもいいです。","ko":"음료는 아무거나 괜찮아요."},{"jp":"兄[あに]はなんでも知[し]っています。","ko":"형은 뭐든지 알고 있어요."}],"dr":[{"t":"make","q":"食べます → '뭐든지 먹어요'","a":"なんでも食べます","hint":"동사 앞에 なんでも를 두고 を는 붙이지 않는다."},{"t":"make","q":"いいです → '아무거나 괜찮아요'","a":"なんでもいいです","hint":"なん + でも 를 いいです 앞에 둔다."},{"t":"fill","q":"このレストランの料理[りょうり]は（　）おいしいです。","a":"なんでも","opts":["なんでも","なにも","なにか","なんと"]}],"src":["https://jisho.org/search/nandemo","https://tofugu.com/japanese-grammar/question-words"],"vf":1,"u":15,"g":1,"gp":"gg_N5_11"}];
